// AUTO is a policy request and never a counter index. The concrete values are
// stable across the C/Zig boundary and deliberately vary only the maximum
// number of context splits; the 32-token MMA tile and 256/256 launch widths
// remain identical to the production route.
typedef enum termite_metal_decode_gqa_split_variant {
    TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_AUTO = 0,
    TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S8 = 1,
    TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S16 = 2,
    TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S24 = 3,
    TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S32 = 4,
} termite_metal_decode_gqa_split_variant;

typedef enum termite_metal_decode_gqa_split_shape {
    TERMITE_METAL_DECODE_GQA_SPLIT_SHAPE_SWA_HD256 = 0,
    TERMITE_METAL_DECODE_GQA_SPLIT_SHAPE_GLOBAL_HD512 = 1,
} termite_metal_decode_gqa_split_shape;

typedef struct termite_metal_decode_gqa_split_schedule_stats {
    uint64_t calls[TERMITE_METAL_DECODE_GQA_SPLIT_SHAPE_COUNT][TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_COUNT];
    uint64_t fallback_calls;
    uint64_t invalid_override_count;
} termite_metal_decode_gqa_split_schedule_stats;

// Precompiled row-one Q4_0 matrix-vector variants.  The numerical body is
// identical across the portfolio; NR0 controls outputs per SIMD-group and NSG
// controls SIMD-groups per threadgroup.  AUTO is a runtime policy, while the
// four concrete values are stable diagnostic override/counter identities.
typedef enum termite_metal_q4_0_mmv_variant {
    TERMITE_METAL_Q4_0_MMV_VARIANT_AUTO = 0,
    TERMITE_METAL_Q4_0_MMV_VARIANT_LEGACY = 1,
    TERMITE_METAL_Q4_0_MMV_VARIANT_NR4_NSG2 = 2,
    TERMITE_METAL_Q4_0_MMV_VARIANT_NR8_NSG2 = 3,
    TERMITE_METAL_Q4_0_MMV_VARIANT_NR4_NSG4 = 4,
    TERMITE_METAL_Q4_0_MMV_VARIANT_NR8_NSG4 = 5,
} termite_metal_q4_0_mmv_variant;

// Semantic classes for row-one Q4_0 work. These are deliberately independent
// of tensor shape: Gemma4 reuses several dimensions across attention, FFN, and
// PLE, while the best Metal launch geometry can differ by workload. UNKNOWN is
// the fail-closed default for generic provider calls and unclassified paths.
typedef enum termite_metal_q4_0_mmv_workload {
    TERMITE_METAL_Q4_0_MMV_WORKLOAD_UNKNOWN = 0,
    TERMITE_METAL_Q4_0_MMV_WORKLOAD_ATTENTION = 1,
    TERMITE_METAL_Q4_0_MMV_WORKLOAD_FFN_GATE_UP = 2,
    TERMITE_METAL_Q4_0_MMV_WORKLOAD_FFN_DOWN = 3,
    TERMITE_METAL_Q4_0_MMV_WORKLOAD_PLE = 4,
    TERMITE_METAL_Q4_0_MMV_WORKLOAD_TAIL = 5,
    TERMITE_METAL_Q4_0_MMV_WORKLOAD_COUNT = 6,
} termite_metal_q4_0_mmv_workload;

// The row-one fused gate/up route uses the same output-row / SIMD-group
// portfolio as the independently qualified Q4_0 MMV kernels. Keep a distinct
// enum so its diagnostic override and counters cannot accidentally change the
// production single-projection policy.
typedef enum termite_metal_q4_0_pair_activation_mmv_variant {
    TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MMV_VARIANT_AUTO = 0,
    TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MMV_VARIANT_NR4_NSG2 = 1,
    TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MMV_VARIANT_NR8_NSG2 = 2,
    TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MMV_VARIANT_NR4_NSG4 = 3,
    TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MMV_VARIANT_NR8_NSG4 = 4,
} termite_metal_q4_0_pair_activation_mmv_variant;

// Fused prefill gate/up matrix-matrix candidates retain exact F32
// accumulators and differ only in their output tile width. AUTO is deliberately
// scoped to the exact M4 Gemma4 E4B FFN shape by the selector below.
typedef enum termite_metal_q4_0_pair_activation_mm_variant {
    TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MM_VARIANT_AUTO = 0,
    TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MM_VARIANT_M32_N64 = 1,
    TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MM_VARIANT_M32_N32 = 2,
} termite_metal_q4_0_pair_activation_mm_variant;

typedef struct termite_metal_jit_exact_dispatch_stats {
    uint64_t q4_0_hits;
    uint64_t q4_k_hits;
} termite_metal_jit_exact_dispatch_stats;

_Static_assert(sizeof(termite_metal_device_info) == 56, "Metal device info ABI size drift");
_Static_assert(sizeof(termite_metal_generated_pipeline_info) == 16, "Metal generated pipeline info ABI size drift");
_Static_assert(sizeof(termite_metal_jit_exact_dispatch_stats) == 16, "Metal exact dispatch stats ABI size drift");
_Static_assert(sizeof(termite_metal_decode_gqa_split_schedule_stats) == 80, "decode GQA split stats ABI size drift");
_Static_assert(offsetof(termite_metal_decode_gqa_split_schedule_stats, calls) == 0, "decode GQA split calls ABI drift");
_Static_assert(offsetof(termite_metal_decode_gqa_split_schedule_stats, fallback_calls) == 64, "decode GQA split fallback ABI drift");
_Static_assert(offsetof(termite_metal_decode_gqa_split_schedule_stats, invalid_override_count) == 72, "decode GQA split invalid override ABI drift");

#define TERMITE_METAL_PLANNED_RANGE_CAPACITY 256u

// Workload profiling is deliberately bounded and allocation-free: quantized
// matmul dispatch sits on the hottest runtime path, so recording an observed
// signature must remain a small inactive branch plus bounded open addressing.
// An incomplete census is never eligible for automatic kernel selection.
#define TERMITE_METAL_WORKLOAD_PROFILE_CAPACITY 256u
#define TERMITE_METAL_WORKLOAD_PROFILE_PROBE_LIMIT 16u

typedef enum termite_metal_workload_regime {
    TERMITE_METAL_WORKLOAD_REGIME_UNKNOWN = 0,
    TERMITE_METAL_WORKLOAD_REGIME_ENCODER = 1,
    TERMITE_METAL_WORKLOAD_REGIME_PREFILL = 2,
    TERMITE_METAL_WORKLOAD_REGIME_DECODE = 3,
    TERMITE_METAL_WORKLOAD_REGIME_SPECULATIVE_DRAFT = 4,
    TERMITE_METAL_WORKLOAD_REGIME_SPECULATIVE_VERIFY = 5,
} termite_metal_workload_regime;

typedef enum termite_metal_workload_implementation {
    TERMITE_METAL_WORKLOAD_IMPLEMENTATION_BUNDLED = 0,
    TERMITE_METAL_WORKLOAD_IMPLEMENTATION_GENERATED = 1,
} termite_metal_workload_implementation;

typedef struct termite_metal_workload_profile_entry {
    uint64_t hash;
    uint64_t call_count;
    uint64_t logical_bytes;
    uint64_t macs;
    // Zero until an explicit, isolated calibration pass supplies an estimate.
    // This is never presented as a hardware DRAM-counter measurement.
    uint64_t estimated_gpu_nanos;
    uint64_t rows;
    uint64_t in_dim;
    uint64_t out_dim;
    uint32_t format;
    uint8_t dispatch;
    uint8_t input_encoding;
    uint8_t output_encoding;
    uint8_t epilogue;
    uint8_t implementation;
    uint8_t regime;
    uint8_t fusion;
    uint8_t layout;
    uint8_t calibrated;
    uint8_t occupied;
} termite_metal_workload_profile_entry;

typedef struct termite_metal_workload_profile_snapshot {
    uint64_t dropped_signatures;
    uint64_t dropped_dispatches;
    uint64_t whole_frame_gpu_nanos;
    uint64_t profiled_frame_count;
    uint32_t entry_count;
    uint8_t active;
    uint8_t complete;
    uint8_t regime;
    uint8_t reserved;
    termite_metal_workload_profile_entry entries[TERMITE_METAL_WORKLOAD_PROFILE_CAPACITY];
} termite_metal_workload_profile_snapshot;

