static const char *termite_metal_q4_0_mmv_workload_name(
    termite_metal_q4_0_mmv_workload workload
) {
    switch (workload) {
        case TERMITE_METAL_Q4_0_MMV_WORKLOAD_UNKNOWN: return "generic";
        case TERMITE_METAL_Q4_0_MMV_WORKLOAD_ATTENTION: return "attention";
        case TERMITE_METAL_Q4_0_MMV_WORKLOAD_FFN_GATE_UP: return "ffn_gate_up";
        case TERMITE_METAL_Q4_0_MMV_WORKLOAD_FFN_DOWN: return "ffn_down";
        case TERMITE_METAL_Q4_0_MMV_WORKLOAD_PLE: return "ple";
        case TERMITE_METAL_Q4_0_MMV_WORKLOAD_TAIL: return "tail";
        case TERMITE_METAL_Q4_0_MMV_WORKLOAD_COUNT: break;
    }
    return "invalid";
}

static termite_metal_q4_0_mmv_variant termite_metal_q4_0_mmv_variant_parse(
    const char *value,
    bool *valid
) {
    if (valid != NULL) *valid = true;
    if (value == NULL || value[0] == '\0' || strcasecmp(value, "auto") == 0) {
        return TERMITE_METAL_Q4_0_MMV_VARIANT_AUTO;
    }
    if (strcasecmp(value, "legacy") == 0) return TERMITE_METAL_Q4_0_MMV_VARIANT_LEGACY;
    if (strcasecmp(value, "nr4-nsg2") == 0 || strcasecmp(value, "nr4_nsg2") == 0) {
        return TERMITE_METAL_Q4_0_MMV_VARIANT_NR4_NSG2;
    }
    if (strcasecmp(value, "nr8-nsg2") == 0 || strcasecmp(value, "nr8_nsg2") == 0) {
        return TERMITE_METAL_Q4_0_MMV_VARIANT_NR8_NSG2;
    }
    if (strcasecmp(value, "nr4-nsg4") == 0 || strcasecmp(value, "nr4_nsg4") == 0) {
        return TERMITE_METAL_Q4_0_MMV_VARIANT_NR4_NSG4;
    }
    if (strcasecmp(value, "nr8-nsg4") == 0 || strcasecmp(value, "nr8_nsg4") == 0) {
        return TERMITE_METAL_Q4_0_MMV_VARIANT_NR8_NSG4;
    }
    if (valid != NULL) *valid = false;
    return TERMITE_METAL_Q4_0_MMV_VARIANT_AUTO;
}

static void termite_metal_q4_0_mmv_parse_workload_override(
    termite_metal_decode_runtime *runtime,
    termite_metal_q4_0_mmv_workload workload,
    const char *environment_name
) {
    if (runtime == NULL ||
        workload <= TERMITE_METAL_Q4_0_MMV_WORKLOAD_UNKNOWN ||
        workload >= TERMITE_METAL_Q4_0_MMV_WORKLOAD_COUNT ||
        environment_name == NULL)
    {
        return;
    }
    bool valid = true;
    const char *value = getenv(environment_name);
    runtime->q4_0_mmv_workload_variant_overrides[workload] =
        (uint8_t)termite_metal_q4_0_mmv_variant_parse(value, &valid);
    if (!valid) {
        fprintf(
            stderr,
            "metal-runtime-create: invalid %s=%s; using auto\n",
            environment_name,
            value);
    }
}

