        case TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S8: return "s8-k32-r256";
        case TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S16: return "s16-k32-r256";
        case TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S24: return "s24-k32-r256";
