    if (value == NULL || value[0] == '\0' || strcasecmp(value, "auto") == 0) {
        return TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_AUTO;
    }
    if (strcasecmp(value, "s8-k32-r256") == 0 || strcasecmp(value, "s8") == 0 ||
        strcmp(value, "8") == 0) return TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S8;
    if (strcasecmp(value, "s16-k32-r256") == 0 || strcasecmp(value, "s16") == 0 ||
        strcmp(value, "16") == 0) return TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S16;
    if (strcasecmp(value, "s24-k32-r256") == 0 || strcasecmp(value, "s24") == 0 ||
        strcmp(value, "24") == 0) return TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S24;
    if (strcasecmp(value, "s32-k32-r256") == 0 || strcasecmp(value, "s32") == 0 ||
        strcmp(value, "32") == 0) return TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S32;
    if (valid != NULL) *valid = false;
    return TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_AUTO;
}

