           "    if ((p.dim & 31u) != 0u) return; uint row_blocks = p.dim / 32u; uint total_blocks = p.total * row_blocks; if (gid >= total_blocks) return; uint row = gid / row_blocks; uint block = gid - row * row_blocks; uint target_row = ids[row]; if (target_row >= p.source_rows) return; uint input_base = row * p.dim + block * 32u; float max_abs = 0.0f; for (uint i = 0u; i < 32u; ++i) max_abs = fmax(max_abs, fabs(input[input_base + i] * p.scale)); float d = max_abs == 0.0f ? 1.0f : max_abs / 8.0f; float inv = max_abs == 0.0f ? 0.0f : 1.0f / d; uint off = (target_row * row_blocks + block) * 18u; ushort bits = as_type<ushort>(half(d)); weight[off] = uchar(bits & 0xffu); weight[off + 1u] = uchar((bits >> 8) & 0xffu); for (uint i = 0u; i < 16u; ++i) { uint lo = uint(clamp(round(input[input_base + i] * p.scale * inv + 8.0f), 0.0f, 15.0f)); uint hi = uint(clamp(round(input[input_base + 16u + i] * p.scale * inv + 8.0f), 0.0f, 15.0f)); weight[off + 2u + i] = uchar(lo | (hi << 4)); }\n"
