	           "    }\n"
	           "    if (row < p.rows && col0 < p.out_dim) output[row * p.out_dim + col0] = acc0;\n"
	           "    if (row < p.rows && col1 < p.out_dim) output[row * p.out_dim + col1] = acc1;\n"
	           "    if (row < p.rows && col2 < p.out_dim) output[row * p.out_dim + col2] = acc2;\n"
