           "    }\n"
           "    if (!(best_scaled > -INFINITY)) { output[0] = 0u; return; }\n"
           "    if (p.temperature <= 0.0f) { output[0] = best_idx; return; }\n"
           "    float sum = 0.0f;\n"
           "    float max_prob = 0.0f;\n"
           "    if (candidate_count != 0u) {\n"
           "        for (uint i = 0u; i < candidate_count; ++i) {\n"
