static id<MTLBuffer> termite_metal_make_private_buffer_with_bytes(
    id<MTLDevice> device,
    id<MTLCommandQueue> queue,
    const void *bytes,
    size_t length
) {
    if (device == nil || queue == nil || bytes == NULL || length == 0) return nil;
    @autoreleasepool {
        id<MTLBuffer> staging = [device newBufferWithBytes:bytes length:length options:MTLResourceStorageModeShared];
        if (staging == nil) return nil;
        id<MTLBuffer> dst = [device newBufferWithLength:length options:MTLResourceStorageModePrivate];
        if (dst == nil) return nil;
        id<MTLCommandBuffer> command_buffer = termite_metal_new_command_buffer(queue, __func__);
        if (command_buffer == nil) return nil;
        termite_metal_record_active_frame_blit_source(command_buffer, TERMITE_METAL_BLIT_SOURCE_OTHER);
        id<MTLBlitCommandEncoder> blit = termite_metal_tracked_blit_command_encoder(command_buffer);
        if (blit == nil) return nil;
        if ([blit respondsToSelector:@selector(setLabel:)]) {
            blit.label = @"private-buffer-upload";
        }
        [blit copyFromBuffer:staging sourceOffset:0 toBuffer:dst destinationOffset:0 size:length];
        [blit endEncoding];
        return termite_metal_commit_and_wait(command_buffer, __func__, -1) == 0 ? dst : nil;
    }
}

static bool termite_metal_can_make_no_copy_buffer(const void *bytes, size_t length) {
    if (bytes == NULL || length == 0) return false;
    long page_size = sysconf(_SC_PAGESIZE);
    if (page_size <= 0) page_size = 4096;
    const uintptr_t ptr = (uintptr_t)bytes;
    const uintptr_t page = (uintptr_t)page_size;
    return (ptr % page) == 0 && (length % (size_t)page_size) == 0;
}

typedef struct termite_metal_host_staging_slice {
    id<MTLBuffer> buffer;
    size_t offset;
} termite_metal_host_staging_slice;

static size_t termite_metal_align_forward_size(size_t value, size_t alignment) {
    if (alignment <= 1) return value;
    const size_t mask = alignment - 1;
    if ((alignment & mask) != 0) return value;
    if (value > SIZE_MAX - mask) return SIZE_MAX;
    return (value + mask) & ~mask;
}

static int termite_metal_decode_runtime_ensure_host_staging_buffer(
    termite_metal_decode_runtime *runtime,
    bool frame_owned,
    size_t required
) {
    if (runtime == NULL || runtime->device == nil || required == 0) return -1;
    id<MTLBuffer> current_buffer = frame_owned ? runtime->host_staging_buffer : runtime->active_frame_host_staging_buffer;
    size_t current_capacity = frame_owned ? runtime->host_staging_capacity : runtime->active_frame_host_staging_capacity;
    if (current_buffer != nil && current_capacity >= required) return 0;

    size_t new_capacity = current_capacity;
    if (new_capacity < 4096) new_capacity = 4096;
    while (new_capacity < required) {
        if (new_capacity > SIZE_MAX / 2) {
            new_capacity = required;
            break;
        }
        new_capacity *= 2;
    }

    id<MTLBuffer> new_buffer = [runtime->device newBufferWithLength:new_capacity options:MTLResourceStorageModeShared];
    if (new_buffer == nil) return -2;
    if (frame_owned) {
        runtime->host_staging_buffer = new_buffer;
        runtime->host_staging_capacity = new_capacity;
    } else {
        runtime->active_frame_host_staging_buffer = new_buffer;
        runtime->active_frame_host_staging_capacity = new_capacity;
        runtime->frame_host_staging_buffers[runtime->frame_host_staging_index & 1u] = new_buffer;
        runtime->frame_host_staging_capacities[runtime->frame_host_staging_index & 1u] = new_capacity;
    }
    return 0;
}

static int termite_metal_decode_runtime_stage_host_bytes(
    termite_metal_decode_runtime *runtime,
    const void *bytes,
    size_t length,
    bool frame_owned,
    termite_metal_host_staging_slice *slice
) {
    if (runtime == NULL || bytes == NULL || length == 0 || slice == NULL) return -1;
    const size_t alignment = 256;
    size_t offset = 0;
    if (!frame_owned) {
        offset = termite_metal_align_forward_size(runtime->active_frame_host_staging_offset, alignment);
        if (offset == SIZE_MAX || length > SIZE_MAX - offset) return -2;
    }
    const size_t required = offset + length;
    if (termite_metal_decode_runtime_ensure_host_staging_buffer(runtime, frame_owned, required) != 0) return -3;

    id<MTLBuffer> buffer = frame_owned ? runtime->host_staging_buffer : runtime->active_frame_host_staging_buffer;
    if (buffer == nil || buffer.contents == NULL || offset + length > buffer.length) return -4;
    memcpy((uint8_t *)buffer.contents + offset, bytes, length);
    if (buffer.storageMode == MTLStorageModeManaged) {
        [buffer didModifyRange:NSMakeRange(offset, length)];
    }

    if (!frame_owned) {
        runtime->active_frame_host_staging_offset = termite_metal_align_forward_size(required, alignment);
        if (runtime->active_frame_host_staging_offset == SIZE_MAX) return -5;
        if (runtime->active_frame_host_staging_retained_buffer != buffer) {
            if (termite_metal_decode_runtime_retain_frame_resource(runtime, buffer) != 0) return -6;
            runtime->active_frame_host_staging_retained_buffer = buffer;
        }
    }

    slice->buffer = buffer;
    slice->offset = offset;
    return 0;
}

static int termite_metal_upload_private_buffer(
    id<MTLDevice> device,
    id<MTLCommandQueue> queue,
    id<MTLBuffer> dst,
    const void *bytes,
    size_t length
) {
    if (device == nil || queue == nil || dst == nil || bytes == NULL || length == 0) return -1;
    @autoreleasepool {
        if (dst.length < length) return -2;
        id<MTLBuffer> staging = [device newBufferWithBytes:bytes length:length options:MTLResourceStorageModeShared];
        if (staging == nil) return -3;
        id<MTLCommandBuffer> command_buffer = termite_metal_new_command_buffer(queue, __func__);
        if (command_buffer == nil) return -4;
        termite_metal_record_active_frame_blit_source(command_buffer, TERMITE_METAL_BLIT_SOURCE_OTHER);
        id<MTLBlitCommandEncoder> blit = termite_metal_tracked_blit_command_encoder(command_buffer);
        if (blit == nil) return -5;
        if ([blit respondsToSelector:@selector(setLabel:)]) {
            blit.label = @"private-buffer-upload";
        }
        [blit copyFromBuffer:staging sourceOffset:0 toBuffer:dst destinationOffset:0 size:length];
        [blit endEncoding];
        return termite_metal_commit_and_wait(command_buffer, __func__, -6);
    }
}

static void termite_metal_decode_runtime_memory_add_buffer(
    termite_metal_decode_runtime_memory_stats *snapshot,
    id<MTLBuffer> buffer,
    uint64_t *category
) {
    if (snapshot == NULL || buffer == nil) return;
    const uint64_t bytes = (uint64_t)buffer.length;
    snapshot->buffer_count += 1;
    snapshot->total_bytes += bytes;
    switch (buffer.storageMode) {
        case MTLStorageModePrivate:
            snapshot->private_bytes += bytes;
            break;
        case MTLStorageModeShared:
            snapshot->shared_bytes += bytes;
            break;
#if TARGET_OS_OSX
        case MTLStorageModeManaged:
            snapshot->managed_bytes += bytes;
            break;
#endif
        default:
            break;
    }
    if (category != NULL) {
        *category += bytes;
    }
}

static void termite_metal_decode_runtime_memory_add_resources(
    termite_metal_decode_runtime_memory_stats *snapshot,
    CFMutableArrayRef resources,
    uint64_t *category
) {
    if (snapshot == NULL || resources == NULL) return;
    const CFIndex count = CFArrayGetCount(resources);
    for (CFIndex i = 0; i < count; ++i) {
        id resource = (__bridge id)CFArrayGetValueAtIndex(resources, i);
        if ([resource conformsToProtocol:@protocol(MTLBuffer)]) {
            termite_metal_decode_runtime_memory_add_buffer(snapshot, (id<MTLBuffer>)resource, category);
        }
    }
}

// Encoder-frame routing is thread-local so independent model runtimes cannot
// redirect each other's command encoders. Serving code additionally
// serializes execution for each stateful model runtime.
static _Thread_local termite_metal_decode_runtime *termite_metal_active_encoder_runtime = NULL;

static bool termite_metal_trace_unscoped_compute_enabled(void) {
    const char *enabled = getenv("TERMITE_METAL_TRACE_UNSCOPED_COMPUTE");
    return enabled != NULL && enabled[0] != '\0' && strcmp(enabled, "0") != 0;
}

static bool termite_metal_trace_frame_blits_enabled(void) {
    const char *enabled = getenv("TERMITE_METAL_TRACE_FRAME_BLITS");
    return enabled != NULL && enabled[0] != '\0' && strcmp(enabled, "0") != 0;
}

static bool termite_metal_trace_frame_lifecycle_enabled(void) {
    const char *enabled = getenv("TERMITE_METAL_TRACE_FRAME_LIFECYCLE");
    return enabled != NULL && enabled[0] != '\0' && strcmp(enabled, "0") != 0;
}

static bool termite_metal_prepared_frame_diagnostics_enabled(void) {
    return termite_metal_env_flag_enabled(getenv("TERMITE_METAL_FORCE_DIAGNOSTIC_COMMAND_BUFFERS")) ||
        termite_metal_trace_unscoped_compute_enabled() ||
        termite_metal_trace_frame_blits_enabled() ||
        termite_metal_trace_frame_lifecycle_enabled() ||
        termite_metal_env_flag_enabled(getenv("TERMITE_METAL_TRACE_FRAME")) ||
        termite_metal_env_flag_enabled(getenv("MTL_DEBUG_LAYER")) ||
        termite_metal_env_flag_enabled(getenv("MTL_CAPTURE_ENABLED"));
}

static uint64_t termite_metal_env_bounded_u64(
    const char *name,
    uint64_t fallback,
    uint64_t minimum,
    uint64_t maximum
) {
    const char *value = getenv(name);
    if (value == NULL || value[0] == '\0') return fallback;
    char *end = NULL;
    errno = 0;
    const unsigned long long parsed = strtoull(value, &end, 10);
    if (errno != 0 || end == value || *end != '\0') return fallback;
    if ((uint64_t)parsed < minimum) return minimum;
    if ((uint64_t)parsed > maximum) return maximum;
    return (uint64_t)parsed;
}

static id<MTLCounterSet> termite_metal_timestamp_counter_set(id<MTLDevice> device) {
    if (device == nil) return nil;
    for (id<MTLCounterSet> counter_set in device.counterSets) {
        if ([counter_set.name isEqualToString:MTLCommonCounterSetTimestamp]) return counter_set;
    }
    return nil;
}

static void termite_metal_stage_sample_frame_reset(termite_metal_stage_sample_frame *frame) {
    if (frame == NULL) return;
    frame->buffer = nil;
    frame->regime = 0;
    frame->selected = 0;
    frame->complete = 0;
    frame->has_current_bucket = 0;
    frame->sample_count = 0;
    frame->current_bucket = 0;
    frame->reserved = 0;
    memset(frame->interval_buckets, 0, sizeof(frame->interval_buckets));
}

static void termite_metal_stage_timing_initialize(termite_metal_decode_runtime *runtime) {
    if (runtime == NULL) return;
    memset(&runtime->stage_timing, 0, sizeof(runtime->stage_timing));
    termite_metal_stage_sample_frame_reset(&runtime->active_stage_sample);
    termite_metal_stage_sample_frame_reset(&runtime->submitted_stage_sample);
    runtime->stage_timing_prefill_max = termite_metal_env_bounded_u64(
        "TERMITE_METAL_STAGE_TIMING_PREFILL_MAX", 1, 0, 8);
    runtime->stage_timing_decode_start = termite_metal_env_bounded_u64(
        "TERMITE_METAL_STAGE_TIMING_DECODE_START", 32, 0, UINT32_MAX);
    runtime->stage_timing_decode_stride = termite_metal_env_bounded_u64(
        "TERMITE_METAL_STAGE_TIMING_DECODE_STRIDE", 64, 1, UINT32_MAX);
    runtime->stage_timing_decode_max = termite_metal_env_bounded_u64(
        "TERMITE_METAL_STAGE_TIMING_DECODE_MAX", 5, 0, 16);
    runtime->active_frame_regime = TERMITE_METAL_FRAME_REGIME_NONE;
    if (!termite_metal_env_flag_enabled(getenv("TERMITE_METAL_STAGE_TIMING"))) return;
    runtime->stage_timing.enabled = 1;
    runtime->stage_timestamp_counter_set = termite_metal_timestamp_counter_set(runtime->device);
    if (runtime->stage_timestamp_counter_set == nil ||
        ![runtime->device supportsCounterSampling:MTLCounterSamplingPointAtDispatchBoundary])
    {
        runtime->stage_timing.supported = 0;
        runtime->stage_timing.complete = 0;
        fprintf(stderr, "metal-stage-timing: timestamp dispatch-boundary counters unsupported\n");
        return;
    }
    runtime->stage_timing.supported = 1;
    runtime->stage_timing.complete = 1;
}

static void termite_metal_stage_timing_fail_frame(
    termite_metal_decode_runtime *runtime,
    termite_metal_stage_sample_frame *frame,
    uint64_t *counter
) {
    if (runtime == NULL || frame == NULL) return;
    if (counter != NULL && *counter != UINT64_MAX) *counter += 1;
    if (runtime->stage_timing.dropped_frames != UINT64_MAX) runtime->stage_timing.dropped_frames += 1;
    runtime->stage_timing.complete = 0;
    frame->complete = 0;
}

static void termite_metal_stage_timing_prepare_active_frame(
    termite_metal_decode_runtime *runtime,
    termite_metal_frame_regime regime
) {
    if (runtime == NULL) return;
    runtime->active_frame_regime = (uint8_t)regime;
    termite_metal_stage_sample_frame_reset(&runtime->active_stage_sample);
    if (runtime->stage_timing.enabled == 0 || runtime->stage_timing.supported == 0) return;

    bool selected = false;
    if (regime == TERMITE_METAL_FRAME_REGIME_PREFILL) {
        const uint64_t ordinal = runtime->stage_timing_prefill_seen++;
        selected = ordinal < runtime->stage_timing_prefill_max &&
            runtime->stage_timing_prefill_selected < runtime->stage_timing_prefill_max;
        if (selected) runtime->stage_timing_prefill_selected += 1;
    } else if (regime == TERMITE_METAL_FRAME_REGIME_DECODE) {
        const uint64_t ordinal = runtime->stage_timing_decode_seen++;
        selected = runtime->stage_timing_decode_selected < runtime->stage_timing_decode_max &&
            ordinal >= runtime->stage_timing_decode_start &&
            ((ordinal - runtime->stage_timing_decode_start) % runtime->stage_timing_decode_stride) == 0;
        if (selected) runtime->stage_timing_decode_selected += 1;
    }
    if (!selected) return;

    MTLCounterSampleBufferDescriptor *descriptor = [[MTLCounterSampleBufferDescriptor alloc] init];
    descriptor.counterSet = runtime->stage_timestamp_counter_set;
    descriptor.storageMode = MTLStorageModeShared;
    descriptor.sampleCount = TERMITE_METAL_STAGE_SAMPLE_CAPACITY;
    NSError *error = nil;
    id<MTLCounterSampleBuffer> buffer = [runtime->device newCounterSampleBufferWithDescriptor:descriptor error:&error];
    if (buffer == nil) {
        termite_metal_stage_timing_fail_frame(
            runtime,
            &runtime->active_stage_sample,
            &runtime->stage_timing.allocation_failures);
        fprintf(
            stderr,
            "metal-stage-timing: counter sample buffer allocation failed%s%s\n",
            error.localizedDescription != nil ? ": " : "",
            error.localizedDescription != nil ? error.localizedDescription.UTF8String : "");
        return;
    }
    runtime->active_stage_sample.buffer = buffer;
    runtime->active_stage_sample.regime = (uint8_t)regime;
    runtime->active_stage_sample.selected = 1;
    runtime->active_stage_sample.complete = 1;
}

static void termite_metal_stage_timing_sample_boundary(
    termite_metal_decode_runtime *runtime,
    id<MTLComputeCommandEncoder> encoder,
    termite_metal_stage_bucket bucket,
    bool force
) {
    if (runtime == NULL || encoder == nil) return;
    termite_metal_stage_sample_frame *frame = &runtime->active_stage_sample;
    if (frame->selected == 0 || frame->complete == 0 || frame->buffer == nil) return;
    if (!force && frame->has_current_bucket != 0 && frame->current_bucket == (uint8_t)bucket) return;
    if (frame->sample_count >= TERMITE_METAL_STAGE_SAMPLE_CAPACITY) {
        termite_metal_stage_timing_fail_frame(runtime, frame, &runtime->stage_timing.overflow_failures);
        return;
    }
    const uint16_t index = frame->sample_count;
    [encoder sampleCountersInBuffer:frame->buffer atSampleIndex:index withBarrier:YES];
    runtime->stage_timing.barrier_sample_count = termite_metal_u64_saturating_add(
        runtime->stage_timing.barrier_sample_count,
        1);
    frame->interval_buckets[index] = (uint8_t)bucket;
    frame->sample_count = index + 1;
    frame->current_bucket = (uint8_t)bucket;
    frame->has_current_bucket = 1;
}

static termite_metal_stage_bucket termite_metal_stage_bucket_for_region(size_t region) {
    switch (region) {
        case TERMITE_METAL_COMPUTE_REGION_ATTENTION:
        case TERMITE_METAL_COMPUTE_REGION_ATTENTION_PROJECT:
            return TERMITE_METAL_STAGE_ATTENTION;
        case TERMITE_METAL_COMPUTE_REGION_FFN_NORM:
        case TERMITE_METAL_COMPUTE_REGION_FFN:
            return TERMITE_METAL_STAGE_FFN;
        case TERMITE_METAL_COMPUTE_REGION_PLE:
            return TERMITE_METAL_STAGE_PLE;
        case TERMITE_METAL_COMPUTE_REGION_TAIL:
            return TERMITE_METAL_STAGE_TAIL;
        case TERMITE_METAL_COMPUTE_REGION_EMBEDDING:
            return TERMITE_METAL_STAGE_EMBEDDING;
        default:
            return TERMITE_METAL_STAGE_OTHER;
    }
}

static termite_metal_stage_bucket termite_metal_stage_bucket_for_plan_op(uint16_t kind) {
    if (kind >= TERMITE_METAL_PLAN_OP_DECODE_ATTENTION_PRE_NORM &&
        kind <= TERMITE_METAL_PLAN_OP_DECODE_ATTENTION_POST_NORM_RESIDUAL)
    {
        return TERMITE_METAL_STAGE_ATTENTION;
    }
    if (kind >= TERMITE_METAL_PLAN_OP_DECODE_FFN_PRE_NORM_SCALE &&
        kind <= TERMITE_METAL_PLAN_OP_DECODE_FFN_POST_NORM_RESIDUAL)
    {
        return TERMITE_METAL_STAGE_FFN;
    }
    if (kind >= TERMITE_METAL_PLAN_OP_DECODE_PLE_GATE_ACTIVATION &&
        kind <= TERMITE_METAL_PLAN_OP_DECODE_PLE_POST_NORM_RESIDUAL)
    {
        return TERMITE_METAL_STAGE_PLE;
    }
    if (kind >= TERMITE_METAL_PLAN_OP_DECODE_TAIL_FINAL_NORM &&
        kind <= TERMITE_METAL_PLAN_OP_DECODE_TAIL_ARGMAX)
    {
        return TERMITE_METAL_STAGE_TAIL;
    }
    return TERMITE_METAL_STAGE_OTHER;
}

static bool termite_metal_stage_timing_add_overflows(uint64_t lhs, uint64_t rhs) {
    return UINT64_MAX - lhs < rhs;
}

static void termite_metal_stage_timing_resolve_submitted_frame(
    termite_metal_decode_runtime *runtime,
    uint64_t whole_frame_gpu_nanos,
    bool command_buffer_completed
) {
    if (runtime == NULL) return;
    termite_metal_stage_sample_frame *frame = &runtime->submitted_stage_sample;
    if (frame->selected == 0) return;
    if (frame->complete == 0) {
        termite_metal_stage_sample_frame_reset(frame);
        return;
    }
    if (!command_buffer_completed || frame->buffer == nil || frame->sample_count < 2) {
        termite_metal_stage_timing_fail_frame(runtime, frame, &runtime->stage_timing.resolve_failures);
        termite_metal_stage_sample_frame_reset(frame);
        return;
    }
    NSData *resolved = [frame->buffer resolveCounterRange:NSMakeRange(0, frame->sample_count)];
    const size_t expected_bytes = (size_t)frame->sample_count * sizeof(MTLCounterResultTimestamp);
    if (resolved == nil || resolved.length != expected_bytes) {
        termite_metal_stage_timing_fail_frame(runtime, frame, &runtime->stage_timing.resolve_failures);
        termite_metal_stage_sample_frame_reset(frame);
        return;
    }
    const MTLCounterResultTimestamp *timestamps = (const MTLCounterResultTimestamp *)resolved.bytes;
    uint64_t raw[TERMITE_METAL_STAGE_BUCKET_COUNT] = {0};
    uint64_t total_ticks = 0;
    for (uint16_t index = 0; index + 1 < frame->sample_count; ++index) {
        const uint64_t start = timestamps[index].timestamp;
        const uint64_t end = timestamps[index + 1].timestamp;
        const uint8_t bucket = frame->interval_buckets[index];
        if (start == MTLCounterErrorValue || end == MTLCounterErrorValue || end <= start ||
            bucket >= TERMITE_METAL_STAGE_BUCKET_COUNT ||
            termite_metal_stage_timing_add_overflows(raw[bucket], end - start) ||
            termite_metal_stage_timing_add_overflows(total_ticks, end - start))
        {
            termite_metal_stage_timing_fail_frame(runtime, frame, &runtime->stage_timing.resolve_failures);
            termite_metal_stage_sample_frame_reset(frame);
            return;
        }
        raw[bucket] += end - start;
        total_ticks += end - start;
    }
    if (total_ticks == 0 || whole_frame_gpu_nanos == 0) {
        termite_metal_stage_timing_fail_frame(runtime, frame, &runtime->stage_timing.resolve_failures);
        termite_metal_stage_sample_frame_reset(frame);
        return;
    }

    uint64_t apportioned[TERMITE_METAL_STAGE_BUCKET_COUNT] = {0};
    uint64_t remainders[TERMITE_METAL_STAGE_BUCKET_COUNT] = {0};
    uint64_t apportioned_total = 0;
    for (size_t bucket = 0; bucket < TERMITE_METAL_STAGE_BUCKET_COUNT; ++bucket) {
        const __uint128_t product = (__uint128_t)whole_frame_gpu_nanos * raw[bucket];
        apportioned[bucket] = (uint64_t)(product / total_ticks);
        remainders[bucket] = (uint64_t)(product % total_ticks);
        apportioned_total += apportioned[bucket];
    }
    uint64_t remaining = whole_frame_gpu_nanos - apportioned_total;
    while (remaining != 0) {
        size_t best = 0;
        for (size_t bucket = 1; bucket < TERMITE_METAL_STAGE_BUCKET_COUNT; ++bucket) {
            if (remainders[bucket] > remainders[best]) best = bucket;
        }
        apportioned[best] += 1;
        remainders[best] = 0;
        remaining -= 1;
    }

    termite_metal_stage_regime_timing *target = NULL;
    if (frame->regime == TERMITE_METAL_FRAME_REGIME_PREFILL) target = &runtime->stage_timing.prefill;
    if (frame->regime == TERMITE_METAL_FRAME_REGIME_DECODE) target = &runtime->stage_timing.decode;
    bool overflow = target == NULL || target->sampled_frames == UINT64_MAX ||
        termite_metal_stage_timing_add_overflows(target->whole_frame_gpu_nanos, whole_frame_gpu_nanos);
    if (!overflow) {
        for (size_t bucket = 0; bucket < TERMITE_METAL_STAGE_BUCKET_COUNT; ++bucket) {
            if (termite_metal_stage_timing_add_overflows(target->bucket_nanos[bucket], apportioned[bucket])) {
                overflow = true;
                break;
            }
        }
    }
    if (overflow) {
        termite_metal_stage_timing_fail_frame(runtime, frame, &runtime->stage_timing.overflow_failures);
        termite_metal_stage_sample_frame_reset(frame);
        return;
    }
    target->sampled_frames += 1;
    target->whole_frame_gpu_nanos += whole_frame_gpu_nanos;
    for (size_t bucket = 0; bucket < TERMITE_METAL_STAGE_BUCKET_COUNT; ++bucket) {
        target->bucket_nanos[bucket] += apportioned[bucket];
    }
    termite_metal_stage_sample_frame_reset(frame);
}

static bool termite_metal_coalesce_planned_compute_encoders_enabled(void) {
    const char *disabled = getenv("TERMITE_METAL_DISABLE_PLANNED_ENCODER_COALESCING");
    return disabled == NULL || disabled[0] == '\0' || strcmp(disabled, "0") == 0;
}

static bool termite_metal_concurrent_planned_dispatch_policy(
    bool requested,
    bool force_enabled,
    bool force_disabled
) {
    // The experimental encoder remains fail-closed.  A caller-owned request
    // or explicit environment opt-in is required, and the kill switch always
    // wins.  Capturing these values per runtime avoids process-global policy
    // races between independently configured model instances.
    return !force_disabled && (requested || force_enabled);
}

static void termite_metal_refresh_concurrent_planned_dispatch_policy(
    termite_metal_decode_runtime *runtime
) {
    if (runtime == NULL) return;
    runtime->concurrent_planned_dispatch_enabled =
        termite_metal_concurrent_planned_dispatch_policy(
            runtime->concurrent_planned_dispatch_requested,
            runtime->concurrent_planned_dispatch_force_enabled,
            runtime->concurrent_planned_dispatch_force_disabled);
}

static bool termite_metal_concurrent_planned_dispatch_enabled(
    const termite_metal_decode_runtime *runtime
) {
    return runtime != NULL && runtime->concurrent_planned_dispatch_enabled;
}

static bool termite_metal_planned_compute_barriers_enabled(termite_metal_decode_runtime *runtime) {
    // Concurrent dispatch relies on range-tracked barriers for correctness, so
    // they cannot be disabled or suppressed in that mode.
    if (termite_metal_concurrent_planned_dispatch_enabled(runtime)) return true;
    const char *disabled = getenv("TERMITE_METAL_DISABLE_PLANNED_COMPUTE_BARRIERS");
    if (disabled != NULL && disabled[0] != '\0' && strcmp(disabled, "0") != 0) return false;
    if (runtime != NULL && runtime->planned_compute_barrier_suppression_depth != 0) return false;
    return true;
}

static bool termite_metal_planned_access_profile_enabled(void) {
    const char *enabled = getenv("TERMITE_METAL_PLANNED_ACCESS_PROFILE");
    return enabled != NULL && enabled[0] != '\0' && strcmp(enabled, "0") != 0;
}

static bool termite_metal_paged_attention_1x_enabled(void) {
    const char *disabled = getenv("TERMITE_METAL_DISABLE_PAGED_ATTENTION_1X");
    return disabled == NULL || disabled[0] == '\0' || strcmp(disabled, "0") == 0;
}

static bool termite_metal_decode_gqa_split_environment_enabled(void) {
    const char *enabled = getenv("TERMITE_METAL_ENABLE_DECODE_GQA_SPLIT");
    return (enabled == NULL || termite_metal_env_flag_enabled(enabled)) &&
        !termite_metal_env_flag_enabled(getenv("TERMITE_METAL_DISABLE_DECODE_GQA_SPLIT"));
}

static void termite_metal_decode_runtime_reset_planned_compute_ranges(termite_metal_decode_runtime *runtime) {
    if (runtime == NULL) return;
    runtime->active_planned_compute_range_count = 0;
}

static void termite_metal_decode_runtime_reset_planned_access_profile(termite_metal_decode_runtime *runtime) {
    if (runtime == NULL) return;
    runtime->active_frame_planned_access_prepare_calls = 0;
    runtime->active_frame_planned_access_ranges = 0;
    runtime->active_frame_planned_access_range_scans = 0;
    runtime->active_frame_planned_access_conflicts = 0;
    runtime->active_frame_planned_access_capacity_flushes = 0;
    runtime->active_frame_planned_access_barriers = 0;
    runtime->active_frame_planned_access_nanos = 0;
}

static void termite_metal_decode_runtime_print_planned_access_profile(termite_metal_decode_runtime *runtime) {
    if (runtime == NULL || !termite_metal_planned_access_profile_enabled()) return;
    const uint64_t calls = runtime->active_frame_planned_access_prepare_calls;
    if (calls == 0) return;
    const double total_ms = (double)runtime->active_frame_planned_access_nanos / 1000000.0;
    const double avg_us = (double)runtime->active_frame_planned_access_nanos / (double)calls / 1000.0;
    fprintf(
        stderr,
        "metal_planned_access_profile: calls=%llu:accesses=%llu:range_scans=%llu:conflicts=%llu:capacity_flushes=%llu:barriers=%llu:total_ms=%.3f:avg_us=%.3f\n",
        (unsigned long long)runtime->active_frame_planned_access_prepare_calls,
        (unsigned long long)runtime->active_frame_planned_access_ranges,
        (unsigned long long)runtime->active_frame_planned_access_range_scans,
        (unsigned long long)runtime->active_frame_planned_access_conflicts,
        (unsigned long long)runtime->active_frame_planned_access_capacity_flushes,
        (unsigned long long)runtime->active_frame_planned_access_barriers,
        total_ms,
        avg_us
    );
}

static bool termite_metal_size_mul(size_t a, size_t b, size_t *out) {
    if (out == NULL) return false;
    if (a != 0 && b > SIZE_MAX / a) return false;
    *out = a * b;
    return true;
}

static bool termite_metal_size_mul3(size_t a, size_t b, size_t c, size_t *out) {
    size_t ab = 0;
    return termite_metal_size_mul(a, b, &ab) && termite_metal_size_mul(ab, c, out);
}

static bool termite_metal_size_add(size_t a, size_t b, size_t *out) {
    if (out == NULL || b > SIZE_MAX - a) return false;
    *out = a + b;
    return true;
}

static size_t termite_metal_dense_qkv_pack_cache_max_bytes(void) {
    const char *value = getenv("TERMITE_METAL_DENSE_QKV_PACK_CACHE_MAX_MB");
    if (value == NULL || value[0] == '\0') {
        return (size_t)TERMITE_METAL_DENSE_QKV_PACK_CACHE_DEFAULT_MAX_MB * 1024u * 1024u;
    }
    char *end = NULL;
    const unsigned long long mb = strtoull(value, &end, 10);
    if (end == value || end == NULL || end[0] != '\0') {
        return (size_t)TERMITE_METAL_DENSE_QKV_PACK_CACHE_DEFAULT_MAX_MB * 1024u * 1024u;
    }
    if (mb > (unsigned long long)(SIZE_MAX / (1024u * 1024u))) return SIZE_MAX;
    return (size_t)mb * 1024u * 1024u;
}

static size_t termite_metal_deberta_mps_attention_scratch_max_bytes(void) {
    if (termite_metal_env_flag_enabled(getenv("TERMITE_METAL_DISABLE_DEBERTA_MPS_ATTENTION"))) return 0;
    const uint64_t max_mb = termite_metal_env_bounded_u64(
        "TERMITE_METAL_DEBERTA_MPS_ATTENTION_MAX_MB",
        TERMITE_METAL_DEBERTA_MPS_ATTENTION_DEFAULT_MAX_MB,
        0,
        (uint64_t)(SIZE_MAX / (1024u * 1024u))
    );
    return (size_t)max_mb * 1024u * 1024u;
}

static bool termite_metal_buffer_range_valid(id<MTLBuffer> buffer, size_t offset, size_t byte_count) {
    if (buffer == nil) return false;
    return offset <= buffer.length && byte_count <= buffer.length - offset;
}

static int termite_metal_planned_range_make(
    id<MTLBuffer> buffer,
    size_t offset,
    size_t byte_count,
    termite_metal_planned_range_type type,
    termite_metal_planned_encoder_range *out,
    int failure_code
) {
    if (out == NULL) return failure_code;
    out->buffer = nil;
    out->begin = 0;
    out->end = 0;
    out->type = type;
    if (buffer == nil || byte_count == 0) return 0;
    if (offset > buffer.length || byte_count > buffer.length - offset) return failure_code;
    out->buffer = buffer;
    out->begin = offset;
    out->end = offset + byte_count;
    return 0;
}

static bool termite_metal_planned_ranges_hazard(
    size_t a_begin,
    size_t a_end,
    termite_metal_planned_range_type a_type,
    size_t b_begin,
    size_t b_end,
    termite_metal_planned_range_type b_type
) {
    if (a_begin >= a_end || b_begin >= b_end) return false;
    if (a_type == TERMITE_METAL_PLANNED_RANGE_READ && b_type == TERMITE_METAL_PLANNED_RANGE_READ) return false;
    return a_begin < b_end && b_begin < a_end;
}

static bool termite_metal_planned_ranges_overlap(
    const termite_metal_planned_encoder_range *a,
    const termite_metal_planned_encoder_range *b
) {
    if (a == NULL || b == NULL || a->buffer == nil || b->buffer == nil) return false;
    if (a->buffer != b->buffer) return false;
    return termite_metal_planned_ranges_hazard(a->begin, a->end, a->type, b->begin, b->end, b->type);
}

static int termite_metal_decode_runtime_prepare_planned_compute_accesses(
    termite_metal_decode_runtime *runtime,
    const termite_metal_planned_encoder_range *accesses,
    size_t access_count,
    int failure_code
) {
    if (runtime == NULL || accesses == NULL || access_count == 0) return 0;
    if (runtime->active_frame_cb == nil || runtime->active_planned_compute_encoder == nil) return 0;

    const bool collect_profile = termite_metal_planned_access_profile_enabled();
    const uint64_t profile_start_ns = collect_profile ? termite_metal_clock_monotonic_nanos() : 0;
    if (collect_profile) {
        runtime->active_frame_planned_access_prepare_calls += 1;
        runtime->active_frame_planned_access_ranges += (uint64_t)access_count;
    }
    bool conflict = false;
    for (size_t i = 0; !conflict && i < access_count; ++i) {
        const termite_metal_planned_encoder_range *access = &accesses[i];
        if (access->buffer == nil) continue;
        for (size_t j = 0; j < runtime->active_planned_compute_range_count; ++j) {
            if (collect_profile) runtime->active_frame_planned_access_range_scans += 1;
            if (termite_metal_planned_ranges_overlap(access, &runtime->active_planned_compute_ranges[j])) {
                conflict = true;
                break;
            }
        }
    }

    const bool capacity_flush = runtime->active_planned_compute_range_count + access_count > TERMITE_METAL_PLANNED_RANGE_CAPACITY;
    if (conflict || capacity_flush) {
        if (collect_profile) {
            if (conflict) runtime->active_frame_planned_access_conflicts += 1;
            if (capacity_flush) runtime->active_frame_planned_access_capacity_flushes += 1;
        }
        id<MTLComputeCommandEncoder> encoder = runtime->active_planned_compute_encoder;
        if (encoder == nil) return failure_code;
        if (termite_metal_planned_compute_barriers_enabled(runtime)) {
            [encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
            runtime->active_frame_planned_barrier_count += 1;
            if (collect_profile) runtime->active_frame_planned_access_barriers += 1;
        }
        termite_metal_decode_runtime_reset_planned_compute_ranges(runtime);
    }

    for (size_t i = 0; i < access_count; ++i) {
        const termite_metal_planned_encoder_range access = accesses[i];
        if (access.buffer == nil) continue;
        if (runtime->active_planned_compute_range_count >= TERMITE_METAL_PLANNED_RANGE_CAPACITY) return failure_code;
        runtime->active_planned_compute_ranges[runtime->active_planned_compute_range_count] = access;
        runtime->active_planned_compute_range_count += 1;
    }
    if (collect_profile) {
        const uint64_t profile_end_ns = termite_metal_clock_monotonic_nanos();
        if (profile_end_ns >= profile_start_ns) {
            runtime->active_frame_planned_access_nanos += profile_end_ns - profile_start_ns;
        }
    }
    return 0;
}

// Force a full buffer-scope barrier on the active planned-compute encoder and
// reset the tracked range set. Used before a write into a REUSED pooled output
// buffer, to order any prior (possibly non-declaring) consumer reads of that
// buffer before the reuse-write — the planned hazard tracker only sees
// declared accesses, so reused pooled buffers need this conservative fence.
int termite_metal_decode_runtime_force_planned_compute_barrier(termite_metal_decode_runtime *runtime) {
    if (runtime == NULL) return -1;
    if (runtime->active_frame_cb == nil || runtime->active_planned_compute_encoder == nil) return 0;
    if (termite_metal_planned_compute_barriers_enabled(runtime)) {
        [runtime->active_planned_compute_encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
        runtime->active_frame_planned_barrier_count += 1;
    }
    termite_metal_decode_runtime_reset_planned_compute_ranges(runtime);
    return 0;
}

// A shared planned encoder can use MTLDispatchTypeConcurrent. Range tracking
// orders this fused call against neighboring calls, while an explicit barrier
// is still required between dispatches inside the call when a later kernel
// reads an intermediate written by an earlier kernel.
static void termite_metal_concurrent_planned_dependency_barrier(
    termite_metal_decode_runtime *runtime,
    id<MTLComputeCommandEncoder> encoder,
    BOOL encoder_owned
) {
    if (runtime == NULL || encoder == nil || encoder_owned || !termite_metal_concurrent_planned_dispatch_enabled(runtime)) return;
    [encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
    runtime->active_frame_planned_barrier_count += 1;
    if (termite_metal_planned_access_profile_enabled()) {
        runtime->active_frame_planned_access_barriers += 1;
    }
}

static int termite_metal_decode_runtime_prepare_planned_compute_unary_accesses(
    termite_metal_decode_runtime *runtime,
    id<MTLBuffer> input_buffer,
    size_t input_offset,
    size_t input_bytes,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    size_t output_bytes,
    int failure_code
) {
    termite_metal_planned_encoder_range accesses[2];
    if (termite_metal_planned_range_make(input_buffer, input_offset, input_bytes, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[0], failure_code) != 0 ||
        termite_metal_planned_range_make(output_buffer, output_offset, output_bytes, TERMITE_METAL_PLANNED_RANGE_WRITE, &accesses[1], failure_code) != 0 ||
        termite_metal_decode_runtime_prepare_planned_compute_accesses(runtime, accesses, 2, failure_code) != 0)
    {
        return failure_code;
    }
    return 0;
}

