            runtime->q4_0_pair_activation_mm_variant_override;
    if (selected == TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MM_VARIANT_AUTO) {
        selected = TERMITE_METAL_Q4_0_PAIR_ACTIVATION_MM_VARIANT_M32_N64;
