static void termite_metal_workload_profile_record_quant_matmul(
    termite_metal_decode_runtime *runtime,
    const termite_metal_quant_matmul_descriptor *descriptor,
    uint8_t dispatch,
    uint8_t implementation
) {
    // Decode runtimes are single-dispatch-thread objects. Keep this branch free
    // of locks, allocation, Metal calls, and environment lookups.
    if (runtime == NULL || descriptor == NULL || runtime->workload_profile_active == 0) return;

    const uint8_t regime = runtime->workload_profile_regime;
    const uint64_t hash = termite_metal_workload_profile_hash(descriptor, dispatch, implementation, regime);
    const uint64_t input_bytes = termite_metal_u64_saturating_mul(
        termite_metal_u64_saturating_mul(descriptor->rows, descriptor->in_dim),
        termite_metal_quant_matmul_dtype_size(descriptor->input_dtype)
    );
    uint64_t weight_bytes = 0;
    if (descriptor->values_per_block != 0 && descriptor->in_dim % descriptor->values_per_block == 0) {
        weight_bytes = termite_metal_u64_saturating_mul(
            termite_metal_u64_saturating_mul(descriptor->out_dim, descriptor->in_dim / descriptor->values_per_block),
            descriptor->bytes_per_block
        );
    }
    const uint64_t output_bytes = termite_metal_u64_saturating_mul(
        termite_metal_u64_saturating_mul(descriptor->rows, descriptor->out_dim),
        termite_metal_quant_matmul_dtype_size(descriptor->output_dtype)
    );
    const uint64_t logical_bytes = termite_metal_u64_saturating_add(
        termite_metal_u64_saturating_add(input_bytes, weight_bytes),
        output_bytes
    );
    const uint64_t macs = termite_metal_u64_saturating_mul(
        termite_metal_u64_saturating_mul(descriptor->rows, descriptor->in_dim),
        descriptor->out_dim
    );

    const size_t initial = (size_t)(hash & (TERMITE_METAL_WORKLOAD_PROFILE_CAPACITY - 1u));
    for (size_t probe = 0; probe < TERMITE_METAL_WORKLOAD_PROFILE_PROBE_LIMIT; ++probe) {
        termite_metal_workload_profile_entry *entry = &runtime->workload_profile_entries[
            (initial + probe) & (TERMITE_METAL_WORKLOAD_PROFILE_CAPACITY - 1u)
        ];
        if (entry->occupied == 0) {
            if (logical_bytes == UINT64_MAX || macs == UINT64_MAX) runtime->workload_profile_complete = 0;
            *entry = (termite_metal_workload_profile_entry){
                .hash = hash,
                .call_count = 1,
                .logical_bytes = logical_bytes,
                .macs = macs,
                .estimated_gpu_nanos = 0,
                .rows = descriptor->rows,
                .in_dim = descriptor->in_dim,
                .out_dim = descriptor->out_dim,
                .format = descriptor->format,
                .dispatch = dispatch,
                .input_encoding = (uint8_t)descriptor->input_dtype,
                .output_encoding = (uint8_t)descriptor->output_dtype,
                .epilogue = (uint8_t)descriptor->epilogue,
                .implementation = implementation,
                .regime = regime,
                .fusion = descriptor->sumsq_buffer != nil ? 1u : 0u,
                .layout = 0,
                .calibrated = 0,
                .occupied = 1,
            };
            return;
        }
        if (termite_metal_workload_profile_entry_matches(entry, descriptor, dispatch, implementation, regime, hash)) {
            if (entry->call_count == UINT64_MAX ||
                termite_metal_u64_add_overflows(entry->logical_bytes, logical_bytes) ||
                termite_metal_u64_add_overflows(entry->macs, macs)) {
                runtime->workload_profile_complete = 0;
            }
            entry->call_count = termite_metal_u64_saturating_add(entry->call_count, 1);
            entry->logical_bytes = termite_metal_u64_saturating_add(entry->logical_bytes, logical_bytes);
            entry->macs = termite_metal_u64_saturating_add(entry->macs, macs);
            return;
        }
    }

    runtime->workload_profile_complete = 0;
    runtime->workload_profile_dropped_signatures = termite_metal_u64_saturating_add(runtime->workload_profile_dropped_signatures, 1);
    runtime->workload_profile_dropped_dispatches = termite_metal_u64_saturating_add(runtime->workload_profile_dropped_dispatches, 1);
}

static termite_metal_quant_matmul_activation_dtype termite_metal_quant_matmul_dtype_from_command(uint8_t dtype) {
    switch (dtype) {
        case TERMITE_METAL_QUANT_MATMUL_ACTIVATION_BF16:
            return TERMITE_METAL_QUANT_MATMUL_ACTIVATION_BF16;
        case TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16:
            return TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16;
        case TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32:
        default:
            return TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32;
    }
}

static bool termite_metal_quant_matmul_descriptor_dtype_supported(
    termite_metal_decode_runtime *runtime,
    const termite_metal_quant_matmul_descriptor *descriptor
) {
    if (runtime == NULL || descriptor == NULL) return false;
    if (descriptor->activation_dtype != TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32) return false;
    if (descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32) return true;
    if (descriptor->format == TERMITE_METAL_QUANT_FORMAT_Q4_K &&
        descriptor->values_per_block == 256u &&
        descriptor->bytes_per_block == 144u &&
        descriptor->rows == 1u &&
        descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_PAIR_ACTIVATION_MUL &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16) {
        return runtime->q4_k_pair_activation_reduce_f16_output_pipeline != nil;
    }
    if (descriptor->format == TERMITE_METAL_QUANT_FORMAT_Q4_0 &&
        descriptor->values_per_block == 32u &&
        descriptor->bytes_per_block == 18u &&
        descriptor->rows == 1u &&
        descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_PAIR_ACTIVATION_MUL &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16) {
        return runtime->q4_0_pair_activation_reduce_f16_output_pipeline != nil;
    }
    if (descriptor->format == TERMITE_METAL_QUANT_FORMAT_Q4_0 &&
        descriptor->values_per_block == 32u &&
        descriptor->bytes_per_block == 18u &&
        descriptor->rows == 1u &&
        descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_ACTIVATION_RHS_MUL &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16) {
        return runtime->q4_0_activation_rhs_reduce_f16_output_pipeline != nil;
    }
    if (descriptor->format == TERMITE_METAL_QUANT_FORMAT_Q4_0 &&
        descriptor->values_per_block == 32u &&
        descriptor->bytes_per_block == 18u &&
        descriptor->rows == 1u &&
        descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_PAIR_ACTIVATION_RMS_SCALE_1X &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16) {
        return runtime->q4_0_pair_activation_rms_scale_reduce_f16_output_pipeline != nil;
    }
    if (descriptor->format == TERMITE_METAL_QUANT_FORMAT_Q4_0 &&
        descriptor->values_per_block == 32u &&
        descriptor->bytes_per_block == 18u &&
        descriptor->rows == 1u &&
        descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_NONE &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32) {
        return runtime->q4_0_reduce_f16_input_pipeline != nil;
    }
    if (descriptor->format == TERMITE_METAL_QUANT_FORMAT_Q4_0 &&
        descriptor->values_per_block == 32u &&
        descriptor->bytes_per_block == 18u &&
        descriptor->rows == 1u &&
        descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_NONE &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16) {
        return runtime->q4_0_reduce_f16_output_pipeline != nil;
    }
    if (descriptor->format == TERMITE_METAL_QUANT_FORMAT_Q4_0 &&
        descriptor->values_per_block == 32u &&
        descriptor->bytes_per_block == 18u &&
        descriptor->rows == 1u &&
        descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_NONE &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16) {
        return runtime->q4_0_reduce_f16_input_f16_output_pipeline != nil;
    }
    if (descriptor->format == TERMITE_METAL_QUANT_FORMAT_Q6_K &&
        descriptor->values_per_block == 256u &&
        descriptor->bytes_per_block == 210u &&
        descriptor->rows == 1u &&
        descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_NONE &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32) {
        return runtime->q6_k_reduce_f16_input_pipeline != nil;
    }
    if (descriptor->format != TERMITE_METAL_QUANT_FORMAT_Q8_0 ||
        descriptor->values_per_block != 32u ||
        descriptor->bytes_per_block != 34u) return false;
    const uint8_t planned_dispatch = termite_metal_quant_matmul_descriptor_planned_dispatch(descriptor);
    const termite_metal_q8_0_linear_dispatch_kind dispatch_kind = termite_metal_q8_0_dispatch_from_quant_dispatch(
        termite_metal_select_quant_matmul_dispatch_preferred(
            descriptor->format,
            descriptor->rows,
            descriptor->in_dim,
            descriptor->out_dim,
            descriptor->values_per_block,
            planned_dispatch));
    if (descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_PAIR_ACTIVATION_MUL &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16) {
        return dispatch_kind == TERMITE_METAL_Q8_0_LINEAR_DISPATCH_MM &&
            runtime->q8_0_pair_activation_mm_f16_output_pipeline != nil;
    }
    if (descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_PAIR_ACTIVATION_RMS_SCALE_1X &&
        descriptor->rows == 1u &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16) {
        return (dispatch_kind == TERMITE_METAL_Q8_0_LINEAR_DISPATCH_MMV ||
                dispatch_kind == TERMITE_METAL_Q8_0_LINEAR_DISPATCH_SCALAR) &&
            runtime->q8_0_pair_activation_rms_scale_mmv_f16_output_pipeline != nil;
    }
    if (descriptor->epilogue == TERMITE_METAL_QUANT_MATMUL_EPILOGUE_NONE &&
        descriptor->input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16 &&
        descriptor->output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32) {
        return (dispatch_kind == TERMITE_METAL_Q8_0_LINEAR_DISPATCH_MM &&
                runtime->q8_0_mm_f16_input_pipeline != nil) ||
            ((dispatch_kind == TERMITE_METAL_Q8_0_LINEAR_DISPATCH_MMV ||
                dispatch_kind == TERMITE_METAL_Q8_0_LINEAR_DISPATCH_SCALAR) &&
                runtime->q8_0_mmv_f16_input_pipeline != nil);
    }
    return false;
}

