static int termite_metal_encode_attention_f32_on_encoder(
    termite_metal_decode_runtime *runtime,
    id<MTLComputeCommandEncoder> encoder,
    id<MTLBuffer> q_buffer,
    size_t q_offset,
    id<MTLBuffer> k_buffer,
    size_t k_offset,
    id<MTLBuffer> v_buffer,
    size_t v_offset,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    size_t q_len,
    size_t kv_tokens,
    size_t num_heads,
    size_t num_kv_heads,
    size_t head_dim,
    size_t query_position_offset,
    size_t kv_position_offset,
    size_t sliding_window,
    size_t total_sequence_len,
    int failure_code
) {
    if (runtime == NULL || encoder == nil || q_buffer == nil || k_buffer == nil || v_buffer == nil || output_buffer == nil) return failure_code;
    if (runtime->attention_f32_pipeline == nil) return failure_code;
    if (q_len == 0 || kv_tokens == 0 || num_heads == 0 || num_kv_heads == 0 || head_dim == 0) return failure_code;
    if (q_len > UINT32_MAX || kv_tokens > UINT32_MAX || num_heads > UINT32_MAX || num_kv_heads > UINT32_MAX || head_dim > UINT32_MAX || query_position_offset > UINT32_MAX || kv_position_offset > UINT32_MAX || sliding_window > UINT32_MAX || total_sequence_len > UINT32_MAX) return failure_code;
    size_t q_rows = 0;
    size_t kv_rows = 0;
    size_t q_bytes = 0;
    size_t kv_bytes = 0;
    size_t output_bytes = 0;
    if (!termite_metal_size_mul(q_len, num_heads, &q_rows) ||
        !termite_metal_size_mul(kv_tokens, num_kv_heads, &kv_rows) ||
        !termite_metal_size_mul3(q_rows, head_dim, sizeof(float), &q_bytes) ||
        !termite_metal_size_mul3(kv_rows, head_dim, sizeof(float), &kv_bytes) ||
        !termite_metal_size_mul3(q_rows, head_dim, sizeof(float), &output_bytes))
    {
        return failure_code;
    }
    termite_metal_planned_encoder_range accesses[4];
    if (termite_metal_planned_range_make(q_buffer, q_offset, q_bytes, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[0], failure_code) != 0 ||
        termite_metal_planned_range_make(k_buffer, k_offset, kv_bytes, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[1], failure_code) != 0 ||
        termite_metal_planned_range_make(v_buffer, v_offset, kv_bytes, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[2], failure_code) != 0 ||
        termite_metal_planned_range_make(output_buffer, output_offset, output_bytes, TERMITE_METAL_PLANNED_RANGE_WRITE, &accesses[3], failure_code) != 0 ||
        termite_metal_decode_runtime_prepare_planned_compute_accesses(runtime, accesses, 4, failure_code) != 0)
    {
        return failure_code;
    }
    const float zero_bias = 0.0f;
    const uint8_t zero_mask = 0;
    termite_metal_attention_f32_params params = {
        .q_len = (uint32_t)q_len,
        .kv_len = (uint32_t)kv_tokens,
        .num_heads = (uint32_t)num_heads,
        .num_kv_heads = (uint32_t)num_kv_heads,
        .head_dim = (uint32_t)head_dim,
        .query_position_offset = (uint32_t)query_position_offset,
        .kv_position_offset = (uint32_t)kv_position_offset,
        .sliding_window = (uint32_t)sliding_window,
        .total_sequence_len = (uint32_t)total_sequence_len,
        .has_bias = 0u,
        .has_mask = 0u,
        .batch = 1u,
        .reserved0 = 0u,
    };
    const BOOL use_prefill_tiled = (runtime->attention_f32_prefill_pipeline != nil && q_len >= 1 && kv_tokens <= 2048u && head_dim <= 1024u);
    id<MTLComputePipelineState> pipeline = use_prefill_tiled ? runtime->attention_f32_prefill_pipeline : runtime->attention_f32_pipeline;
    [encoder setComputePipelineState:pipeline];
    [encoder setBuffer:q_buffer offset:q_offset atIndex:0];
    [encoder setBuffer:k_buffer offset:k_offset atIndex:1];
    [encoder setBuffer:v_buffer offset:v_offset atIndex:2];
    [encoder setBuffer:output_buffer offset:output_offset atIndex:3];
    [encoder setBytes:&zero_bias length:sizeof(zero_bias) atIndex:4];
    [encoder setBytes:&zero_mask length:sizeof(zero_mask) atIndex:5];
    [encoder setBytes:&params length:sizeof(params) atIndex:6];
    if (use_prefill_tiled) {
        [encoder setThreadgroupMemoryLength:termite_metal_threadgroup_memory_16((kv_tokens + 256u) * sizeof(float)) atIndex:0];
        [encoder dispatchThreadgroups:MTLSizeMake(q_len, num_heads, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    } else {
        const size_t total_rows = q_len * num_heads;
        [encoder dispatchThreads:MTLSizeMake(total_rows, 1, 1) threadsPerThreadgroup:MTLSizeMake(termite_metal_thread_width(runtime->attention_f32_pipeline, total_rows), 1, 1)];
    }
    return 0;
}

static bool termite_metal_block_table_contiguous(
    const uint32_t *block_table,
    size_t needed_blocks,
    size_t page_size,
    size_t kv_tokens,
    uint32_t *base_out
) {
    if (block_table == NULL || needed_blocks == 0 || page_size == 0 || kv_tokens == 0 || base_out == NULL) return false;
    const uint32_t base = block_table[0];
    if ((uint64_t)base + (uint64_t)(kv_tokens - 1u) > UINT32_MAX) return false;
    for (size_t block = 1; block < needed_blocks; ++block) {
        const uint64_t expected = (uint64_t)base + (uint64_t)block * (uint64_t)page_size;
        if (expected > UINT32_MAX || block_table[block] != (uint32_t)expected) return false;
    }
    *base_out = base;
    return true;
}

// Direct contiguous K/V remains a qualification candidate: the long-prompt
// M4 gate did not clear the promotion threshold. Keep it explicit-only until
// a device/shape policy demonstrates a repeatable whole-phase win. The
// disable switch still wins when both flags are present.
static bool termite_metal_prefill_direct_kv_enabled_for_device(id<MTLDevice> device, uint16_t apple_gpu_family) {
    (void)device;
    (void)apple_gpu_family;
    if (termite_metal_env_flag_enabled(getenv("TERMITE_METAL_DISABLE_PREFILL_SG_DIRECT_LOAD"))) return false;
    return termite_metal_env_flag_enabled(getenv("TERMITE_METAL_ENABLE_PREFILL_SG_DIRECT_LOAD"));
}

static bool termite_metal_fast_prepared_frame_enabled_for_device(id<MTLDevice> device, uint16_t apple_gpu_family) {
    if (termite_metal_env_flag_enabled(getenv("TERMITE_METAL_DISABLE_FAST_PREPARED_FRAME"))) return false;
    return device != nil && apple_gpu_family == 9u && [device.name hasPrefix:@"Apple M4"];
}

static void termite_metal_record_prefill_kv_route(termite_metal_decode_runtime *runtime, bool direct) {
    if (direct) {
        runtime->attention_prefill_direct_kv_calls += 1;
    } else {
        runtime->attention_prefill_paged_kv_calls += 1;
    }
}

static bool termite_metal_generated_flash_prefill_disabled(void) {
    return termite_metal_env_flag_enabled(getenv("TERMITE_METAL_DISABLE_FLASH_PREFILL_GENERATED"));
}

static bool termite_metal_generated_flash_prefill_shape_enabled(
    size_t num_heads,
    size_t num_kv_heads,
    size_t head_dim,
    size_t sliding_window
) {
    if (termite_metal_generated_flash_prefill_disabled() || head_dim != 256u) return false;
    return termite_metal_env_flag_enabled(getenv("TERMITE_METAL_ENABLE_FLASH_PREFILL_GENERATED")) ||
        (num_heads == 8u && num_kv_heads == 2u && sliding_window == 512u);
}

static bool termite_metal_generated_flash_prefill_eligible(
    termite_metal_decode_runtime *runtime,
    uint32_t format,
    size_t q_len,
    size_t num_heads,
    size_t num_kv_heads,
    size_t head_dim,
    size_t page_size,
    size_t sliding_window,
    float softcap,
    const float *sinks
) {
    id<MTLComputePipelineState> pipeline = runtime->attention_flash_generated_pipeline;
    return pipeline != nil &&
        format == 3u &&
        sinks == NULL &&
        softcap == 0.0f &&
        q_len >= 8u &&
        page_size % 8u == 0u &&
        num_heads % num_kv_heads == 0u &&
        termite_metal_generated_flash_prefill_shape_enabled(num_heads, num_kv_heads, head_dim, sliding_window) &&
        pipeline.maxTotalThreadsPerThreadgroup >= TERMITE_METAL_GENERATED_FLASH_THREADS &&
        pipeline.threadExecutionWidth == 32u &&
        runtime->device.maxThreadgroupMemoryLength >= TERMITE_METAL_GENERATED_FLASH_MEMORY_BYTES(head_dim);
}

static bool termite_metal_handwritten_flash_prefill_eligible(
    termite_metal_decode_runtime *runtime,
    uint32_t format,
    size_t q_len,
    size_t head_dim,
    float softcap,
    const float *sinks
) {
    return runtime->attention_paged_prefill_sg_pipeline != nil &&
        format == 3u &&
        sinks == NULL &&
        softcap == 0.0f &&
        q_len >= 8u &&
        head_dim % 32u == 0u &&
        head_dim <= 256u;
}

typedef struct termite_metal_decode_gqa_split_schedule {
    termite_metal_decode_gqa_split_variant variant;
    uint32_t max_splits;
    uint32_t key_chunk;
    uint32_t stage_threads;
    uint32_t reduce_threads;
} termite_metal_decode_gqa_split_schedule;

typedef struct termite_metal_decode_gqa_split_launch {
    termite_metal_decode_gqa_split_schedule schedule;
    termite_metal_decode_gqa_split_params params;
    termite_metal_decode_gqa_split_shape shape;
    size_t scratch_bytes;
} termite_metal_decode_gqa_split_launch;

static bool termite_metal_decode_gqa_split_schedule_for_variant(
    termite_metal_decode_gqa_split_variant requested,
    termite_metal_decode_gqa_split_schedule *schedule_out
) {
    if (schedule_out == NULL) return false;
    termite_metal_decode_gqa_split_variant resolved = requested;
    if (resolved == TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_AUTO) {
        // AUTO intentionally preserves the production route byte-for-byte:
        // cap 32, 32-token tiles, and 256-thread stage/reducer launches.
        resolved = TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S32;
    }
    uint32_t max_splits = 0;
    switch (resolved) {
        case TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S8: max_splits = 8u; break;
        case TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S16: max_splits = 16u; break;
        case TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S24: max_splits = 24u; break;
        case TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S32: max_splits = 32u; break;
        case TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_AUTO: return false;
    }
    *schedule_out = (termite_metal_decode_gqa_split_schedule){
        .variant = resolved,
        .max_splits = max_splits,
        .key_chunk = TERMITE_METAL_DECODE_GQA_SPLIT_KEY_CHUNK,
        .stage_threads = TERMITE_METAL_DECODE_GQA_SPLIT_STAGE_THREADS,
        .reduce_threads = TERMITE_METAL_DECODE_GQA_SPLIT_REDUCE_THREADS,
    };
    return true;
}

static bool termite_metal_decode_gqa_split_shape_classify(
    size_t head_dim,
    size_t sliding_window,
    termite_metal_decode_gqa_split_shape *shape_out
) {
    if (head_dim == 256u && sliding_window == 512u) {
        if (shape_out != NULL) *shape_out = TERMITE_METAL_DECODE_GQA_SPLIT_SHAPE_SWA_HD256;
        return true;
    }
    if (head_dim == 512u && sliding_window == 0u) {
        if (shape_out != NULL) *shape_out = TERMITE_METAL_DECODE_GQA_SPLIT_SHAPE_GLOBAL_HD512;
        return true;
    }
    return false;
}

static bool termite_metal_decode_gqa_split_scratch_bytes(
    size_t q_len,
    size_t num_heads,
    size_t head_dim,
    size_t split_count,
    size_t *bytes_out
) {
    if (bytes_out == NULL || split_count == 0u ||
        split_count > TERMITE_METAL_DECODE_GQA_SPLIT_COUNT || head_dim > SIZE_MAX - 2u) return false;
    size_t bytes = 0;
    return termite_metal_size_mul3(q_len, num_heads, split_count, &bytes) &&
        termite_metal_size_mul(bytes, head_dim + 2u, &bytes) &&
        termite_metal_size_mul(bytes, sizeof(float), bytes_out);
}

// Pure portfolio selection used by both dispatch and the public probe. A
// positive result means the geometry is supported; zero is an ordinary route
// miss, while a negative result identifies malformed input or overflow.
static int termite_metal_decode_gqa_split_select(
    termite_metal_decode_gqa_split_variant requested,
    size_t q_len,
    size_t kv_tokens,
    size_t num_heads,
    size_t num_kv_heads,
    size_t head_dim,
    size_t sliding_window,
    termite_metal_decode_gqa_split_launch *launch_out
) {
    if (launch_out == NULL) return -1;
    memset(launch_out, 0, sizeof(*launch_out));
    termite_metal_decode_gqa_split_schedule schedule;
    if (!termite_metal_decode_gqa_split_schedule_for_variant(requested, &schedule)) return -2;
    termite_metal_decode_gqa_split_shape shape;
    if (q_len == 0u || q_len > 2u || kv_tokens < TERMITE_METAL_DECODE_GQA_SPLIT_MIN_KV_TOKENS ||
        num_heads != 8u || (num_kv_heads != 1u && num_kv_heads != 2u) ||
        !termite_metal_decode_gqa_split_shape_classify(head_dim, sliding_window, &shape)) return 0;
    if (kv_tokens > SIZE_MAX - (schedule.key_chunk - 1u)) return -3;
    size_t split_count = (kv_tokens + schedule.key_chunk - 1u) / schedule.key_chunk;
    if (split_count > schedule.max_splits) split_count = schedule.max_splits;
    size_t scratch_bytes = 0;
    if (!termite_metal_decode_gqa_split_scratch_bytes(
            q_len, num_heads, head_dim, split_count, &scratch_bytes)) return -3;
    launch_out->schedule = schedule;
    launch_out->params = (termite_metal_decode_gqa_split_params){
        .split_count = (uint32_t)split_count,
        .max_splits = schedule.max_splits,
        .key_chunk = schedule.key_chunk,
        .reduce_simdgroups = schedule.reduce_threads / 32u,
    };
    launch_out->shape = shape;
    launch_out->scratch_bytes = scratch_bytes;
    return 1;
}

int termite_metal_decode_gqa_split_policy_probe(
    uint32_t requested_variant,
    size_t q_len,
    size_t kv_tokens,
    size_t num_heads,
    size_t num_kv_heads,
    size_t head_dim,
    size_t sliding_window,
    uint32_t *resolved_variant_out,
    uint32_t *split_count_out,
    size_t *scratch_bytes_out
) {
    if (resolved_variant_out == NULL || split_count_out == NULL || scratch_bytes_out == NULL) return -1;
    *resolved_variant_out = TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_AUTO;
    *split_count_out = 0u;
    *scratch_bytes_out = 0u;
    if (requested_variant > TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S32) return -2;
    termite_metal_decode_gqa_split_launch launch;
    const int selected = termite_metal_decode_gqa_split_select(
        (termite_metal_decode_gqa_split_variant)requested_variant,
        q_len,
        kv_tokens,
        num_heads,
        num_kv_heads,
        head_dim,
        sliding_window,
        &launch);
    if (selected <= 0) return selected;
    *resolved_variant_out = (uint32_t)launch.schedule.variant;
    *split_count_out = launch.params.split_count;
    *scratch_bytes_out = launch.scratch_bytes;
    return 1;
}

static termite_metal_decode_gqa_split_variant termite_metal_decode_gqa_split_override_for_shape(
    const termite_metal_decode_runtime *runtime,
    termite_metal_decode_gqa_split_shape shape
) {
    if (runtime == NULL) return TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_AUTO;
    return (termite_metal_decode_gqa_split_variant)(
        shape == TERMITE_METAL_DECODE_GQA_SPLIT_SHAPE_SWA_HD256
            ? runtime->decode_gqa_split_swa_variant_override
            : runtime->decode_gqa_split_global_variant_override);
}

static bool termite_metal_decode_gqa_split_runtime_scratch_capacity(
    const termite_metal_decode_runtime *runtime,
    size_t *bytes_out
) {
    if (runtime == NULL || bytes_out == NULL) return false;
    termite_metal_decode_gqa_split_schedule swa_schedule;
    termite_metal_decode_gqa_split_schedule global_schedule;
    if (!termite_metal_decode_gqa_split_schedule_for_variant(
            (termite_metal_decode_gqa_split_variant)runtime->decode_gqa_split_swa_variant_override,
            &swa_schedule) ||
        !termite_metal_decode_gqa_split_schedule_for_variant(
            (termite_metal_decode_gqa_split_variant)runtime->decode_gqa_split_global_variant_override,
            &global_schedule)) return false;
    size_t swa_bytes = 0;
    size_t global_bytes = 0;
    if (!termite_metal_decode_gqa_split_scratch_bytes(
            2u, 8u, 256u, swa_schedule.max_splits, &swa_bytes) ||
        !termite_metal_decode_gqa_split_scratch_bytes(
            2u, 8u, 512u, global_schedule.max_splits, &global_bytes)) return false;
    *bytes_out = swa_bytes > global_bytes ? swa_bytes : global_bytes;
    return *bytes_out <= TERMITE_METAL_DECODE_GQA_SPLIT_SCRATCH_MAX_BYTES;
}

static bool termite_metal_decode_gqa_split_eligible(
    termite_metal_decode_runtime *runtime,
    termite_metal_decode_runtime *scratch_runtime,
    uint32_t format,
    size_t q_len,
    size_t kv_tokens,
    size_t output_offset,
    size_t num_heads,
    size_t num_kv_heads,
    size_t head_dim,
    size_t key_row_bytes,
    size_t v_row_stride,
    size_t page_size,
    size_t sliding_window,
    float softcap,
    const float *sinks,
    termite_metal_decode_gqa_split_launch *launch_out,
    bool *strict_failure_out
) {
    if (launch_out != NULL) memset(launch_out, 0, sizeof(*launch_out));
    if (strict_failure_out != NULL) *strict_failure_out = false;
    if (runtime == NULL || !runtime->decode_gqa_split_enabled) return false;
    if (format != 3u || sinks != NULL || softcap != 0.0f || q_len == 0u || q_len > 2u ||
        kv_tokens < TERMITE_METAL_DECODE_GQA_SPLIT_MIN_KV_TOKENS || num_heads != 8u ||
        (num_kv_heads != 1u && num_kv_heads != 2u) ||
        page_size == 0u || page_size % 8u != 0u) return false;
    termite_metal_decode_gqa_split_shape shape;
    if (!termite_metal_decode_gqa_split_shape_classify(head_dim, sliding_window, &shape)) return false;
    termite_metal_decode_gqa_split_launch launch;
    const int selected = termite_metal_decode_gqa_split_select(
        termite_metal_decode_gqa_split_override_for_shape(runtime, shape),
        q_len,
        kv_tokens,
        num_heads,
        num_kv_heads,
        head_dim,
        sliding_window,
        &launch);
    if (selected <= 0) {
        runtime->decode_gqa_split_schedule_fallback_calls += 1;
        if (strict_failure_out != NULL && runtime->decode_gqa_split_explicitly_requested) {
            *strict_failure_out = true;
        }
        return false;
    }
    size_t expected_key_row_bytes = 0;
    size_t expected_v_row_stride = 0;
    if (scratch_runtime == NULL || runtime->device != scratch_runtime->device ||
        scratch_runtime->submitted_frame_cb != nil || output_offset % (4u * sizeof(float)) != 0u ||
        runtime->attention_decode_gqa_split_stage_pipeline == nil ||
        runtime->attention_decode_gqa_split_reduce_pipeline == nil ||
        scratch_runtime->attention_decode_gqa_split_scratch_buffer == nil ||
        !termite_metal_size_mul3(num_kv_heads, head_dim, sizeof(uint16_t), &expected_key_row_bytes) ||
        !termite_metal_size_mul(num_kv_heads, head_dim, &expected_v_row_stride) ||
        key_row_bytes != expected_key_row_bytes || v_row_stride != expected_v_row_stride ||
        launch.scratch_bytes > scratch_runtime->attention_decode_gqa_split_scratch_capacity ||
        launch.scratch_bytes > scratch_runtime->attention_decode_gqa_split_scratch_buffer.length) {
        runtime->decode_gqa_split_schedule_fallback_calls += 1;
        if (strict_failure_out != NULL && runtime->decode_gqa_split_explicitly_requested) {
            *strict_failure_out = true;
        }
        return false;
    }
    id<MTLComputePipelineState> stage = runtime->attention_decode_gqa_split_stage_pipeline;
    id<MTLComputePipelineState> reduce = runtime->attention_decode_gqa_split_reduce_pipeline;
    if (stage.maxTotalThreadsPerThreadgroup < launch.schedule.stage_threads ||
        reduce.maxTotalThreadsPerThreadgroup < launch.schedule.reduce_threads ||
        stage.threadExecutionWidth != 32u || reduce.threadExecutionWidth != 32u ||
        runtime->device.maxThreadgroupMemoryLength < TERMITE_METAL_DECODE_GQA_SPLIT_STAGE_MEMORY_BYTES(head_dim)) {
        runtime->decode_gqa_split_schedule_fallback_calls += 1;
        if (strict_failure_out != NULL && runtime->decode_gqa_split_explicitly_requested) {
            *strict_failure_out = true;
        }
        return false;
    }
    if (launch_out != NULL) *launch_out = launch;
    return true;
}

// Keep the two paged-attention entry points on one stage/reduce encoding
// contract. The caller binds q/K/V/block/sinks first; this helper owns every
// schedule-dependent binding, dispatch dimension, hazard transition, and
// counter update.
static int termite_metal_encode_decode_gqa_split_dispatch(
    termite_metal_decode_runtime *runtime,
    termite_metal_decode_runtime *scratch_runtime,
    id<MTLComputeCommandEncoder> encoder,
    const termite_metal_paged_attention_params *params,
    const termite_metal_decode_gqa_split_launch *launch,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    size_t output_bytes,
    int failure_code
) {
    if (runtime == NULL || scratch_runtime == NULL || encoder == nil || params == NULL ||
        launch == NULL || output_buffer == nil ||
        launch->schedule.variant < TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S8 ||
        launch->schedule.variant > TERMITE_METAL_DECODE_GQA_SPLIT_VARIANT_S32 ||
        launch->shape >= TERMITE_METAL_DECODE_GQA_SPLIT_SHAPE_COUNT) return failure_code;
    [encoder setComputePipelineState:runtime->attention_decode_gqa_split_stage_pipeline];
    [encoder setBuffer:scratch_runtime->attention_decode_gqa_split_scratch_buffer offset:0 atIndex:5];
    [encoder setBytes:params length:sizeof(*params) atIndex:6];
    [encoder setBytes:&launch->params length:sizeof(launch->params) atIndex:7];
    [encoder setThreadgroupMemoryLength:TERMITE_METAL_DECODE_GQA_SPLIT_STAGE_MEMORY_BYTES(params->head_dim) atIndex:0];
    [encoder dispatchThreadgroups:MTLSizeMake(params->q_len, params->num_kv_heads, launch->params.split_count)
        threadsPerThreadgroup:MTLSizeMake(launch->schedule.stage_threads, 1, 1)];

    const bool needs_explicit_split_barrier = scratch_runtime->active_planned_compute_encoder != encoder ||
        !termite_metal_planned_compute_barriers_enabled(scratch_runtime);
    termite_metal_planned_encoder_range reduce_accesses[2];
    if (termite_metal_planned_range_make(
            scratch_runtime->attention_decode_gqa_split_scratch_buffer,
            0,
            launch->scratch_bytes,
            TERMITE_METAL_PLANNED_RANGE_READ,
            &reduce_accesses[0],
            failure_code) != 0 ||
        termite_metal_planned_range_make(
            output_buffer,
            output_offset,
            output_bytes,
            TERMITE_METAL_PLANNED_RANGE_WRITE,
            &reduce_accesses[1],
            failure_code) != 0 ||
        termite_metal_decode_runtime_prepare_planned_compute_accesses(
            scratch_runtime,
            reduce_accesses,
            2,
            failure_code) != 0) return failure_code;
    if (needs_explicit_split_barrier) [encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
    [encoder setComputePipelineState:runtime->attention_decode_gqa_split_reduce_pipeline];
    [encoder setBuffer:scratch_runtime->attention_decode_gqa_split_scratch_buffer offset:0 atIndex:0];
    [encoder setBuffer:output_buffer offset:output_offset atIndex:1];
    [encoder setBytes:params length:sizeof(*params) atIndex:2];
    [encoder setBytes:&launch->params length:sizeof(launch->params) atIndex:3];
    [encoder dispatchThreadgroups:MTLSizeMake(params->q_len, params->num_heads, 1)
        threadsPerThreadgroup:MTLSizeMake(launch->schedule.reduce_threads, 1, 1)];

    runtime->decode_gqa_split_calls += 1;
    const size_t variant_index = (size_t)launch->schedule.variant - 1u;
    runtime->decode_gqa_split_schedule_calls[launch->shape][variant_index] += 1;
    return 0;
}

static int termite_metal_encode_paged_attention_slot_on_encoder(
    termite_metal_decode_runtime *runtime,
    id<MTLComputeCommandEncoder> encoder,
    size_t slot,
    uint32_t format,
    id<MTLBuffer> q_buffer,
    size_t q_offset,
    const uint32_t *block_table,
    size_t block_count,
    size_t page_size,
    size_t q_len,
    size_t kv_tokens,
    size_t num_heads,
    size_t num_kv_heads,
    size_t head_dim,
    size_t key_row_bytes,
    size_t base_key_row_bytes,
    size_t query_position_offset,
    size_t kv_position_offset,
    size_t sliding_window,
    float softcap,
    const float *sinks,
    size_t sink_count,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    int failure_code
) {
    if (runtime == NULL || encoder == nil || q_buffer == nil || block_table == NULL || output_buffer == nil) return failure_code;
    if (slot >= TERMITE_METAL_ATTENTION_SPAN_SLOT_CAPACITY) return failure_code;
    if (q_len == 0 || kv_tokens == 0 || num_heads == 0 || num_kv_heads == 0 || head_dim == 0 || page_size == 0 || block_count == 0) return failure_code;
    if (num_heads % num_kv_heads != 0) return failure_code;
    if (q_len > UINT32_MAX || kv_tokens > UINT32_MAX || num_heads > UINT32_MAX || num_kv_heads > UINT32_MAX || head_dim > UINT32_MAX) return failure_code;
    if (key_row_bytes > UINT32_MAX || base_key_row_bytes > UINT32_MAX || query_position_offset > UINT32_MAX || kv_position_offset > UINT32_MAX || sliding_window > UINT32_MAX || page_size > UINT32_MAX || block_count > UINT32_MAX) return failure_code;
    if (runtime->attention_paged_pipeline == nil) return failure_code;
    if (runtime->attention_span_encoded_key_buffers[slot] == nil || runtime->attention_span_v_buffers[slot] == nil) return failure_code;
    // Paged slots may be layer-global: sequence-local token counts and
    // position offsets are carried by this invocation and its block table.
    // Only the physical row layout is slot-global. Referenced page capacity is
    // validated below before any buffer is bound.
    if (runtime->attention_span_slot_key_row_bytes[slot] != key_row_bytes) return failure_code;
    if (runtime->attention_span_slot_v_row_stride[slot] > UINT32_MAX) return failure_code;
    if (sinks != NULL && sink_count < num_heads) return failure_code;
    if (block_count > SIZE_MAX / sizeof(uint32_t)) return failure_code;
    const uint32_t v_element_bytes = (format == 3u) ? (uint32_t)sizeof(uint16_t) : (uint32_t)sizeof(float);
    switch (format) {
        case 0u:
        case 1u:
        case 2u:
        case 3u:
        case 4u:
            break;
        default:
            return failure_code;
    }
    const size_t full_needed_blocks = 1u + (kv_tokens - 1u) / page_size;
    if (full_needed_blocks > block_count) return failure_code;
    // iSWA scan clamp: for sliding-window layers, whole leading pages that
    // lie outside every query's window contribute exactly zero (the kernels
    // mask per position). Clamp before validating physical pages so validation
    // cost also tracks the window rather than the full logical history.
    if (sliding_window > 0 && sliding_window < kv_tokens && runtime->swa_scan_clamp_enabled) {
        const size_t window_start = query_position_offset + 1 > sliding_window
            ? query_position_offset + 1 - sliding_window
            : 0;
        if (window_start > kv_position_offset) {
            const size_t skip_tokens = window_start - kv_position_offset;
            const size_t skip_pages = skip_tokens / page_size;
            const size_t skip = skip_pages * page_size;
            if (skip > 0 && skip < kv_tokens && skip_pages < block_count) {
                block_table += skip_pages;
                block_count -= skip_pages;
                kv_tokens -= skip;
                kv_position_offset += skip;
            }
        }
    }
    const size_t needed_blocks = 1u + (kv_tokens - 1u) / page_size;
    if (needed_blocks > block_count) return failure_code;
    size_t referenced_tokens = 0;
    for (size_t block = 0; block < needed_blocks; ++block) {
        const size_t block_start = (size_t)block_table[block];
        if (block_start > SIZE_MAX - page_size) return failure_code;
        const size_t block_end = block_start + page_size;
        if (block_end > referenced_tokens) referenced_tokens = block_end;
    }
    if (referenced_tokens == 0 || referenced_tokens > SIZE_MAX / key_row_bytes) return failure_code;
    const size_t referenced_key_bytes = referenced_tokens * key_row_bytes;
    const size_t v_row_stride = runtime->attention_span_slot_v_row_stride[slot];
    if (v_row_stride == 0 || v_row_stride > SIZE_MAX / v_element_bytes) return failure_code;
    const size_t v_row_bytes = v_row_stride * v_element_bytes;
    if (referenced_tokens > SIZE_MAX / v_row_bytes) return failure_code;
    const size_t referenced_v_bytes = referenced_tokens * v_row_bytes;
    if (referenced_key_bytes > runtime->attention_span_encoded_key_buffers[slot].length ||
        referenced_v_bytes > runtime->attention_span_v_buffers[slot].length) return failure_code;

    termite_metal_paged_attention_params params = {
        .q_len = (uint32_t)q_len,
        .kv_tokens = (uint32_t)kv_tokens,
        .num_heads = (uint32_t)num_heads,
        .num_kv_heads = (uint32_t)num_kv_heads,
        .head_dim = (uint32_t)head_dim,
        .key_row_bytes = (uint32_t)key_row_bytes,
        .base_key_row_bytes = (uint32_t)base_key_row_bytes,
        .query_position_offset = (uint32_t)query_position_offset,
        .kv_position_offset = (uint32_t)kv_position_offset,
        .sliding_window = (uint32_t)sliding_window,
        .v_row_stride = (uint32_t)runtime->attention_span_slot_v_row_stride[slot],
        .page_size = (uint32_t)page_size,
        .block_count = (uint32_t)needed_blocks,
        .contiguous_base_token = 0u,
        .contiguous_blocks = 0u,
        .format = format,
        .v_element_bytes = v_element_bytes,
        .has_sinks = sinks != NULL ? 1u : 0u,
        .softcap = softcap,
        .swa_scan_clamp = runtime->swa_scan_clamp_enabled ? 1u : 0u,
    };
    const float zero_sink = 0.0f;
    const size_t block_table_bytes = needed_blocks * sizeof(uint32_t);
    const size_t sinks_bytes = sinks != NULL ? num_heads * sizeof(float) : sizeof(zero_sink);
    id<MTLBuffer> block_table_buffer = nil;
    id<MTLBuffer> sinks_buffer = nil;
    size_t q_bytes = 0;
    size_t output_bytes = 0;
    if (!termite_metal_size_mul3(q_len, num_heads, head_dim, &q_bytes) ||
        !termite_metal_size_mul(q_bytes, sizeof(float), &q_bytes) ||
        !termite_metal_size_mul3(q_len, num_heads, head_dim, &output_bytes) ||
        !termite_metal_size_mul(output_bytes, sizeof(float), &output_bytes))
    {
        return failure_code;
    }
    termite_metal_decode_gqa_split_launch split_launch = {0};
    bool decode_gqa_split_strict_failure = false;
    const bool use_decode_gqa_split = termite_metal_decode_gqa_split_eligible(
        runtime,
        runtime,
        format,
        q_len,
        kv_tokens,
        output_offset,
        num_heads,
        num_kv_heads,
        head_dim,
        key_row_bytes,
        v_row_stride,
        page_size,
        sliding_window,
        softcap,
        sinks,
        &split_launch,
        &decode_gqa_split_strict_failure);
    if (decode_gqa_split_strict_failure) return failure_code;
    termite_metal_planned_encoder_range accesses[4];
    if (termite_metal_planned_range_make(q_buffer, q_offset, q_bytes, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[0], failure_code) != 0 ||
        termite_metal_planned_range_make(runtime->attention_span_encoded_key_buffers[slot], 0, runtime->attention_span_encoded_key_buffers[slot].length, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[1], failure_code) != 0 ||
        termite_metal_planned_range_make(runtime->attention_span_v_buffers[slot], 0, runtime->attention_span_v_buffers[slot].length, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[2], failure_code) != 0 ||
        termite_metal_planned_range_make(
            use_decode_gqa_split ? runtime->attention_decode_gqa_split_scratch_buffer : output_buffer,
            use_decode_gqa_split ? 0u : output_offset,
            use_decode_gqa_split ? split_launch.scratch_bytes : output_bytes,
            TERMITE_METAL_PLANNED_RANGE_WRITE,
            &accesses[3],
            failure_code) != 0 ||
        termite_metal_decode_runtime_prepare_planned_compute_accesses(runtime, accesses, 4, failure_code) != 0)
    {
        return failure_code;
    }

    id<MTLComputePipelineState> decode_1x_pipeline = runtime->attention_1x_generated_pipeline != nil
        ? runtime->attention_1x_generated_pipeline
        : runtime->attention_paged_1x_pipeline;
    const bool generated_prefill_sg = termite_metal_generated_flash_prefill_eligible(
        runtime,
        format,
        q_len,
        num_heads,
        num_kv_heads,
        head_dim,
        page_size,
        sliding_window,
        softcap,
        sinks);
    const bool handwritten_prefill_sg = termite_metal_handwritten_flash_prefill_eligible(
        runtime,
        format,
        q_len,
        head_dim,
        softcap,
        sinks);
    id<MTLComputePipelineState> prefill_sg_pipeline = generated_prefill_sg
        ? runtime->attention_flash_generated_pipeline
        : runtime->attention_paged_prefill_sg_pipeline;
    id<MTLComputePipelineState> prefill_hd512_pipeline = runtime->attention_flash_hd512_generated_pipeline;
    const bool use_prefill_hd512 = format == 3u &&
        sinks == NULL &&
        softcap == 0.0f &&
        q_len >= 8u &&
        head_dim == 512u &&
        page_size % 8u == 0u &&
        prefill_hd512_pipeline != nil &&
        prefill_hd512_pipeline.maxTotalThreadsPerThreadgroup >= TERMITE_METAL_GENERATED_FLASH_HD512_THREADS &&
        prefill_hd512_pipeline.threadExecutionWidth == 32u &&
        runtime->device.maxThreadgroupMemoryLength >= TERMITE_METAL_GENERATED_FLASH_HD512_MEMORY_BYTES;
    const bool use_prefill_sg = generated_prefill_sg || handwritten_prefill_sg;
    uint32_t contiguous_base_token = 0;
    const bool use_prefill_direct_kv = (use_prefill_hd512 || use_prefill_sg) &&
        runtime->prefill_direct_kv_enabled &&
        termite_metal_block_table_contiguous(
            block_table,
            needed_blocks,
            page_size,
            kv_tokens,
            &contiguous_base_token);
    if (use_prefill_direct_kv) {
        params.contiguous_base_token = contiguous_base_token;
        params.contiguous_blocks = 1u;
    }
    const bool use_decode_1x = !use_decode_gqa_split && !use_prefill_hd512 && !use_prefill_sg &&
        format == 3u &&
        sinks == NULL &&
        softcap == 0.0f &&
        kv_tokens <= 4096u &&
        termite_metal_paged_attention_1x_enabled() &&
        decode_1x_pipeline != nil;
    // When the generated decode-1x candidate is built (opt-in kill switch), route
    // the decode-1x path through it instead of the hand-written kernel. Same
    // buffer bindings, grid and threadgroup memory below, so this is a pure A/B
    // of the kernel body — the model-token acceptance gate for the generated route.
    // Prefer generated flash only when its model-shape and device gates pass;
    // otherwise preserve the independently eligible hand-written flash route.
    [encoder setComputePipelineState:use_decode_gqa_split ? runtime->attention_decode_gqa_split_stage_pipeline : (use_prefill_hd512 ? prefill_hd512_pipeline : (use_prefill_sg ? prefill_sg_pipeline : (use_decode_1x ? decode_1x_pipeline : runtime->attention_paged_pipeline)))];
    [encoder setBuffer:q_buffer offset:q_offset atIndex:0];
    [encoder setBuffer:runtime->attention_span_encoded_key_buffers[slot] offset:0 atIndex:1];
    [encoder setBuffer:runtime->attention_span_v_buffers[slot] offset:0 atIndex:2];
    if (block_table_bytes <= 4096u) {
        [encoder setBytes:block_table length:block_table_bytes atIndex:3];
    } else {
        block_table_buffer = [runtime->device newBufferWithBytes:block_table length:block_table_bytes options:MTLResourceStorageModeShared];
        if (block_table_buffer == nil) return failure_code;
        [encoder setBuffer:block_table_buffer offset:0 atIndex:3];
    }
    if (sinks == NULL) {
        [encoder setBytes:&zero_sink length:sizeof(zero_sink) atIndex:4];
    } else if (sinks_bytes <= 4096u) {
        [encoder setBytes:sinks length:sinks_bytes atIndex:4];
    } else {
        sinks_buffer = [runtime->device newBufferWithBytes:sinks length:sinks_bytes options:MTLResourceStorageModeShared];
        if (sinks_buffer == nil) return failure_code;
        [encoder setBuffer:sinks_buffer offset:0 atIndex:4];
    }
    [encoder setBuffer:(use_decode_gqa_split ? runtime->attention_decode_gqa_split_scratch_buffer : output_buffer) offset:(use_decode_gqa_split ? 0u : output_offset) atIndex:5];
    [encoder setBytes:&params length:sizeof(params) atIndex:6];
    if (use_decode_gqa_split) {
        if (termite_metal_encode_decode_gqa_split_dispatch(
                runtime,
                runtime,
                encoder,
                &params,
                &split_launch,
                output_buffer,
                output_offset,
                output_bytes,
                failure_code) != 0) return failure_code;
    } else if (use_prefill_hd512) {
        runtime->generated_attention_flash_prefill_hd512_calls += 1;
        termite_metal_record_prefill_kv_route(runtime, use_prefill_direct_kv);
        [encoder setThreadgroupMemoryLength:TERMITE_METAL_GENERATED_FLASH_HD512_MEMORY_BYTES atIndex:0];
        [encoder dispatchThreadgroups:MTLSizeMake((q_len + 7u) / 8u, num_heads, 1) threadsPerThreadgroup:MTLSizeMake(TERMITE_METAL_GENERATED_FLASH_HD512_THREADS, 1, 1)];
    } else if (use_prefill_sg) {
        if (generated_prefill_sg) runtime->generated_attention_flash_prefill_calls += 1;
        termite_metal_record_prefill_kv_route(runtime, use_prefill_direct_kv);
        const size_t prefill_sg_memory_bytes = generated_prefill_sg
            ? TERMITE_METAL_GENERATED_FLASH_MEMORY_BYTES(head_dim)
            : TERMITE_METAL_HANDWRITTEN_FLASH_MEMORY_BYTES(head_dim);
        [encoder setThreadgroupMemoryLength:termite_metal_threadgroup_memory_16(prefill_sg_memory_bytes) atIndex:0];
        [encoder dispatchThreadgroups:MTLSizeMake((q_len + 7u) / 8u, num_heads, 1) threadsPerThreadgroup:MTLSizeMake(TERMITE_METAL_GENERATED_FLASH_THREADS, 1, 1)];
    } else if (use_decode_1x) {
        runtime->paged_attention_1x_calls += 1;
        if (runtime->attention_1x_generated_pipeline != nil) runtime->generated_attention_decode_1x_calls += 1;
        [encoder setThreadgroupMemoryLength:termite_metal_threadgroup_memory_16((kv_tokens * 2u + TERMITE_METAL_GENERATED_DECODE_THREADS) * sizeof(float)) atIndex:0];
        [encoder dispatchThreadgroups:MTLSizeMake(q_len, num_heads, 1) threadsPerThreadgroup:MTLSizeMake(TERMITE_METAL_GENERATED_DECODE_THREADS, 1, 1)];
    } else {
        const size_t total = q_len * num_heads;
        [encoder dispatchThreads:MTLSizeMake(total, 1, 1) threadsPerThreadgroup:MTLSizeMake(termite_metal_thread_width(runtime->attention_paged_pipeline, total), 1, 1)];
    }
    (void)block_table_buffer;
    (void)sinks_buffer;
    return 0;
}

static int termite_metal_encode_q8_0_linear_rms_add_planned_1x(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    id<MTLBuffer> linear_input_buffer,
    size_t linear_input_offset,
    id<MTLBuffer> linear_weight_buffer,
    size_t linear_weight_offset,
    id<MTLBuffer> projected_buffer,
    size_t projected_offset,
    size_t in_dim,
    size_t hidden_size,
    size_t post_rms_norm_slot,
    id<MTLBuffer> residual_buffer,
    size_t residual_offset,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    float eps,
    size_t source,
    size_t region,
    int failure_code
) {
    if (runtime == NULL || command_buffer == nil || runtime->active_frame_cb != command_buffer) return failure_code;
    if (linear_input_buffer == nil || linear_weight_buffer == nil || projected_buffer == nil || residual_buffer == nil || output_buffer == nil) return failure_code;
    if (termite_metal_decode_runtime_begin_planned_compute_scope(runtime, source, region) != 0) return failure_code;
    id<MTLComputeCommandEncoder> encoder = runtime->active_planned_compute_encoder;
    int rc = termite_metal_encode_q8_0_linear_raw_on_encoder_with_offset(
        runtime,
        encoder,
        linear_input_buffer,
        linear_input_offset,
        linear_weight_buffer,
        linear_weight_offset,
        projected_buffer,
        projected_offset,
        1,
        in_dim,
        hidden_size,
        failure_code
    );
    if (rc == 0) {
        rc = termite_metal_encode_rms_norm_add_on_encoder(
            runtime,
            encoder,
            projected_buffer,
            projected_offset,
            post_rms_norm_slot,
            residual_buffer,
            residual_offset,
            output_buffer,
            output_offset,
            hidden_size,
            eps,
            failure_code
        );
    }
    const int end_rc = termite_metal_decode_runtime_end_planned_compute_scope(runtime);
    if (rc != 0) return rc;
    return end_rc == 0 ? 0 : failure_code;
}

static int termite_metal_encode_quant_linear_rms_add_planned_1x(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    uint32_t quant_format,
    termite_metal_quant_matmul_activation_dtype input_dtype,
    termite_metal_quant_matmul_activation_dtype output_dtype,
    id<MTLBuffer> linear_input_buffer,
    size_t linear_input_offset,
    const termite_metal_quant_linear_slot_view *linear_view,
    id<MTLBuffer> projected_buffer,
    size_t projected_offset,
    size_t in_dim,
    size_t hidden_size,
    size_t post_rms_norm_slot,
    id<MTLBuffer> residual_buffer,
    size_t residual_offset,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    float eps,
    int output_scale_present,
    float output_scale,
    size_t source,
    size_t region,
    int failure_code
) {
    if (runtime == NULL || command_buffer == nil || runtime->active_frame_cb != command_buffer) return failure_code;
    if (linear_input_buffer == nil || linear_view == NULL || linear_view->weight_buffer == nil || projected_buffer == nil || residual_buffer == nil || output_buffer == nil) return failure_code;
    if (in_dim == 0 || hidden_size == 0 || in_dim > UINT32_MAX || hidden_size > UINT32_MAX) return failure_code;
    id<MTLBuffer> sumsq_buffer = nil;
    const size_t sumsq_partials = (hidden_size + 7u) / 8u;
    const BOOL can_use_sumsq =
        quant_format == TERMITE_METAL_QUANT_FORMAT_Q4_0 &&
        output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 &&
        output_scale_present == 0 &&
        !termite_metal_q4_0_linear_rms_add_sumsq_disabled() &&
        runtime->rms_norm_add_sumsq_pipeline != nil &&
        ((input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32 && runtime->q4_0_reduce_sumsq_pipeline != nil) ||
            (input_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16 && runtime->q4_0_reduce_f16_input_sumsq_pipeline != nil));
    if (can_use_sumsq) {
        for (int i = 3; i >= 0; --i) {
            id<MTLBuffer> candidate = runtime->hot_hidden_buffers[i];
            if (candidate != nil &&
                candidate != projected_buffer &&
                candidate != linear_input_buffer &&
                candidate != residual_buffer &&
                candidate != output_buffer)
            {
                sumsq_buffer = candidate;
                break;
            }
        }
    }
    if (termite_metal_decode_runtime_begin_planned_compute_scope(runtime, source, region) != 0) return failure_code;
    id<MTLComputeCommandEncoder> encoder = runtime->active_planned_compute_encoder;
    termite_metal_quant_matmul_descriptor descriptor = {
        .slot = SIZE_MAX,
        .format = quant_format,
        .activation_dtype = TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32,
        .input_dtype = input_dtype,
        .output_dtype = output_dtype,
        .epilogue = TERMITE_METAL_QUANT_MATMUL_EPILOGUE_NONE,
        .fallback_pipeline = linear_view->pipeline,
        .input_buffer = linear_input_buffer,
        .input_offset = linear_input_offset,
        .weight_buffer = linear_view->weight_buffer,
        .weight_offset = linear_view->weight_offset,
        .output_buffer = projected_buffer,
        .output_offset = projected_offset,
        .sumsq_buffer = sumsq_buffer,
        .sumsq_offset = 0,
        .sumsq_partials = sumsq_buffer != nil ? sumsq_partials : 0,
        .rows = 1,
        .in_dim = in_dim,
        .out_dim = hidden_size,
        .values_per_block = linear_view->values_per_block,
        .bytes_per_block = linear_view->bytes_per_block,
        .q4_0_mmv_workload = source == TERMITE_METAL_COMPUTE_SOURCE_ATTENTION
            ? TERMITE_METAL_Q4_0_MMV_WORKLOAD_ATTENTION
            : source == TERMITE_METAL_COMPUTE_SOURCE_FFN
            ? TERMITE_METAL_Q4_0_MMV_WORKLOAD_FFN_DOWN
            : source == TERMITE_METAL_COMPUTE_SOURCE_PLE
            ? TERMITE_METAL_Q4_0_MMV_WORKLOAD_PLE
            : source == TERMITE_METAL_COMPUTE_SOURCE_TAIL
            ? TERMITE_METAL_Q4_0_MMV_WORKLOAD_TAIL
            : TERMITE_METAL_Q4_0_MMV_WORKLOAD_UNKNOWN,
        .failure_code = failure_code,
    };
    int rc = termite_metal_encode_quant_matmul_descriptor_on_encoder(runtime, encoder, &descriptor);
    if (rc == 0) {
        rc = sumsq_buffer != nil && output_scale_present != 0
            ? termite_metal_encode_rms_norm_add_scale_sumsq_on_encoder(
                runtime,
                encoder,
                projected_buffer,
                projected_offset,
                sumsq_buffer,
                0,
                sumsq_partials,
                post_rms_norm_slot,
                residual_buffer,
                residual_offset,
                output_buffer,
                output_offset,
                hidden_size,
                eps,
                output_scale,
                failure_code
            )
            : sumsq_buffer != nil
            ? termite_metal_encode_rms_norm_add_sumsq_on_encoder(
                runtime,
                encoder,
                projected_buffer,
                projected_offset,
                sumsq_buffer,
                0,
                sumsq_partials,
                post_rms_norm_slot,
                residual_buffer,
                residual_offset,
                output_buffer,
                output_offset,
                hidden_size,
                eps,
                failure_code
            )
            : output_scale_present != 0
            ? (output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32
                ? termite_metal_encode_rms_norm_add_scale_on_encoder(
                    runtime,
                    encoder,
                    projected_buffer,
                    projected_offset,
                    post_rms_norm_slot,
                    residual_buffer,
                    residual_offset,
                    output_buffer,
                    output_offset,
                    hidden_size,
                    eps,
                    output_scale,
                    failure_code
                )
                : failure_code)
            : output_dtype == TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F16
            ? termite_metal_encode_rms_norm_add_f16_input_on_encoder(
                runtime,
                encoder,
                projected_buffer,
                projected_offset,
                post_rms_norm_slot,
                residual_buffer,
                residual_offset,
                output_buffer,
                output_offset,
                hidden_size,
                eps,
                failure_code
            )
            : termite_metal_encode_rms_norm_add_on_encoder(
                runtime,
                encoder,
                projected_buffer,
                projected_offset,
                post_rms_norm_slot,
                residual_buffer,
                residual_offset,
                output_buffer,
                output_offset,
                hidden_size,
                eps,
                failure_code
            );
    }
    const int end_rc = termite_metal_decode_runtime_end_planned_compute_scope(runtime);
    if (rc != 0) return rc;
    return end_rc == 0 ? 0 : failure_code;
}

