                case TERMITE_METAL_PLAN_OP_DECODE_PLE_PROJECTION: {
                    if (!termite_metal_runtime_operator_is_quant_matmul(op.op)) {
                        rc = failure_code;
                        break;
                    }
                    if (!termite_metal_runtime_command_format_matches_quant(op.format, TERMITE_METAL_QUANT_FORMAT_Q8_0)) {
                        rc = failure_code;
                        break;
                    }
                    termite_metal_quant_matmul_descriptor descriptor = {
                        .slot = ple_proj_linear_slot,
                        .format = TERMITE_METAL_QUANT_FORMAT_Q8_0,
                        .activation_dtype = TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32,
                        .input_dtype = termite_metal_quant_matmul_dtype_from_command(op.input_dtype),
                        .output_dtype = termite_metal_quant_matmul_dtype_from_command(op.output_dtype),
                        .epilogue = TERMITE_METAL_QUANT_MATMUL_EPILOGUE_NONE,
                        .fallback_pipeline = runtime->q8_0_pipeline,
                        .input_buffer = ple_gated_buffer,
                        .weight_buffer = ple_proj_view.weight_buffer,
                        .weight_offset = ple_proj_view.weight_offset,
                        .output_buffer = ple_projected_buffer,
                        .rows = 1,
                        .in_dim = ple_hidden_size,
                        .out_dim = hidden_size,
                        .values_per_block = 32u,
                        .bytes_per_block = 34u,
                        .q8_family = TERMITE_METAL_Q8_0_LINEAR_FAMILY_PLE_PROJECTION,
                        .use_planned_dispatch = true,
                        .planned_dispatch = op.quant_dispatch,
                        .failure_code = failure_code,
                    };
                    rc = termite_metal_encode_quant_matmul_descriptor_on_encoder(runtime, encoder, &descriptor);
                    break;
                }
                case TERMITE_METAL_PLAN_OP_DECODE_PLE_POST_NORM_RESIDUAL:
                    rc = output_scale_present != 0
                        ? termite_metal_encode_rms_norm_add_scale_on_encoder(
                            runtime,
                            encoder,
                            ple_projected_buffer,
                            0,
                            ple_post_norm_slot,
                            ffn_output_buffer,
                            ffn_output_offset,
                            output_buffer,
                            output_offset,
                            hidden_size,
                            eps,
                            output_scale,
                            failure_code)
                        : termite_metal_encode_rms_norm_add_on_encoder(
                            runtime,
                            encoder,
                            ple_projected_buffer,
                            0,
                            ple_post_norm_slot,
                            ffn_output_buffer,
                            ffn_output_offset,
                            output_buffer,
                            output_offset,
                            hidden_size,
                            eps,
                            failure_code);
                    break;
                default:
                    rc = failure_code;
                    break;
            }
            if (trace_q80_block && rc != 0) {
                fprintf(
                    stderr,
                    "metal-planned-q80-1x-op-fail index=%zu kind=%u op=%u format=%u dispatch=%u rc=%d paged=%d suffix=%zu\n",
                    op_index,
                    (unsigned)op.kind,
                    (unsigned)op.op,
                    (unsigned)op.format,
                    (unsigned)op.quant_dispatch,
                    rc,
                    use_paged_kv ? 1 : 0,
                    paged_suffix_tokens
                );
            }
        }
	        const int end_rc = termite_metal_decode_runtime_end_planned_compute_scope(runtime);
        if (trace_q80_block && rc == 0 && end_rc != 0) {
            fprintf(stderr, "metal-planned-q80-1x-fail reason=end-scope rc=%d\n", end_rc);
        }
        if (rc != 0) return rc;
#undef TERMITE_Q80_PLANNED_FAIL
        return end_rc == 0 ? 0 : failure_code;
    }
    termite_metal_planned_layer_cursor planned_cursor = termite_metal_planned_layer_cursor_make(runtime, planned_contract, failure_code);
    int rc = 0;
    rc = termite_metal_planned_layer_cursor_before_step(&planned_cursor, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_KINDS, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_COUNT, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_ATTENTION);
	    if (rc == 0 && use_paged_kv) {
	        if (paged_suffix_tokens != 0) {
	            if (rc == 0 && (paged_format == 0u || paged_format == 1u || paged_format == 4u)) {
                rc = termite_metal_encode_paged_quantized_kv_seed_on_encoder(
                    runtime,
                    encoder,
                    paged_slot,
                    paged_format,
                    k_buffer,
                    k_offset,
                    v_buffer,
                    v_offset,
                    kv_tokens,
                    paged_suffix_tokens,
                    num_kv_heads,
                    head_dim,
                    paged_key_row_bytes,
                    paged_base_key_row_bytes,
                    paged_v_row_stride,
                    kv_position_offset,
                    paged_block_table,
                    paged_block_count,
                    paged_page_size,
	                    failure_code);
	            } else {
                if (termite_metal_decode_runtime_end_planned_compute_scope(runtime) != 0) {
                    rc = failure_code;
                }
                if (rc == 0) {
                    rc = termite_metal_decode_runtime_encode_attention_paged_update_from_f32_key_device_slot(
                        runtime,
                        command_buffer,
                        paged_slot,
                        paged_format,
                        (__bridge void *)k_buffer,
                        k_offset,
                        (__bridge void *)v_buffer,
                        v_offset,
                        kv_tokens,
                        paged_suffix_tokens,
                        num_kv_heads,
                        head_dim,
                        paged_key_row_bytes,
                        paged_base_key_row_bytes,
                        paged_v_row_stride,
                        kv_position_offset,
                        paged_block_table,
                        paged_block_count,
                        paged_page_size);
                }
                if (rc == 0 && termite_metal_decode_runtime_begin_planned_compute_scope(runtime, TERMITE_METAL_COMPUTE_SOURCE_LAYER, TERMITE_METAL_COMPUTE_REGION_LAYER) != 0) rc = failure_code;
	                encoder = runtime->active_planned_compute_encoder;
	                if (rc == 0 && encoder == nil) rc = failure_code;
	            }
	        }
        if (rc == 0) rc = termite_metal_encode_paged_attention_slot_on_encoder(
            runtime,
            encoder,
            paged_slot,
            paged_format,
            q_buffer,
            q_offset,
            paged_block_table,
            paged_block_count,
            paged_page_size,
            1,
            kv_tokens,
            num_heads,
            num_kv_heads,
            head_dim,
            paged_key_row_bytes,
            paged_base_key_row_bytes,
            query_position_offset,
            kv_position_offset,
            sliding_window,
            0.0f,
            NULL,
            0,
            attention_output_buffer,
            0,
            failure_code
        );
    } else if (rc == 0) rc = termite_metal_encode_attention_f32_on_encoder(
        runtime,
        encoder,
        q_buffer,
        q_offset,
        k_buffer,
        k_offset,
        v_buffer,
