        attention_output_buffer,
        0,
        1,
        kv_tokens,
        num_heads,
        num_kv_heads,
        head_dim,
        query_position_offset,
        kv_position_offset,
        sliding_window,
        total_sequence_len,
        failure_code
    );
    if (rc == 0) rc = termite_metal_planned_layer_cursor_fallback_barrier_after_op(&planned_cursor);
    if (rc == 0) {
        rc = termite_metal_planned_layer_cursor_before_step(&planned_cursor, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_KINDS, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_COUNT, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_ATTENTION_OUTPUT_LINEAR);
    }
    if (rc == 0) {
        termite_metal_quant_matmul_descriptor descriptor = {
            .slot = attention_linear_slot,
