    if (rc == 0) rc = termite_metal_planned_layer_cursor_fallback_barrier_after_op(&planned_cursor);
    if (rc == 0) {
        rc = termite_metal_planned_layer_cursor_before_step(&planned_cursor, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_KINDS, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_COUNT, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_FFN_GATE_UP_ACTIVATION);
