    if (rc == 0) rc = termite_metal_planned_layer_cursor_fallback_barrier_after_op(&planned_cursor);
    if (rc == 0) {
        rc = termite_metal_planned_layer_cursor_before_step(&planned_cursor, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_KINDS, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_COUNT, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_FFN_DOWN_LINEAR);
    }
    if (rc == 0) {
        termite_metal_quant_matmul_descriptor descriptor = {
            .slot = down_ffn_linear_slot,
            .format = TERMITE_METAL_QUANT_FORMAT_Q8_0,
            .activation_dtype = TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32,
