        rc = termite_metal_encode_quant_matmul_descriptor_on_encoder(runtime, encoder, &descriptor);
    }
    if (rc == 0) rc = termite_metal_planned_layer_cursor_fallback_barrier_after_op(&planned_cursor);
    if (rc == 0) {
        rc = termite_metal_planned_layer_cursor_before_step(&planned_cursor, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_KINDS, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_COUNT, TERMITE_METAL_Q80_F32_KV_LAYER_STEP_FFN_POST_NORM_RESIDUAL);
    }
    if (rc == 0) {
        rc = termite_metal_encode_rms_norm_add_on_encoder(
            runtime,
            encoder,
            ffn_projected_buffer,
            0,
            ffn_post_down_rms_norm_slot,
