                ple_post_norm_slot,
                ffn_output_buffer,
                ffn_output_offset,
                output_buffer,
                output_offset,
                hidden_size,
                eps,
                failure_code);
    }
    const int end_rc = termite_metal_decode_runtime_end_planned_compute_scope(runtime);
    if (rc != 0) return rc;
    return end_rc == 0 ? 0 : failure_code;
}

static int termite_metal_encode_rms_norm_add_scale_for(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    id<MTLBuffer> input_buffer,
    size_t input_offset,
    size_t norm_slot,
    id<MTLBuffer> residual_buffer,
    size_t residual_offset,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    size_t hidden_size,
    float eps,
    float scale,
    size_t source,
    int failure_code
) {
    if (runtime == NULL || command_buffer == nil || input_buffer == nil || residual_buffer == nil || output_buffer == nil) return failure_code;
    if (runtime->rms_norm_add_scale_pipeline == nil) return failure_code;
    if (norm_slot >= TERMITE_METAL_RMS_NORM_SLOT_CAPACITY) return failure_code;
    if (runtime->rms_norm_slot_prepared[norm_slot] == 0 || runtime->rms_norm_hidden_sizes[norm_slot] != hidden_size) return failure_code;
    if (hidden_size == 0 || hidden_size > UINT32_MAX) return failure_code;
    size_t hidden_bytes = 0;
    if (!termite_metal_size_mul(hidden_size, sizeof(float), &hidden_bytes)) return failure_code;
    termite_metal_planned_encoder_range accesses[4];
    if (termite_metal_planned_range_make(input_buffer, input_offset, hidden_bytes, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[0], failure_code) != 0 ||
        termite_metal_planned_range_make(runtime->rms_norm_weight_buffers[norm_slot], 0, runtime->rms_norm_weight_buffers[norm_slot].length, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[1], failure_code) != 0 ||
        termite_metal_planned_range_make(residual_buffer, residual_offset, hidden_bytes, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[2], failure_code) != 0 ||
        termite_metal_planned_range_make(output_buffer, output_offset, hidden_bytes, TERMITE_METAL_PLANNED_RANGE_WRITE, &accesses[3], failure_code) != 0 ||
        termite_metal_decode_runtime_prepare_planned_compute_accesses(runtime, accesses, 4, failure_code) != 0)
    {
        return failure_code;
    }
    termite_metal_apply_layer_norm_scale_params params = {
        .hidden_size = (uint32_t)hidden_size,
        .eps = eps,
        .scale = scale,
        .reserved = 0,
    };
    id<MTLBuffer> params_buffer = [runtime->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
    if (params_buffer == nil) return failure_code;
    if (runtime->active_frame_cb == command_buffer && termite_metal_decode_runtime_retain_frame_resource(runtime, params_buffer) != 0) return failure_code;
    id<MTLComputeCommandEncoder> encoder = runtime->active_planned_compute_encoder;
    const BOOL planned_encoder = (encoder != nil);
    if (!planned_encoder) {
        encoder = termite_metal_tracked_compute_command_encoder_for(command_buffer, source);
        if (encoder == nil) return failure_code;
    }
    [encoder setComputePipelineState:runtime->rms_norm_add_scale_pipeline];
    [encoder setBuffer:input_buffer offset:input_offset atIndex:0];
    [encoder setBuffer:runtime->rms_norm_weight_buffers[norm_slot] offset:0 atIndex:1];
    [encoder setBuffer:residual_buffer offset:residual_offset atIndex:2];
    [encoder setBuffer:output_buffer offset:output_offset atIndex:3];
    [encoder setBuffer:params_buffer offset:0 atIndex:4];
    [encoder setThreadgroupMemoryLength:256u * sizeof(float) atIndex:0];
    [encoder dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    if (!planned_encoder) [encoder endEncoding];
    return 0;
}

static int termite_metal_encode_rms_norm_add_scale_rows_for(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    id<MTLBuffer> input_buffer,
    size_t input_offset,
    size_t norm_slot,
    id<MTLBuffer> residual_buffer,
    size_t residual_offset,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    size_t rows,
    size_t hidden_size,
    float eps,
    float scale,
    size_t source,
    int failure_code
) {
    if (runtime == NULL || command_buffer == nil || input_buffer == nil || residual_buffer == nil || output_buffer == nil) return failure_code;
    if (runtime->rms_norm_add_scale_rows_pipeline == nil) return failure_code;
    if (norm_slot >= TERMITE_METAL_RMS_NORM_SLOT_CAPACITY) return failure_code;
    if (runtime->rms_norm_slot_prepared[norm_slot] == 0 || runtime->rms_norm_hidden_sizes[norm_slot] != hidden_size) return failure_code;
    if (rows == 0 || hidden_size == 0 || rows > UINT32_MAX || hidden_size > UINT32_MAX) return failure_code;
    size_t elems = 0;
    size_t bytes = 0;
    if (!termite_metal_size_mul(rows, hidden_size, &elems) ||
        !termite_metal_size_mul(elems, sizeof(float), &bytes))
    {
        return failure_code;
    }
    termite_metal_planned_encoder_range accesses[4];
    if (termite_metal_planned_range_make(input_buffer, input_offset, bytes, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[0], failure_code) != 0 ||
        termite_metal_planned_range_make(runtime->rms_norm_weight_buffers[norm_slot], 0, runtime->rms_norm_weight_buffers[norm_slot].length, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[1], failure_code) != 0 ||
        termite_metal_planned_range_make(residual_buffer, residual_offset, bytes, TERMITE_METAL_PLANNED_RANGE_READ, &accesses[2], failure_code) != 0 ||
        termite_metal_planned_range_make(output_buffer, output_offset, bytes, TERMITE_METAL_PLANNED_RANGE_WRITE, &accesses[3], failure_code) != 0 ||
        termite_metal_decode_runtime_prepare_planned_compute_accesses(runtime, accesses, 4, failure_code) != 0)
    {
        return failure_code;
    }
    termite_metal_apply_row_norm_scale_params params = {
        .rows = (uint32_t)rows,
        .hidden_size = (uint32_t)hidden_size,
        .eps = eps,
        .scale = scale,
    };
    id<MTLBuffer> params_buffer = [runtime->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
    if (params_buffer == nil) return failure_code;
    if (runtime->active_frame_cb == command_buffer && termite_metal_decode_runtime_retain_frame_resource(runtime, params_buffer) != 0) return failure_code;
    id<MTLComputeCommandEncoder> encoder = runtime->active_planned_compute_encoder;
    const BOOL planned_encoder = (encoder != nil);
    if (!planned_encoder) {
        encoder = termite_metal_tracked_compute_command_encoder_for(command_buffer, source);
        if (encoder == nil) return failure_code;
    }
    [encoder setComputePipelineState:runtime->rms_norm_add_scale_rows_pipeline];
    [encoder setBuffer:input_buffer offset:input_offset atIndex:0];
    [encoder setBuffer:runtime->rms_norm_weight_buffers[norm_slot] offset:0 atIndex:1];
    [encoder setBuffer:residual_buffer offset:residual_offset atIndex:2];
    [encoder setBuffer:output_buffer offset:output_offset atIndex:3];
    [encoder setBuffer:params_buffer offset:0 atIndex:4];
    [encoder setThreadgroupMemoryLength:256u * sizeof(float) atIndex:0];
    [encoder dispatchThreadgroups:MTLSizeMake(rows, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    if (!planned_encoder) [encoder endEncoding];
    return 0;
}

static int termite_metal_encode_rms_norm_add_rows_for(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    id<MTLBuffer> input_buffer,
    size_t input_offset,
    size_t norm_slot,
    id<MTLBuffer> residual_buffer,
    size_t residual_offset,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    size_t rows,
    size_t hidden_size,
    float eps,
    size_t source,
    int failure_code
) {
    return termite_metal_encode_rms_norm_add_scale_rows_for(
        runtime,
        command_buffer,
        input_buffer,
        input_offset,
        norm_slot,
        residual_buffer,
        residual_offset,
        output_buffer,
        output_offset,
        rows,
        hidden_size,
        eps,
        1.0f,
        source,
        failure_code
    );
}

// Small row counts over a wide hidden dim (the MTP-verify shapes) may route to
// the threadgroup-per-row reduce kernel: the thread-per-row kernel dispatches
// only `rows` threads total, each serially scanning hidden_size twice, which
// on the serial planned frame encoder is a near-idle GPU stall per norm. The
// shape gate is deliberately narrow, and rollout remains explicit opt-in.
static bool termite_metal_rms_norm_rows_reduce_preferred(
    termite_metal_decode_runtime *runtime,
    size_t rows,
    size_t hidden_size
) {
    if (rows < 2 || rows > 8) return false;
    if (hidden_size < 1024) return false;
    if (runtime == NULL || runtime->rms_norm_rows_reduce_pipeline == nil) return false;
    if (runtime->rms_norm_rows_reduce_pipeline.maxTotalThreadsPerThreadgroup < 256) return false;
    static int enabled = -1;
    if (enabled < 0) {
        enabled = termite_metal_env_flag_enabled(getenv("TERMITE_METAL_ENABLE_SMALL_ROWS_NORM_REDUCE")) &&
            !termite_metal_env_flag_enabled(getenv("TERMITE_METAL_DISABLE_SMALL_ROWS_NORM_REDUCE"));
    }
    return enabled == 1;
}

static void termite_metal_dispatch_rms_norm_rows(
    termite_metal_decode_runtime *runtime,
    id<MTLComputeCommandEncoder> encoder,
    size_t rows,
    size_t hidden_size
) {
    if (termite_metal_rms_norm_rows_reduce_preferred(runtime, rows, hidden_size)) {
        [encoder setComputePipelineState:runtime->rms_norm_rows_reduce_pipeline];
        [encoder setThreadgroupMemoryLength:256u * sizeof(float) atIndex:0];
        [encoder dispatchThreadgroups:MTLSizeMake(rows, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        return;
    }
    [encoder setComputePipelineState:runtime->rms_norm_rows_pipeline];
    [encoder dispatchThreads:MTLSizeMake(rows, 1, 1) threadsPerThreadgroup:MTLSizeMake(termite_metal_thread_width(runtime->rms_norm_rows_pipeline, rows), 1, 1)];
}

static int termite_metal_encode_rms_norm_rows(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    id<MTLBuffer> input_buffer,
    size_t input_offset,
    size_t norm_slot,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    size_t rows,
    size_t hidden_size,
    float eps,
    int failure_code
) {
    if (runtime == NULL || command_buffer == nil || input_buffer == nil || output_buffer == nil) return failure_code;
    if (runtime->rms_norm_rows_pipeline == nil) return failure_code;
    if (norm_slot >= TERMITE_METAL_RMS_NORM_SLOT_CAPACITY) return failure_code;
    if (runtime->rms_norm_slot_prepared[norm_slot] == 0 || runtime->rms_norm_hidden_sizes[norm_slot] != hidden_size) return failure_code;
    if (rows == 0 || hidden_size == 0 || rows > UINT32_MAX || hidden_size > UINT32_MAX) return failure_code;
    size_t elems = 0;
    size_t bytes = 0;
    if (!termite_metal_size_mul(rows, hidden_size, &elems) ||
        !termite_metal_size_mul(elems, sizeof(float), &bytes))
    {
        return failure_code;
    }
    if (termite_metal_decode_runtime_prepare_planned_compute_norm_accesses(
            runtime,
            input_buffer,
            input_offset,
            bytes,
            runtime->rms_norm_weight_buffers[norm_slot],
            output_buffer,
            output_offset,
            bytes,
            failure_code) != 0)
    {
        return failure_code;
    }
    if (runtime->rms_norm_generated_pipeline != nil) {
        return termite_metal_encode_rms_norm_generated(
            runtime,
            command_buffer,
            input_buffer,
            input_offset,
            runtime->rms_norm_weight_buffers[norm_slot],
            0,
            output_buffer,
            output_offset,
            rows,
            hidden_size,
            eps,
            failure_code);
    }
    termite_metal_apply_row_norm_params params = {
        .rows = (uint32_t)rows,
        .hidden_size = (uint32_t)hidden_size,
        .eps = eps,
    };
    id<MTLComputeCommandEncoder> encoder = runtime->active_planned_compute_encoder;
    const BOOL planned_encoder = (encoder != nil);
    if (!planned_encoder) {
        encoder = termite_metal_tracked_compute_command_encoder_for(command_buffer, TERMITE_METAL_COMPUTE_SOURCE_RMS_NORM);
        if (encoder == nil) return failure_code;
    }
    [encoder setBuffer:input_buffer offset:input_offset atIndex:0];
    [encoder setBuffer:runtime->rms_norm_weight_buffers[norm_slot] offset:0 atIndex:1];
    [encoder setBuffer:output_buffer offset:output_offset atIndex:2];
    [encoder setBytes:&params length:sizeof(params) atIndex:3];
    termite_metal_dispatch_rms_norm_rows(runtime, encoder, rows, hidden_size);
    if (!planned_encoder) [encoder endEncoding];
    return 0;
}

// Dispatch the generated RMSNorm microkernel candidate. Binds the descriptor
// renderer's self-contained scalar layout (input, weight, output, rows,
// hidden_size, eps) and launches one threadgroup per row with the schedule's
// fixed 256-thread reduction. The regular rows path selects this encoder when
// the explicit generated-route opt-in successfully built the pipeline.
static int termite_metal_encode_rms_norm_generated(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    id<MTLBuffer> input_buffer,
    size_t input_offset,
    id<MTLBuffer> weight_buffer,
    size_t weight_offset,
    id<MTLBuffer> output_buffer,
    size_t output_offset,
    size_t rows,
    size_t hidden_size,
    float eps,
    int failure_code
) {
    if (runtime == NULL || command_buffer == nil || input_buffer == nil || weight_buffer == nil || output_buffer == nil) return failure_code;
    if (runtime->rms_norm_generated_pipeline == nil) return failure_code;
    if (rows == 0 || hidden_size == 0 || rows > INT32_MAX || hidden_size > INT32_MAX) return failure_code;
    const NSUInteger reduction_threads = TERMITE_METAL_GENERATED_RMS_THREADS;
    if (runtime->rms_norm_generated_pipeline.maxTotalThreadsPerThreadgroup < reduction_threads) return failure_code;
    const int rows_i = (int)rows;
    const int hidden_size_i = (int)hidden_size;
    const float eps_f = eps;
    id<MTLComputeCommandEncoder> encoder = runtime->active_planned_compute_encoder;
    const BOOL planned_encoder = (encoder != nil);
    if (!planned_encoder) {
        encoder = termite_metal_tracked_compute_command_encoder_for(command_buffer, TERMITE_METAL_COMPUTE_SOURCE_RMS_NORM);
        if (encoder == nil) return failure_code;
    }
    [encoder setComputePipelineState:runtime->rms_norm_generated_pipeline];
    [encoder setBuffer:input_buffer offset:input_offset atIndex:0];
    [encoder setBuffer:weight_buffer offset:weight_offset atIndex:1];
    [encoder setBuffer:output_buffer offset:output_offset atIndex:2];
    [encoder setBytes:&rows_i length:sizeof(rows_i) atIndex:3];
    [encoder setBytes:&hidden_size_i length:sizeof(hidden_size_i) atIndex:4];
    [encoder setBytes:&eps_f length:sizeof(eps_f) atIndex:5];
    [encoder dispatchThreadgroups:MTLSizeMake(rows, 1, 1) threadsPerThreadgroup:MTLSizeMake(reduction_threads, 1, 1)];
    runtime->generated_rms_norm_calls += 1;
    if (!planned_encoder) [encoder endEncoding];
    return 0;
}

static int termite_metal_encode_add(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
