        provider->polar4_key_scores_pipeline = termite_metal_make_pipeline(device, library, @"termite_polar4_key_scores");
        provider->turbo3_key_scores_pipeline = termite_metal_make_pipeline(device, library, @"termite_turbo3_key_scores");
        if (provider->q4_0_pipeline == nil || provider->q4_1_pipeline == nil || provider->q5_0_pipeline == nil || provider->q5_1_pipeline == nil || provider->q8_0_pipeline == nil || provider->q8_1_pipeline == nil || provider->q8_0_mmv_pipeline == nil || provider->q8_0_small_batch_r2_pipeline == nil || provider->q8_0_small_batch_r3_pipeline == nil || provider->q8_0_small_batch_r4_pipeline == nil || provider->q8_0_small_batch_pipeline == nil || provider->q8_0_mm_pipeline == nil || provider->q2_k_pipeline == nil || provider->q3_k_pipeline == nil || provider->q4_k_pipeline == nil || provider->q5_k_pipeline == nil || provider->q6_k_pipeline == nil || provider->q8_k_pipeline == nil || provider->iq4_nl_pipeline == nil || provider->iq4_xs_pipeline == nil || provider->mxfp4_pipeline == nil || provider->i2_s_pipeline == nil || provider->i2_s_pair_pipeline == nil || provider->tl1_pipeline == nil || provider->tl2_pipeline == nil || provider->polar4_key_scores_pipeline == nil || provider->turbo3_key_scores_pipeline == nil) {
            free(provider);
            return NULL;
        }
        return provider;
    }
}

void termite_metal_provider_destroy(termite_metal_provider *provider) {
    if (provider == NULL) return;
    @autoreleasepool {
        provider->q4_0_pipeline = nil;
        provider->antfly_q4_0_small_batch_pipeline = nil;
        provider->q4_1_pipeline = nil;
        provider->antfly_q4_1_small_batch_pipeline = nil;
        provider->q5_0_pipeline = nil;
        provider->antfly_q5_0_small_batch_pipeline = nil;
        provider->q5_1_pipeline = nil;
        provider->antfly_q5_1_small_batch_pipeline = nil;
        provider->q8_0_pipeline = nil;
        provider->q8_1_pipeline = nil;
        provider->antfly_q8_0_small_batch_pipeline = nil;
        provider->antfly_q8_1_small_batch_pipeline = nil;
        provider->antfly_q8_0_small_batch_bias_pipeline = nil;
        provider->antfly_q8_0_small_batch_bias_gelu_pipeline = nil;
        provider->antfly_q8_0_small_batch_relu_pipeline = nil;
        provider->q2_k_pipeline = nil;
        provider->antfly_q2_k_small_batch_pipeline = nil;
        provider->antfly_q2_k_small_batch_bias_pipeline = nil;
        provider->antfly_q2_k_small_batch_bias_gelu_pipeline = nil;
        provider->q3_k_pipeline = nil;
        provider->antfly_q3_k_small_batch_pipeline = nil;
        provider->antfly_q3_k_small_batch_bias_pipeline = nil;
        provider->antfly_q3_k_small_batch_bias_gelu_pipeline = nil;
        provider->q4_k_pipeline = nil;
        provider->antfly_q4_k_small_batch_pipeline = nil;
        provider->antfly_q4_k_small_batch_bias_pipeline = nil;
        provider->antfly_q4_k_small_batch_bias_gelu_pipeline = nil;
        provider->q5_k_pipeline = nil;
        provider->antfly_q5_k_small_batch_pipeline = nil;
        provider->antfly_q5_k_small_batch_bias_pipeline = nil;
        provider->antfly_q5_k_small_batch_bias_gelu_pipeline = nil;
        provider->q6_k_pipeline = nil;
        provider->antfly_q6_k_small_batch_pipeline = nil;
        provider->antfly_q6_k_small_batch_bias_pipeline = nil;
        provider->antfly_q6_k_small_batch_bias_gelu_pipeline = nil;
        provider->q8_k_pipeline = nil;
        provider->antfly_q8_k_small_batch_pipeline = nil;
        provider->iq4_nl_pipeline = nil;
        provider->iq4_xs_pipeline = nil;
        provider->mxfp4_pipeline = nil;
        provider->i2_s_pipeline = nil;
        provider->i2_s_pair_pipeline = nil;
        provider->tl1_pipeline = nil;
        provider->tl2_pipeline = nil;
        provider->polar4_key_scores_pipeline = nil;
        provider->turbo3_key_scores_pipeline = nil;
        for (size_t route = 0; route < TERMITE_METAL_JIT_EXACT_ROUTE_COUNT; ++route) {
            const size_t count = provider->jit_exact_pipeline_counts[route] <= TERMITE_METAL_JIT_EXACT_PIPELINES_PER_ROUTE
                ? provider->jit_exact_pipeline_counts[route]
                : TERMITE_METAL_JIT_EXACT_PIPELINES_PER_ROUTE;
            for (size_t index = 0; index < count; ++index) {
                provider->jit_exact_pipelines[route][index].pipeline = nil;
                provider->jit_exact_pipelines[route][index].qkv_pipeline = nil;
            }
            provider->jit_exact_pipeline_counts[route] = 0;
        }
        provider->queue = nil;
        provider->device = nil;
        free(provider);
    }
}

static void termite_metal_paged_kv_slot_leases_init(
    termite_metal_decode_runtime *runtime
) {
    for (size_t slot = 0; slot < TERMITE_METAL_PAGED_KV_SLOT_CAPACITY; ++slot) {
        atomic_init(&runtime->attention_span_paged_slot_leased[slot], 0);
    }
}

termite_metal_decode_runtime *termite_metal_decode_runtime_create(void) {
    @autoreleasepool {
        id<MTLDevice> device = termite_metal_shared_device();
        if (device == nil) {
            fprintf(stderr, "metal-runtime-create: device=nil\n");
            return NULL;
        }
        id<MTLCommandQueue> queue = [device newCommandQueue];
        if (queue == nil) {
            fprintf(stderr, "metal-runtime-create: queue=nil\n");
            return NULL;
        }
        id<MTLLibrary> library = termite_metal_shared_library(device, NO);
        if (library == nil) {
            fprintf(stderr, "metal-runtime-create: library=nil\n");
            return NULL;
        }
        id<MTLLibrary> precise_library = termite_metal_shared_library(device, YES);
        if (precise_library == nil) precise_library = library;

        termite_metal_decode_runtime *runtime = calloc(1, sizeof(termite_metal_decode_runtime));
        if (runtime == NULL) return NULL;
        termite_metal_jit_exact_dispatch_stats_init(runtime);
        termite_metal_paged_kv_slot_leases_init(runtime);
        runtime->buffer_reuse_enabled = -1;
        runtime->device = device;
        runtime->queue = queue;
        runtime->library = library;
        runtime->precise_library = precise_library;
        runtime->apple_gpu_family = termite_metal_device_apple_gpu_family(device);
        runtime->apple_m4_device = device != nil &&
            runtime->apple_gpu_family == 9u &&
            [device.name hasPrefix:@"Apple M4"];
        runtime->prefill_direct_kv_enabled = termite_metal_prefill_direct_kv_enabled_for_device(
            device,
            runtime->apple_gpu_family);
        runtime->swa_scan_clamp_enabled =
            !termite_metal_env_flag_enabled(getenv("TERMITE_METAL_DISABLE_SWA_SCAN_CLAMP"));
        runtime->fast_prepared_frame_enabled = termite_metal_fast_prepared_frame_enabled_for_device(
            device,
            runtime->apple_gpu_family);
        const char *decode_gqa_split_enable_value =
            getenv("TERMITE_METAL_ENABLE_DECODE_GQA_SPLIT");
        runtime->decode_gqa_split_enabled = termite_metal_decode_gqa_split_environment_enabled();
        runtime->trace_decode_gqa_split_schedule = termite_metal_env_flag_enabled(
            getenv("TERMITE_METAL_TRACE_DECODE_GQA_SPLIT_SCHEDULE"));
        bool decode_gqa_split_swa_override_valid = true;
        const char *decode_gqa_split_swa_override_value =
            getenv("TERMITE_METAL_DECODE_GQA_SPLIT_SWA_VARIANT");
        runtime->decode_gqa_split_swa_variant_override =
            (uint8_t)termite_metal_decode_gqa_split_variant_parse(
                decode_gqa_split_swa_override_value,
                &decode_gqa_split_swa_override_valid);
        if (!decode_gqa_split_swa_override_valid) {
            runtime->decode_gqa_split_schedule_invalid_override_count += 1;
            fprintf(
                stderr,
                "metal-runtime-create: invalid TERMITE_METAL_DECODE_GQA_SPLIT_SWA_VARIANT=%s; using auto\n",
                decode_gqa_split_swa_override_value);
        }
        bool decode_gqa_split_global_override_valid = true;
        const char *decode_gqa_split_global_override_value =
            getenv("TERMITE_METAL_DECODE_GQA_SPLIT_GLOBAL_VARIANT");
        runtime->decode_gqa_split_global_variant_override =
            (uint8_t)termite_metal_decode_gqa_split_variant_parse(
                decode_gqa_split_global_override_value,
                &decode_gqa_split_global_override_valid);
        if (!decode_gqa_split_global_override_valid) {
            runtime->decode_gqa_split_schedule_invalid_override_count += 1;
            fprintf(
                stderr,
                "metal-runtime-create: invalid TERMITE_METAL_DECODE_GQA_SPLIT_GLOBAL_VARIANT=%s; using auto\n",
                decode_gqa_split_global_override_value);
        }
        runtime->decode_gqa_split_explicitly_requested =
            runtime->decode_gqa_split_enabled &&
            (termite_metal_env_flag_enabled(decode_gqa_split_enable_value) ||
             decode_gqa_split_swa_override_value != NULL ||
             decode_gqa_split_global_override_value != NULL);
        runtime->prepared_frame_diagnostics_forced = termite_metal_prepared_frame_diagnostics_enabled();
        termite_metal_stage_timing_initialize(runtime);
        runtime->q4_0_mmv_portfolio_disabled =
            termite_metal_env_flag_enabled(getenv("TERMITE_METAL_DISABLE_Q4_0_MMV_PORTFOLIO"));
        runtime->q4_0_small_reduce_disabled =
            termite_metal_env_flag_enabled(getenv("TERMITE_METAL_DISABLE_Q4_0_SMALL_REDUCE"));
        runtime->q4_0_mmv_trace_enabled =
            termite_metal_env_flag_enabled(getenv("TERMITE_METAL_TRACE_Q4_0_MMV_VARIANT"));
        bool q4_0_mmv_override_valid = true;
        const char *q4_0_mmv_override_value = getenv("TERMITE_METAL_Q4_0_MMV_VARIANT");
        runtime->q4_0_mmv_variant_override = (uint8_t)termite_metal_q4_0_mmv_variant_parse(
            q4_0_mmv_override_value,
