static void termite_metal_decode_runtime_drain_reuse_pool(termite_metal_decode_runtime *runtime, int keep_alive);

void termite_metal_decode_runtime_destroy(termite_metal_decode_runtime *runtime) {
    if (runtime == NULL) return;
    @autoreleasepool {
    if (runtime->submitted_frame_cb != nil) {
        (void)termite_metal_decode_runtime_wait_frame(runtime);
    }
    if (runtime->active_frame_cb != nil) {
        if (termite_metal_decode_runtime_active_frame_empty(runtime)) {
            (void)termite_metal_decode_runtime_cancel_frame(runtime);
        } else if (termite_metal_decode_runtime_submit_frame(runtime) == 0) {
            (void)termite_metal_decode_runtime_wait_frame(runtime);
        }
    }
    termite_metal_decode_runtime_clear_frame_resources(&runtime->active_frame_retained_resources);
    termite_metal_decode_runtime_clear_frame_resources(&runtime->submitted_frame_retained_resources);
    termite_metal_stage_sample_frame_reset(&runtime->active_stage_sample);
    termite_metal_stage_sample_frame_reset(&runtime->submitted_stage_sample);
    runtime->stage_timestamp_counter_set = nil;
    for (size_t route = 0; route < TERMITE_METAL_JIT_EXACT_ROUTE_COUNT; ++route) {
        const size_t count = runtime->jit_exact_pipeline_counts[route] <= TERMITE_METAL_JIT_EXACT_PIPELINES_PER_ROUTE
            ? runtime->jit_exact_pipeline_counts[route]
            : TERMITE_METAL_JIT_EXACT_PIPELINES_PER_ROUTE;
        for (size_t index = 0; index < count; ++index) {
            runtime->jit_exact_pipelines[route][index].pipeline = nil;
            runtime->jit_exact_pipelines[route][index].qkv_pipeline = nil;
        }
        runtime->jit_exact_pipeline_counts[route] = 0;
    }
    {
        const char *stats_env = getenv("TERMITE_METAL_EXPERT_SUBBUFFER_CACHE_STATS");
        if (stats_env != NULL && stats_env[0] == '1') {
            const uint64_t requests = runtime->expert_subbuffer_cache_hits + runtime->expert_subbuffer_cache_misses;
            const double rate = requests > 0
                ? (100.0 * (double)runtime->expert_subbuffer_cache_hits / (double)requests)
                : 0.0;
            fprintf(stderr,
                "metal_expert_subbuffer_cache_stats: hits=%llu misses=%llu hit_rate=%.1f%% capacity=%u\n",
                (unsigned long long)runtime->expert_subbuffer_cache_hits,
                (unsigned long long)runtime->expert_subbuffer_cache_misses,
                rate,
                TERMITE_METAL_EXPERT_SUBBUFFER_CACHE_CAPACITY);
        }
    }
    for (size_t slot = 0; slot < TERMITE_METAL_EXPERT_SUBBUFFER_CACHE_CAPACITY; ++slot) {
        runtime->expert_subbuffer_cache_ptrs[slot] = NULL;
        runtime->expert_subbuffer_cache_lens[slot] = 0;
        runtime->expert_subbuffer_cache_buffers[slot] = nil;
    }
    termite_metal_decode_runtime_drain_reuse_pool(runtime, 0);
    if (runtime->frame_reuse_pool != NULL) {
        free(runtime->frame_reuse_pool);
        runtime->frame_reuse_pool = NULL;
        runtime->frame_reuse_pool_cap = 0;
    }
    {
        const char *stats_env = getenv("TERMITE_METAL_BUFFER_REUSE_STATS");
        if (stats_env != NULL && stats_env[0] == '1') {
            double rate = runtime->reuse_alloc_count > 0
                ? (100.0 * (double)runtime->reuse_hit_count / (double)runtime->reuse_alloc_count)
                : 0.0;
            fprintf(stderr,
                "metal_buffer_reuse_stats: in_frame_private_allocs=%llu hits=%llu hit_rate=%.1f%% pool_peak=%zu\n",
                (unsigned long long)runtime->reuse_alloc_count,
                (unsigned long long)runtime->reuse_hit_count,
                rate,
                runtime->reuse_pool_peak_len);
        }
    }
    runtime->embed_absolute_position_pipeline = nil;
    runtime->embedding_lookup_pipeline = nil;
    runtime->embedding_lookup_bf16_pipeline = nil;
    runtime->q4_0_get_rows_pipeline = nil;
    runtime->q4_0_set_rows_pipeline = nil;
    runtime->q4_0_cpy_q_to_f32_pipeline = nil;
    runtime->q4_0_cpy_f32_to_q_pipeline = nil;
