int termite_metal_decode_runtime_quant_get_rows_linear_slot_device(
    termite_metal_decode_runtime *runtime,
    uint32_t format,
    size_t slot,
    const uint32_t *ids,
    size_t total,
    size_t dim,
    size_t source_rows,
    float scale,
    void *output_handle,
    size_t output_offset
) {
    if (runtime == NULL || ids == NULL || output_handle == NULL) return -1;
    id<MTLComputePipelineState> pipeline = termite_metal_decode_runtime_quant_get_rows_pipeline(runtime, format);
    if (pipeline == nil) return -2;
    if (slot >= TERMITE_METAL_LINEAR_SLOT_CAPACITY) return -3;
    if (total == 0 || dim == 0 || source_rows == 0 || dim % 32u != 0) return -4;
    if (total > UINT32_MAX || dim > UINT32_MAX || source_rows > UINT32_MAX) return -5;
    termite_metal_quant_linear_slot_view view;
    if (termite_metal_decode_runtime_require_quant_linear_slot(
            runtime,
            format,
            slot,
            dim,
            source_rows,
            &view) != 0) return -6;
