int termite_metal_decode_runtime_apply_rope(
    termite_metal_decode_runtime *runtime,
    const float *input,
    const uint32_t *positions,
    size_t total_chunks,
    size_t head_dim,
    size_t rope_dim,
    float theta,
    float freq_scale,
    uint32_t consecutive_pairs,
    float *output
) {
    if (runtime == NULL || input == NULL || positions == NULL || output == NULL) return -1;
    if (runtime->rope_pipeline == nil) return -2;
    if (total_chunks == 0 || head_dim == 0 || rope_dim == 0) return -3;
    if (total_chunks > UINT32_MAX || head_dim > UINT32_MAX || rope_dim > UINT32_MAX) return -4;
    @autoreleasepool {
        bool frame_owned = (runtime->active_frame_cb == nil);
        const size_t input_bytes = total_chunks * head_dim * sizeof(float);
        const size_t positions_bytes = total_chunks * sizeof(uint32_t);
        id<MTLBuffer> input_buffer = [runtime->device newBufferWithBytesNoCopy:(void *)input length:input_bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (input_buffer == nil) input_buffer = [runtime->device newBufferWithBytes:input length:input_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> positions_buffer = frame_owned
            ? [runtime->device newBufferWithBytesNoCopy:(void *)positions length:positions_bytes options:MTLResourceStorageModeShared deallocator:nil]
            : [runtime->device newBufferWithBytes:positions length:positions_bytes options:MTLResourceStorageModeShared];
        if (positions_buffer == nil) positions_buffer = [runtime->device newBufferWithBytes:positions length:positions_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> output_buffer = [runtime->device newBufferWithBytesNoCopy:output length:input_bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (output_buffer == nil) output_buffer = [runtime->device newBufferWithBytes:output length:input_bytes options:MTLResourceStorageModeShared];
        if (input_buffer == nil || positions_buffer == nil || output_buffer == nil) return -5;
        termite_metal_rope_params params = {
            .total_chunks = (uint32_t)total_chunks,
            .head_dim = (uint32_t)head_dim,
            .rope_dim = (uint32_t)rope_dim,
            .theta = theta,
            .freq_scale = freq_scale,
            .consecutive_pairs = consecutive_pairs,
        };
        id<MTLCommandBuffer> command_buffer = termite_metal_decode_runtime_host_io_command_buffer(runtime, __func__, &frame_owned);
        if (command_buffer == nil) return -7;
        id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder_for(command_buffer, TERMITE_METAL_COMPUTE_SOURCE_HEAD_ROPE);
        if (encoder == nil) return -8;
        [encoder setComputePipelineState:runtime->rope_pipeline];
        [encoder setBuffer:input_buffer offset:0 atIndex:0];
        [encoder setBuffer:positions_buffer offset:0 atIndex:1];
        [encoder setBuffer:output_buffer offset:0 atIndex:2];
        [encoder setBytes:&params length:sizeof(params) atIndex:3];
        const size_t total_values = total_chunks * head_dim;
        MTLSize grid_size = MTLSizeMake(total_values, 1, 1);
        NSUInteger thread_width = runtime->rope_pipeline.maxTotalThreadsPerThreadgroup;
        if (thread_width == 0) thread_width = 64;
        if (thread_width > total_values && total_values > 0) thread_width = total_values;
        MTLSize group_size = MTLSizeMake(thread_width, 1, 1);
        [encoder dispatchThreads:grid_size threadsPerThreadgroup:group_size];
        [encoder endEncoding];
        const int finish_rc = termite_metal_decode_runtime_finish_command_buffer(command_buffer, frame_owned, -9);
        if (finish_rc != 0) return finish_rc;
        // newBufferWithBytes (the non-page-aligned fallback) snapshots the caller's
        // buffer instead of aliasing it, so results must be copied back after the wait.
        if (output_buffer.contents != (void *)output) memcpy(output, output_buffer.contents, input_bytes);
        return 0;
    }
}

