    @autoreleasepool {
        if (bytes > runtime->direct_block_shared_capacities[index] ||
            runtime->direct_block_shared_buffers[index] == nil ||
            runtime->direct_block_shared_buffers[index].storageMode != MTLStorageModeShared)
        {
