static int termite_metal_decode_runtime_sample_tail_scratch_sizes(
    size_t out_dim,
    size_t top_k,
    size_t *logits_bytes,
    size_t *topk_bytes,
    size_t *probs_bytes
) {
    if (logits_bytes == NULL || topk_bytes == NULL || probs_bytes == NULL) return -1;
    if (out_dim == 0 || out_dim > SIZE_MAX / sizeof(float)) return -2;
    *logits_bytes = out_dim * sizeof(float);
    *topk_bytes = 0;
    *probs_bytes = out_dim * sizeof(float);
    if (top_k > 0 && top_k <= 64) {
        const size_t actual_top_k = top_k < out_dim ? top_k : out_dim;
        const size_t block_size = 512;
        const size_t block_count = (out_dim + block_size - 1) / block_size;
        if (actual_top_k == 0 || block_count == 0 || block_count > SIZE_MAX / actual_top_k) return -3;
        const size_t candidate_count = block_count * actual_top_k;
        if (candidate_count > SIZE_MAX / sizeof(float)) return -4;
        *topk_bytes = candidate_count * sizeof(float);
        *probs_bytes = actual_top_k * sizeof(float);
    }
    return 0;
}

int termite_metal_decode_runtime_reserve_sample_tail_scratch(
    termite_metal_decode_runtime *runtime,
    size_t out_dim,
    size_t top_k
) {
    if (runtime == NULL) return -1;
    size_t logits_bytes = 0;
    size_t topk_bytes = 0;
    size_t probs_bytes = 0;
    if (termite_metal_decode_runtime_sample_tail_scratch_sizes(out_dim, top_k, &logits_bytes, &topk_bytes, &probs_bytes) != 0) return -2;
    size_t slots[4] = {
        TERMITE_METAL_GRAPH_PLAN_SAMPLE_LOGITS_SLOT,
        TERMITE_METAL_GRAPH_PLAN_SAMPLE_PROBS_SLOT,
        TERMITE_METAL_GRAPH_PLAN_SAMPLE_TOPK_VALUES_SLOT,
        TERMITE_METAL_GRAPH_PLAN_SAMPLE_TOPK_IDS_SLOT,
    };
    size_t bytes[4] = {
        logits_bytes,
        probs_bytes,
        topk_bytes,
        topk_bytes,
    };
    if (termite_metal_decode_runtime_reserve_graph_plan_slots(runtime, slots, bytes, 4) != 0) return -3;
    runtime->sample_logits_buffer = runtime->graph_plan_buffers[TERMITE_METAL_GRAPH_PLAN_SAMPLE_LOGITS_SLOT];
    runtime->sample_logits_capacity = runtime->graph_plan_capacities[TERMITE_METAL_GRAPH_PLAN_SAMPLE_LOGITS_SLOT];
    runtime->scratch_buffer = runtime->graph_plan_buffers[TERMITE_METAL_GRAPH_PLAN_SAMPLE_PROBS_SLOT];
    runtime->scratch_capacity = runtime->graph_plan_capacities[TERMITE_METAL_GRAPH_PLAN_SAMPLE_PROBS_SLOT];
    if (topk_bytes > 0) {
        runtime->sample_topk_values_buffer = runtime->graph_plan_buffers[TERMITE_METAL_GRAPH_PLAN_SAMPLE_TOPK_VALUES_SLOT];
        runtime->sample_topk_ids_buffer = runtime->graph_plan_buffers[TERMITE_METAL_GRAPH_PLAN_SAMPLE_TOPK_IDS_SLOT];
        runtime->sample_topk_capacity = runtime->graph_plan_capacities[TERMITE_METAL_GRAPH_PLAN_SAMPLE_TOPK_VALUES_SLOT];
    }
    return 0;
}

int termite_metal_decode_runtime_reserve_attention_span_scratch(
    termite_metal_decode_runtime *runtime,
    size_t kv_tokens,
    size_t key_row_bytes,
    size_t v_row_stride
) {
    if (runtime == NULL) return -1;
    if (kv_tokens == 0 || key_row_bytes == 0 || v_row_stride == 0) return -2;
    if (kv_tokens > SIZE_MAX / key_row_bytes) return -3;
    if (kv_tokens > SIZE_MAX / v_row_stride) return -4;
    const size_t encoded_bytes = kv_tokens * key_row_bytes;
    const size_t v_elements = kv_tokens * v_row_stride;
    if (v_elements > SIZE_MAX / sizeof(float)) return -5;
    const size_t v_bytes = v_elements * sizeof(float);
    size_t slots[2] = {
        TERMITE_METAL_GRAPH_PLAN_ATTENTION_SPAN_KEY_SLOT,
        TERMITE_METAL_GRAPH_PLAN_ATTENTION_SPAN_VALUE_SLOT,
    };
    size_t bytes[2] = {
        encoded_bytes,
        v_bytes,
    };
    if (termite_metal_decode_runtime_reserve_graph_plan_slots(runtime, slots, bytes, 2) != 0) return -6;
    runtime->attention_span_encoded_key_buffers[0] = runtime->graph_plan_buffers[TERMITE_METAL_GRAPH_PLAN_ATTENTION_SPAN_KEY_SLOT];
    runtime->attention_span_v_buffers[0] = runtime->graph_plan_buffers[TERMITE_METAL_GRAPH_PLAN_ATTENTION_SPAN_VALUE_SLOT];
    runtime->attention_span_encoded_key_capacities[0] = runtime->graph_plan_capacities[TERMITE_METAL_GRAPH_PLAN_ATTENTION_SPAN_KEY_SLOT];
    runtime->attention_span_v_capacities[0] = runtime->graph_plan_capacities[TERMITE_METAL_GRAPH_PLAN_ATTENTION_SPAN_VALUE_SLOT];
    runtime->attention_span_encoded_key_buffer = runtime->attention_span_encoded_key_buffers[0];
    runtime->attention_span_v_buffer = runtime->attention_span_v_buffers[0];
    runtime->attention_span_encoded_key_capacity = runtime->attention_span_encoded_key_capacities[0];
    runtime->attention_span_v_capacity = runtime->attention_span_v_capacities[0];
    return 0;
}

