            encode_rc = termite_metal_encode_argmax_logits_suppress_on_encoder_at(
                runtime,
                encoder,
                logits_buffer,
                logits_offset + row * row_bytes,
                out_dim,
                suppress_buffer,
                suppress_count,
                row * sizeof(uint32_t),
                row * partial_bytes,
                -13);
