static int termite_metal_decode_runtime_validate_quantized_linear_slot(
    termite_metal_decode_runtime *runtime,
    uint32_t format,
    size_t slot,
    const uint8_t *weight_raw,
    size_t weight_bytes,
    size_t in_dim,
    size_t out_dim,
    size_t *values_per_block,
    size_t *bytes_per_block
) {
