    if (format == TERMITE_METAL_QUANT_FORMAT_TL1 || format == TERMITE_METAL_QUANT_FORMAT_TL2) return -10;
    if (!termite_metal_quant_format_block_layout(format, values_per_block, bytes_per_block)) return -10;
