int termite_metal_decode_runtime_apply_dense_mlp2_device(
    termite_metal_decode_runtime *runtime,
    size_t first_linear_slot,
    size_t second_linear_slot,
    void *input_handle,
    size_t input_offset,
    size_t rows,
    size_t in_dim,
    size_t hidden_dim,
    size_t out_dim,
    uint32_t activation_kind,
    void *output_handle,
    size_t output_offset
