    size_t kv_out_dim,
    const termite_metal_quant_linear_slot_view *q_view,
    const termite_metal_quant_linear_slot_view *k_view,
    const termite_metal_quant_linear_slot_view *v_view,
    id<MTLComputePipelineState> kv_pair_pipeline,
    id<MTLBuffer> q_output_buffer,
    size_t q_output_offset,
    id<MTLBuffer> k_output_buffer,
    size_t k_output_offset,
    id<MTLBuffer> v_output_buffer,
    size_t v_output_offset,
    int q_failure_code,
    int kv_failure_code
);

int termite_metal_decode_runtime_apply_quantized_linear_qkv_slots_device(
    termite_metal_decode_runtime *runtime,
    uint32_t q_format,
    uint32_t k_format,
    uint32_t v_format,
    size_t q_slot,
    size_t k_slot,
    size_t v_slot,
    void *input_handle,
    size_t input_offset,
    size_t rows,
    size_t in_dim,
    size_t q_out_dim,
    size_t kv_out_dim,
    void *q_output_handle,
    size_t q_output_offset,
    void *k_output_handle,
    size_t k_output_offset,
    void *v_output_handle,
    size_t v_output_offset
) {
    if (runtime == NULL || input_handle == NULL || q_output_handle == NULL || k_output_handle == NULL || v_output_handle == NULL) return -1;
    if (q_format != TERMITE_METAL_QUANT_FORMAT_Q8_0 ||
        k_format != TERMITE_METAL_QUANT_FORMAT_Q8_0 ||
        v_format != TERMITE_METAL_QUANT_FORMAT_Q8_0)
    {
        if (k_format != v_format) return -2;
        return termite_metal_decode_runtime_apply_quantized_q_kv_pair_linear_qkv_slots_device(
            runtime,
            q_format,
            k_format,
            q_slot,
            k_slot,
            v_slot,
            input_handle,
            input_offset,
            rows,
            in_dim,
            q_out_dim,
            kv_out_dim,
            q_output_handle,
            q_output_offset,
            k_output_handle,
            k_output_offset,
            v_output_handle,
            v_output_offset);
    }
    if (runtime->q8_0_pipeline == nil || runtime->q8_0_pair_pipeline == nil) return -2;
    if (q_slot >= TERMITE_METAL_LINEAR_SLOT_CAPACITY || k_slot >= TERMITE_METAL_LINEAR_SLOT_CAPACITY || v_slot >= TERMITE_METAL_LINEAR_SLOT_CAPACITY) return -3;
    if (q_slot == k_slot || q_slot == v_slot || k_slot == v_slot) return -4;
    termite_metal_quant_linear_slot_view q_view;
    termite_metal_quant_linear_slot_view k_view;
    termite_metal_quant_linear_slot_view v_view;
    if (termite_metal_decode_runtime_require_quant_linear_slot(runtime, TERMITE_METAL_QUANT_FORMAT_Q8_0, q_slot, in_dim, q_out_dim, &q_view) != 0) return -5;
    if (termite_metal_decode_runtime_require_quant_linear_slot(runtime, TERMITE_METAL_QUANT_FORMAT_Q8_0, k_slot, in_dim, kv_out_dim, &k_view) != 0) return -6;
    if (termite_metal_decode_runtime_require_quant_linear_slot(runtime, TERMITE_METAL_QUANT_FORMAT_Q8_0, v_slot, in_dim, kv_out_dim, &v_view) != 0) return -7;
    if (rows == 0 || rows > UINT32_MAX || in_dim == 0 || q_out_dim == 0 || kv_out_dim == 0 || in_dim > UINT32_MAX || q_out_dim > UINT32_MAX || kv_out_dim > UINT32_MAX) return -8;
    if (in_dim % 32u != 0) return -9;
    @autoreleasepool {
        id<MTLBuffer> input_buffer = (__bridge id<MTLBuffer>)input_handle;
        id<MTLBuffer> q_output_buffer = (__bridge id<MTLBuffer>)q_output_handle;
        id<MTLBuffer> k_output_buffer = (__bridge id<MTLBuffer>)k_output_handle;
        id<MTLBuffer> v_output_buffer = (__bridge id<MTLBuffer>)v_output_handle;
        const size_t input_bytes = rows * in_dim * sizeof(float);
        const size_t q_output_bytes = rows * q_out_dim * sizeof(float);
        const size_t kv_output_bytes = rows * kv_out_dim * sizeof(float);
        if (input_offset + input_bytes > input_buffer.length) return -10;
        if (q_output_offset + q_output_bytes > q_output_buffer.length) return -11;
        if (k_output_offset + kv_output_bytes > k_output_buffer.length) return -12;
        if (v_output_offset + kv_output_bytes > v_output_buffer.length) return -13;

        const bool frame_owned = (runtime->active_frame_cb == nil);
        id<MTLCommandBuffer> command_buffer = frame_owned
            ? termite_metal_new_command_buffer(runtime->queue, __func__)
            : runtime->active_frame_cb;
        if (command_buffer == nil) return -14;

        if (rows == 1 && termite_metal_encode_q8_0_qkv_linear_with_offsets(
                runtime,
                command_buffer,
                input_buffer,
                input_offset,
                q_view.weight_buffer,
                q_view.weight_offset,
                k_view.weight_buffer,
                k_view.weight_offset,
                v_view.weight_buffer,
                v_view.weight_offset,
                q_output_buffer,
                q_output_offset,
                k_output_buffer,
                k_output_offset,
                v_output_buffer,
                v_output_offset,
                rows,
                in_dim,
                q_out_dim,
                kv_out_dim,
                -15) != 0) return -15;

        if (rows != 1 && termite_metal_encode_q8_0_linear_family_with_offset(
                runtime,
                command_buffer,
                input_buffer,
                input_offset,
                q_view.weight_buffer,
                q_view.weight_offset,
                q_output_buffer,
                q_output_offset,
                rows,
                in_dim,
                q_out_dim,
                TERMITE_METAL_Q8_0_LINEAR_FAMILY_NONE,
                -15) != 0) return -15;

        if (rows != 1) {
            if (rows >= 9u && runtime->q8_0_mm_pipeline != nil) {
                if (termite_metal_encode_q8_0_linear_family_with_offset(
                        runtime,
                        command_buffer,
                        input_buffer,
                        input_offset,
                        k_view.weight_buffer,
                        k_view.weight_offset,
                        k_output_buffer,
                        k_output_offset,
                        rows,
                        in_dim,
                        kv_out_dim,
                        TERMITE_METAL_Q8_0_LINEAR_FAMILY_NONE,
                        -16) != 0) return -16;
                if (termite_metal_encode_q8_0_linear_family_with_offset(
                        runtime,
                        command_buffer,
                        input_buffer,
                        input_offset,
                        v_view.weight_buffer,
                        v_view.weight_offset,
                        v_output_buffer,
                        v_output_offset,
                        rows,
                        in_dim,
                        kv_out_dim,
                        TERMITE_METAL_Q8_0_LINEAR_FAMILY_NONE,
                        -16) != 0) return -16;
            } else {
                if (termite_metal_encode_q8_0_pair_linear_with_offsets(
                        runtime,
                        command_buffer,
                        input_buffer,
                        input_offset,
                        k_view.weight_buffer,
                        k_view.weight_offset,
                        v_view.weight_buffer,
                        v_view.weight_offset,
                        k_output_buffer,
                        k_output_offset,
                        v_output_buffer,
                        v_output_offset,
                        rows,
                        in_dim,
                        kv_out_dim,
                        -16) != 0) return -16;
            }
        }

	        if (!frame_owned) return 0;
        [command_buffer commit];
        [command_buffer waitUntilCompleted];
        return command_buffer.status == MTLCommandBufferStatusCompleted ? 0 : -17;
