        [split_encoder setBuffer:packed_output_buffer offset:0 atIndex:0];
        [split_encoder setBuffer:runtime->linear_bias_buffers[a_slot] offset:0 atIndex:1];
        [split_encoder setBuffer:runtime->linear_bias_buffers[b_slot] offset:0 atIndex:2];
        [split_encoder setBuffer:a_output_buffer offset:0 atIndex:3];
        [split_encoder setBuffer:b_output_buffer offset:0 atIndex:4];
        [split_encoder setBytes:&params length:sizeof(params) atIndex:5];
        [split_encoder dispatchThreads:MTLSizeMake(rows * total_out_dim, 1, 1)
                   threadsPerThreadgroup:MTLSizeMake(termite_metal_thread_width(runtime->dense_pair_split_bias_pipeline, rows * total_out_dim), 1, 1)];
        [split_encoder endEncoding];
        runtime->mps_dense_linear_active_frame_calls += 1;
        runtime->active_frame_mps_dense_linear_count += 1;

        *a_output_handle = (__bridge void *)a_output_buffer;
        *b_output_handle = (__bridge void *)b_output_buffer;
        runtime->dense_pair_packed_calls += 1;
        return 0;
    }
}

static int termite_metal_encode_quant_q_plus_kv_pair_descriptors(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    uint32_t q_format,
    uint32_t kv_format,
    size_t q_slot,
    size_t k_slot,
    id<MTLBuffer> input_buffer,
    size_t input_offset,
    size_t rows,
    size_t in_dim,
    size_t q_out_dim,
    size_t kv_out_dim,
    const termite_metal_quant_linear_slot_view *q_view,
    const termite_metal_quant_linear_slot_view *k_view,
    const termite_metal_quant_linear_slot_view *v_view,
    id<MTLComputePipelineState> kv_pair_pipeline,
    id<MTLBuffer> q_output_buffer,
    size_t q_output_offset,
    id<MTLBuffer> k_output_buffer,
    size_t k_output_offset,
    id<MTLBuffer> v_output_buffer,
    size_t v_output_offset,
    int q_failure_code,
    int kv_failure_code
) {
    if (runtime == NULL || command_buffer == nil || input_buffer == nil ||
        q_view == NULL || k_view == NULL || v_view == NULL ||
        q_output_buffer == nil || k_output_buffer == nil || v_output_buffer == nil) return q_failure_code;
    if (q_format == kv_format && q_out_dim == kv_out_dim) {
        const int qkv_rc = termite_metal_encode_exact_quant_qkv_descriptor(
            runtime,
            command_buffer,
            q_format,
            input_buffer,
            input_offset,
            rows,
            in_dim,
            q_out_dim,
            q_view,
            k_view,
            v_view,
            q_output_buffer,
            q_output_offset,
            k_output_buffer,
            k_output_offset,
            v_output_buffer,
            v_output_offset,
            q_failure_code);
        if (qkv_rc < 0) return q_failure_code;
        if (qkv_rc > 0) return 0;
    }
    if (k_view->values_per_block != v_view->values_per_block ||
        k_view->bytes_per_block != v_view->bytes_per_block) return kv_failure_code;
    termite_metal_quant_matmul_descriptor q_descriptor = {
        .slot = q_slot,
        .format = q_format,
        .activation_dtype = TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32,
        .epilogue = TERMITE_METAL_QUANT_MATMUL_EPILOGUE_NONE,
        .fallback_pipeline = q_view->pipeline,
        .input_buffer = input_buffer,
        .input_offset = input_offset,
        .weight_buffer = q_view->weight_buffer,
        .weight_offset = q_view->weight_offset,
        .output_buffer = q_output_buffer,
        .output_offset = q_output_offset,
        .rows = rows,
        .in_dim = in_dim,
        .out_dim = q_out_dim,
        .values_per_block = q_view->values_per_block,
        .bytes_per_block = q_view->bytes_per_block,
        .q4_0_mmv_workload = TERMITE_METAL_Q4_0_MMV_WORKLOAD_ATTENTION,
        .failure_code = q_failure_code,
    };
    if (termite_metal_encode_quant_matmul_descriptor(runtime, command_buffer, &q_descriptor) != 0) return q_failure_code;

    termite_metal_quant_matmul_descriptor kv_descriptor = {
        .slot = k_slot,
        .format = kv_format,
        .activation_dtype = TERMITE_METAL_QUANT_MATMUL_ACTIVATION_F32,
        .epilogue = TERMITE_METAL_QUANT_MATMUL_EPILOGUE_PAIR,
        .fallback_pipeline = kv_pair_pipeline,
        .input_buffer = input_buffer,
        .input_offset = input_offset,
        .weight_buffer = k_view->weight_buffer,
        .weight_offset = k_view->weight_offset,
        .second_weight_buffer = v_view->weight_buffer,
        .second_weight_offset = v_view->weight_offset,
        .output_buffer = k_output_buffer,
        .output_offset = k_output_offset,
        .second_output_buffer = v_output_buffer,
        .second_output_offset = v_output_offset,
        .rows = rows,
        .in_dim = in_dim,
        .out_dim = kv_out_dim,
        .values_per_block = k_view->values_per_block,
        .bytes_per_block = k_view->bytes_per_block,
        .failure_code = kv_failure_code,
    };
    if (termite_metal_encode_quant_matmul_descriptor(runtime, command_buffer, &kv_descriptor) != 0) return kv_failure_code;
    return 0;
}

static id<MTLComputePipelineState> termite_metal_quant_pair_pipeline_for_format(
    termite_metal_decode_runtime *runtime,
    uint32_t format
) {
    if (runtime == NULL) return nil;
    switch (format) {
        case TERMITE_METAL_QUANT_FORMAT_I2_S:
            return runtime->i2_s_pair_pipeline;
        case TERMITE_METAL_QUANT_FORMAT_Q4_0:
            return runtime->q4_0_pair_pipeline;
        case TERMITE_METAL_QUANT_FORMAT_Q4_K:
            return runtime->q4_k_pair_pipeline;
        case TERMITE_METAL_QUANT_FORMAT_Q6_K:
            return runtime->q6_k_pair_pipeline;
        default:
            return nil;
    }
}

