        const size_t output_bytes = out_dim * sizeof(float);
        id<MTLBuffer> input_buffer = [runtime->device newBufferWithBytesNoCopy:(void *)input length:input_bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (input_buffer == nil) input_buffer = [runtime->device newBufferWithBytes:input length:input_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> hidden_buffer = [runtime->device newBufferWithLength:hidden_bytes options:MTLResourceStorageModePrivate];
        id<MTLBuffer> output_buffer = [runtime->device newBufferWithLength:output_bytes options:MTLResourceStorageModeShared];
        if (input_buffer == nil || hidden_buffer == nil || output_buffer == nil) return -9;
        termite_metal_apply_layer_norm_params norm_params = {
            .hidden_size = (uint32_t)hidden_size,
            .eps = eps,
        };
        termite_metal_apply_linear_params linear_params = {
            .in_dim = (uint32_t)hidden_size,
            .out_dim = (uint32_t)out_dim,
        };
        id<MTLBuffer> norm_params_buffer = [runtime->device newBufferWithBytes:&norm_params length:sizeof(norm_params) options:MTLResourceStorageModeShared];
        id<MTLBuffer> linear_params_buffer = [runtime->device newBufferWithBytes:&linear_params length:sizeof(linear_params) options:MTLResourceStorageModeShared];
        if (norm_params_buffer == nil || linear_params_buffer == nil) return -10;
        id<MTLCommandBuffer> command_buffer = termite_metal_new_command_buffer(runtime->queue, __func__);
        if (command_buffer == nil) return -11;

        id<MTLComputeCommandEncoder> norm_encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
        if (norm_encoder == nil) return -12;
        [norm_encoder setComputePipelineState:runtime->rms_norm_pipeline];
        [norm_encoder setBuffer:input_buffer offset:0 atIndex:0];
        [norm_encoder setBuffer:runtime->rms_norm_weight_buffers[norm_slot] offset:0 atIndex:1];
        [norm_encoder setBuffer:hidden_buffer offset:0 atIndex:2];
        [norm_encoder setBuffer:norm_params_buffer offset:0 atIndex:3];
        [norm_encoder dispatchThreads:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
        [norm_encoder endEncoding];

        id<MTLComputeCommandEncoder> linear_encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
        if (linear_encoder == nil) return -13;
        const BOOL use_reduce = out_dim >= 128;
        [linear_encoder setComputePipelineState:(use_reduce ? runtime->linear_reduce_pipeline : runtime->linear_pipeline)];
        [linear_encoder setBuffer:hidden_buffer offset:0 atIndex:0];
        [linear_encoder setBuffer:runtime->linear_weight_buffers[linear_slot] offset:0 atIndex:1];
        [linear_encoder setBuffer:runtime->linear_bias_buffers[linear_slot] offset:0 atIndex:2];
        [linear_encoder setBuffer:output_buffer offset:0 atIndex:3];
        [linear_encoder setBuffer:linear_params_buffer offset:0 atIndex:4];
        if (use_reduce) {
            [linear_encoder dispatchThreads:MTLSizeMake(out_dim * 32u, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        } else {
            NSUInteger thread_width = runtime->linear_pipeline.maxTotalThreadsPerThreadgroup;
            if (thread_width == 0) thread_width = 64;
            if (thread_width > out_dim && out_dim > 0) thread_width = out_dim;
            [linear_encoder dispatchThreads:MTLSizeMake(out_dim, 1, 1) threadsPerThreadgroup:MTLSizeMake(thread_width, 1, 1)];
        }
        [linear_encoder endEncoding];

        [command_buffer commit];
        [command_buffer waitUntilCompleted];
        if (command_buffer.status != MTLCommandBufferStatusCompleted) return -14;
        float *result = (float *)output_buffer.contents;
        if (result == NULL) return -15;
        memcpy(output, result, output_bytes);
        return 0;
    }
}

static int termite_metal_decode_runtime_sample_from_logits(
    termite_metal_decode_runtime *runtime,
    const float *logits,
    size_t out_dim,
    float temperature,
    size_t top_k,
    float top_p,
    float min_p,
    float repetition_penalty,
    float frequency_penalty,
    float presence_penalty,
    const uint32_t *penalty_token_ids,
    const uint32_t *penalty_counts,
    size_t penalty_count,
    uint32_t seed,
    uint32_t *output_token_id
) {
    if (runtime == NULL || logits == NULL || output_token_id == NULL) return -1;
    if (runtime->sample_logits_pipeline == nil) return -2;
    if (out_dim == 0 || out_dim > UINT32_MAX) return -3;
    @autoreleasepool {
        const size_t logits_bytes = out_dim * sizeof(float);
        id<MTLBuffer> logits_buffer = [runtime->device newBufferWithBytesNoCopy:(void *)logits length:logits_bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (logits_buffer == nil) logits_buffer = [runtime->device newBufferWithBytes:logits length:logits_bytes options:MTLResourceStorageModeShared];
        if (logits_buffer == nil) return -4;
        id<MTLCommandBuffer> command_buffer = termite_metal_new_command_buffer(runtime->queue, __func__);
        if (command_buffer == nil) return -6;
        int rc = termite_metal_decode_runtime_encode_sample_from_logits_buffer(
            runtime,
            command_buffer,
            logits_buffer,
            out_dim,
            temperature,
            top_k,
            top_p,
            min_p,
            repetition_penalty,
            frequency_penalty,
            presence_penalty,
            penalty_token_ids,
            penalty_counts,
            penalty_count,
            seed,
            0.0f
        );
        if (rc != 0) return rc;
        [command_buffer commit];
        [command_buffer waitUntilCompleted];
        if (command_buffer.status != MTLCommandBufferStatusCompleted) return -8;
        uint32_t *result = (uint32_t *)runtime->token_buffer.contents;
        if (result == NULL) return -9;
        output_token_id[0] = result[0];
        return 0;
    }
}

// Sample from the logits already resident in runtime->sample_logits_buffer
// (written by the fused norm+lm-head+argmax decode tail). Avoids re-running
// the LM head for temperature sampling after a planned decode frame.
int termite_metal_decode_runtime_sample_from_resident_logits(
    termite_metal_decode_runtime *runtime,
    size_t out_dim,
    float temperature,
    size_t top_k,
    float top_p,
    float min_p,
    float repetition_penalty,
    float frequency_penalty,
    float presence_penalty,
    const uint32_t *penalty_token_ids,
    const uint32_t *penalty_counts,
    size_t penalty_count,
    uint32_t seed,
    float final_logit_softcap,
    uint32_t *output_token_id
) {
    if (runtime == NULL || output_token_id == NULL) return -1;
    if (out_dim == 0 || out_dim > UINT32_MAX) return -3;
    @autoreleasepool {
        const size_t logits_bytes = out_dim * sizeof(float);
        if (runtime->sample_logits_buffer == nil || runtime->sample_logits_capacity < logits_bytes) return -2;
        if (runtime->active_frame_cb != nil || runtime->submitted_frame_cb != nil) {
            if (termite_metal_decode_runtime_flush_active_frame(runtime) != 0) return -5;
        }
        id<MTLCommandBuffer> command_buffer = termite_metal_new_command_buffer(runtime->queue, __func__);
        if (command_buffer == nil) return -6;
        int rc = termite_metal_decode_runtime_encode_sample_from_logits_buffer(
            runtime,
            command_buffer,
            runtime->sample_logits_buffer,
            out_dim,
            temperature,
            top_k,
            top_p,
            min_p,
            repetition_penalty,
            frequency_penalty,
            presence_penalty,
            penalty_token_ids,
            penalty_counts,
            penalty_count,
            seed,
            final_logit_softcap
        );
        if (rc != 0) return rc;
        [command_buffer commit];
        [command_buffer waitUntilCompleted];
        if (command_buffer.status != MTLCommandBufferStatusCompleted) return -8;
        uint32_t *result = (uint32_t *)runtime->token_buffer.contents;
        if (result == NULL) return -9;
        output_token_id[0] = result[0];
        return 0;
    }
}

static int termite_metal_bind_sampling_penalties(
    termite_metal_decode_runtime *runtime,
    id<MTLComputeCommandEncoder> encoder,
    const termite_metal_penalty_entry *entries,
    size_t entry_count,
    NSUInteger index
) {
    if (runtime == NULL || encoder == nil) return -1;
    if (entries == NULL || entry_count == 0) {
        termite_metal_penalty_entry empty_penalty = { 0, 0 };
        [encoder setBytes:&empty_penalty length:sizeof(empty_penalty) atIndex:index];
        return 0;
    }
    const size_t penalty_bytes = entry_count * sizeof(termite_metal_penalty_entry);
    if (penalty_bytes <= 4096u) {
        [encoder setBytes:entries length:penalty_bytes atIndex:index];
        return 0;
    }
    id<MTLBuffer> penalty_buffer = [runtime->device newBufferWithBytes:entries length:penalty_bytes options:MTLResourceStorageModeShared];
    if (penalty_buffer == nil) return -10;
    [encoder setBuffer:penalty_buffer offset:0 atIndex:index];
    return 0;
}

static int termite_metal_decode_runtime_encode_sample_topk_from_logits_buffer(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    id<MTLBuffer> logits_buffer,
    size_t out_dim,
    float temperature,
    size_t top_k,
    float top_p,
    float min_p,
    float repetition_penalty,
    float frequency_penalty,
    float presence_penalty,
    const uint32_t *penalty_token_ids,
    const uint32_t *penalty_counts,
    size_t penalty_count,
    uint32_t seed
) {
    if (runtime == NULL || command_buffer == nil || logits_buffer == nil) return -1;
    if (runtime->sample_topk_partials_pipeline == nil || runtime->sample_topk_reduce_pipeline == nil) return -2;
    if (out_dim == 0 || out_dim > UINT32_MAX || top_k == 0 || top_k > 64 || penalty_count > UINT32_MAX) return -3;

    const size_t block_size = 512;
    const size_t actual_top_k = top_k < out_dim ? top_k : out_dim;
    const size_t block_count = (out_dim + block_size - 1) / block_size;
    const size_t candidate_count = block_count * actual_top_k;
    if (candidate_count == 0 || candidate_count > UINT32_MAX) return -3;
    const size_t partial_bytes = candidate_count * sizeof(float);
    if (termite_metal_decode_runtime_ensure_sample_topk_buffers(runtime, partial_bytes) != 0) return -4;
    const size_t probs_bytes = actual_top_k * sizeof(float);
    if (termite_metal_decode_runtime_ensure_sample_probs_buffer(runtime, probs_bytes) != 0) return -4;
    if (runtime->token_capacity < sizeof(uint32_t) || runtime->token_buffer == nil || runtime->token_buffer.storageMode != MTLStorageModeShared) {
        id<MTLBuffer> token = [runtime->device newBufferWithLength:sizeof(uint32_t) options:MTLResourceStorageModeShared];
        if (token == nil) return -4;
        runtime->token_buffer = token;
        runtime->token_capacity = sizeof(uint32_t);
    }

    termite_metal_sample_logits_params params = {
        .out_dim = (uint32_t)out_dim,
        .temperature = temperature,
        .top_k = (uint32_t)actual_top_k,
        .top_p = top_p,
        .min_p = min_p,
        .repetition_penalty = repetition_penalty,
        .frequency_penalty = frequency_penalty,
        .presence_penalty = presence_penalty,
        .penalty_count = (uint32_t)penalty_count,
        .seed = seed,
    };
    termite_metal_topk_reduce_params reduce_params = {
        .candidate_count = (uint32_t)candidate_count,
        .top_k = (uint32_t)actual_top_k,
        .top_p = top_p,
        .min_p = min_p,
        .seed = seed,
    };
    termite_metal_penalty_entry *entries = NULL;
    if (penalty_count > 0) {
        entries = calloc(penalty_count, sizeof(termite_metal_penalty_entry));
        if (entries == NULL) return -10;
        for (size_t i = 0; i < penalty_count; ++i) {
            entries[i].token_id = penalty_token_ids[i];
            entries[i].count = penalty_counts[i];
        }
    }

    id<MTLComputeCommandEncoder> partial_encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
    if (partial_encoder == nil) {
        if (entries != NULL) free(entries);
        return -7;
    }
    [partial_encoder setComputePipelineState:runtime->sample_topk_partials_pipeline];
    [partial_encoder setBuffer:logits_buffer offset:0 atIndex:0];
    [partial_encoder setBuffer:runtime->sample_topk_values_buffer offset:0 atIndex:1];
    [partial_encoder setBuffer:runtime->sample_topk_ids_buffer offset:0 atIndex:2];
    [partial_encoder setBytes:&params length:sizeof(params) atIndex:3];
    if (termite_metal_bind_sampling_penalties(runtime, partial_encoder, entries, penalty_count, 4) != 0) {
        [partial_encoder endEncoding];
        if (entries != NULL) free(entries);
        return -10;
    }
    [partial_encoder dispatchThreads:MTLSizeMake(block_count, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    [partial_encoder endEncoding];

    id<MTLComputeCommandEncoder> reduce_encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
    if (reduce_encoder == nil) {
        if (entries != NULL) free(entries);
        return -7;
    }
    [reduce_encoder setComputePipelineState:runtime->sample_topk_reduce_pipeline];
    [reduce_encoder setBuffer:runtime->sample_topk_values_buffer offset:0 atIndex:0];
    [reduce_encoder setBuffer:runtime->sample_topk_ids_buffer offset:0 atIndex:1];
    [reduce_encoder setBuffer:runtime->scratch_buffer offset:0 atIndex:2];
    [reduce_encoder setBuffer:runtime->token_buffer offset:0 atIndex:3];
    [reduce_encoder setBytes:&reduce_params length:sizeof(reduce_params) atIndex:4];
    [reduce_encoder dispatchThreads:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    [reduce_encoder endEncoding];
    if (entries != NULL) free(entries);
    return 0;
}

static int termite_metal_decode_runtime_encode_sample_from_logits_buffer(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    id<MTLBuffer> logits_buffer,
    size_t out_dim,
    float temperature,
    size_t top_k,
    float top_p,
    float min_p,
    float repetition_penalty,
    float frequency_penalty,
    float presence_penalty,
    const uint32_t *penalty_token_ids,
    const uint32_t *penalty_counts,
    size_t penalty_count,
    uint32_t seed,
    float final_logit_softcap
) {
    if (runtime == NULL || command_buffer == nil || logits_buffer == nil) return -1;
    if (runtime->sample_logits_pipeline == nil) return -2;
    if (out_dim == 0 || out_dim > UINT32_MAX || top_k > 256 || penalty_count > UINT32_MAX) return -3;
    const bool softcap_requested = final_logit_softcap > 0.0f;
    if (top_k > 0 && top_k <= 64) {
        // The top-k kernels do not apply final-logit softcap.
        if (softcap_requested) return -20;
        return termite_metal_decode_runtime_encode_sample_topk_from_logits_buffer(
            runtime,
            command_buffer,
            logits_buffer,
            out_dim,
            temperature,
            top_k,
            top_p,
            min_p,
            repetition_penalty,
            frequency_penalty,
            presence_penalty,
            penalty_token_ids,
            penalty_counts,
            penalty_count,
            seed
        );
    }

    // Pure temperature sampling (no top-k/top-p/min-p filtering): Gumbel-max
    // is an exact draw from softmax(logits/T) and runs as a parallel
    // two-stage max instead of the single-thread CDF walk below.
    const bool gumbel_eligible = temperature > 0.0f &&
        top_k == 0 &&
        (top_p <= 0.0f || top_p >= 1.0f) &&
        min_p <= 0.0f &&
        runtime->sample_gumbel_partials_pipeline != nil &&
        runtime->argmax_logits_reduce_pipeline != nil;
    if (softcap_requested && !gumbel_eligible) return -20;
    if (gumbel_eligible) {
        const size_t block_size = 1024u;
        const size_t block_count = (out_dim + block_size - 1u) / block_size;
        const size_t partial_bytes = block_count * sizeof(float);
        if (block_count == 0 || block_count > UINT32_MAX) return -4;
        if (termite_metal_decode_runtime_ensure_sample_topk_buffers(runtime, partial_bytes) != 0) return -4;
        if (runtime->sample_topk_values_buffer == nil || runtime->sample_topk_ids_buffer == nil) return -4;
        if (runtime->token_capacity < sizeof(uint32_t) || runtime->token_buffer == nil || runtime->token_buffer.storageMode != MTLStorageModeShared) {
            id<MTLBuffer> token = [runtime->device newBufferWithLength:sizeof(uint32_t) options:MTLResourceStorageModeShared];
            if (token == nil) return -4;
            runtime->token_buffer = token;
            runtime->token_capacity = sizeof(uint32_t);
        }
        termite_metal_sample_logits_params gumbel_params = {
            .out_dim = (uint32_t)out_dim,
            .temperature = temperature,
            .top_k = 0u,
            .top_p = top_p,
            .min_p = min_p,
            .repetition_penalty = repetition_penalty,
            .frequency_penalty = frequency_penalty,
            .presence_penalty = presence_penalty,
            .penalty_count = (uint32_t)penalty_count,
            .seed = seed,
            .final_logit_softcap = final_logit_softcap,
        };
        termite_metal_penalty_entry *gumbel_entries = NULL;
        if (penalty_count > 0) {
            gumbel_entries = calloc(penalty_count, sizeof(termite_metal_penalty_entry));
            if (gumbel_entries == NULL) return -10;
            for (size_t i = 0; i < penalty_count; ++i) {
                gumbel_entries[i].token_id = penalty_token_ids[i];
                gumbel_entries[i].count = penalty_counts[i];
            }
        }
        id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
        if (encoder == nil) {
            if (gumbel_entries != NULL) free(gumbel_entries);
            return -7;
        }
        [encoder setComputePipelineState:runtime->sample_gumbel_partials_pipeline];
        [encoder setBuffer:logits_buffer offset:0 atIndex:0];
        [encoder setBuffer:runtime->sample_topk_values_buffer offset:0 atIndex:1];
        [encoder setBuffer:runtime->sample_topk_ids_buffer offset:0 atIndex:2];
        [encoder setBytes:&gumbel_params length:sizeof(gumbel_params) atIndex:3];
        if (termite_metal_bind_sampling_penalties(runtime, encoder, gumbel_entries, penalty_count, 4) != 0) {
            [encoder endEncoding];
            if (gumbel_entries != NULL) free(gumbel_entries);
            return -10;
        }
        [encoder setThreadgroupMemoryLength:256u * sizeof(float) atIndex:0];
        [encoder setThreadgroupMemoryLength:256u * sizeof(uint32_t) atIndex:1];
        [encoder dispatchThreadgroups:MTLSizeMake(block_count, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        [encoder memoryBarrierWithScope:MTLBarrierScopeBuffers];
        const uint32_t block_count_u32 = (uint32_t)block_count;
        [encoder setComputePipelineState:runtime->argmax_logits_reduce_pipeline];
        [encoder setBuffer:runtime->sample_topk_values_buffer offset:0 atIndex:0];
        [encoder setBuffer:runtime->sample_topk_ids_buffer offset:0 atIndex:1];
        [encoder setBuffer:runtime->token_buffer offset:0 atIndex:2];
        [encoder setBytes:&block_count_u32 length:sizeof(block_count_u32) atIndex:3];
        [encoder dispatchThreads:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
        [encoder endEncoding];
        if (gumbel_entries != NULL) free(gumbel_entries);
        return 0;
    }

    const size_t logits_bytes = out_dim * sizeof(float);
    if (termite_metal_decode_runtime_ensure_sample_probs_buffer(runtime, logits_bytes) != 0) return -4;
    if (runtime->token_capacity < sizeof(uint32_t) || runtime->token_buffer == nil || runtime->token_buffer.storageMode != MTLStorageModeShared) {
        id<MTLBuffer> token = [runtime->device newBufferWithLength:sizeof(uint32_t) options:MTLResourceStorageModeShared];
        if (token == nil) return -4;
        runtime->token_buffer = token;
        runtime->token_capacity = sizeof(uint32_t);
    }

    termite_metal_sample_logits_params params = {
        .out_dim = (uint32_t)out_dim,
        .temperature = temperature,
        .top_k = (uint32_t)top_k,
        .top_p = top_p,
        .min_p = min_p,
        .repetition_penalty = repetition_penalty,
        .frequency_penalty = frequency_penalty,
        .presence_penalty = presence_penalty,
        .penalty_count = (uint32_t)penalty_count,
        .seed = seed,
    };
    termite_metal_penalty_entry *entries = NULL;
    if (penalty_count > 0) {
        entries = calloc(penalty_count, sizeof(termite_metal_penalty_entry));
        if (entries == NULL) return -10;
        for (size_t i = 0; i < penalty_count; ++i) {
            entries[i].token_id = penalty_token_ids[i];
            entries[i].count = penalty_counts[i];
        }
    }
    id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
    if (encoder == nil) {
        if (entries != NULL) free(entries);
        return -7;
    }
    [encoder setComputePipelineState:runtime->sample_logits_pipeline];
    [encoder setBuffer:logits_buffer offset:0 atIndex:0];
    [encoder setBuffer:runtime->scratch_buffer offset:0 atIndex:1];
    [encoder setBuffer:runtime->token_buffer offset:0 atIndex:2];
    [encoder setBytes:&params length:sizeof(params) atIndex:3];
    if (termite_metal_bind_sampling_penalties(runtime, encoder, entries, penalty_count, 4) != 0) {
        [encoder endEncoding];
        if (entries != NULL) free(entries);
        return -10;
    }
    [encoder dispatchThreads:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    [encoder endEncoding];
    if (entries != NULL) free(entries);
    return 0;
}

int termite_metal_decode_runtime_sample_from_logits_device(
    termite_metal_decode_runtime *runtime,
    void *logits_handle,
    size_t logits_offset,
