int termite_metal_decode_runtime_apply_activation(
    termite_metal_decode_runtime *runtime,
    uint32_t activation_kind,
    const float *input,
    size_t dim,
    float *output
) {
    if (runtime == NULL || input == NULL || output == NULL) return -1;
    if (runtime->activation_pipeline == nil) return -2;
    if (dim == 0 || dim > UINT32_MAX) return -3;
    @autoreleasepool {
        const size_t bytes = dim * sizeof(float);
        id<MTLBuffer> input_buffer = [runtime->device newBufferWithBytesNoCopy:(void *)input length:bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (input_buffer == nil) input_buffer = [runtime->device newBufferWithBytes:input length:bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> output_buffer = [runtime->device newBufferWithBytesNoCopy:output length:bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (output_buffer == nil) output_buffer = [runtime->device newBufferWithBytes:output length:bytes options:MTLResourceStorageModeShared];
        if (input_buffer == nil || output_buffer == nil) return -4;
        termite_metal_apply_activation_params params = {
            .activation_kind = activation_kind,
            .rows = 1,
            .dim = (uint32_t)dim,
        };
        id<MTLBuffer> params_buffer = [runtime->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
        if (params_buffer == nil) return -5;
        id<MTLCommandBuffer> command_buffer = termite_metal_new_command_buffer(runtime->queue, __func__);
        if (command_buffer == nil) return -6;
        id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
        if (encoder == nil) return -7;
        [encoder setComputePipelineState:runtime->activation_pipeline];
        [encoder setBuffer:input_buffer offset:0 atIndex:0];
        [encoder setBuffer:output_buffer offset:0 atIndex:1];
        [encoder setBuffer:params_buffer offset:0 atIndex:2];
        NSUInteger thread_width = runtime->activation_pipeline.maxTotalThreadsPerThreadgroup;
        if (thread_width == 0) thread_width = 64;
        if (thread_width > dim && dim > 0) thread_width = dim;
        [encoder dispatchThreads:MTLSizeMake(dim, 1, 1) threadsPerThreadgroup:MTLSizeMake(thread_width, 1, 1)];
        [encoder endEncoding];
        [command_buffer commit];
        [command_buffer waitUntilCompleted];
        if (command_buffer.status != MTLCommandBufferStatusCompleted) return -8;
        // newBufferWithBytes (the non-page-aligned fallback) snapshots the caller's
        // buffer instead of aliasing it, so results must be copied back after the wait.
        if (output_buffer.contents != (void *)output) memcpy(output, output_buffer.contents, bytes);
        return 0;
    }
}

int termite_metal_decode_runtime_apply_activation_device(
    termite_metal_decode_runtime *runtime,
    uint32_t activation_kind,
    void *input_handle,
    size_t input_offset,
    size_t rows,
    size_t dim,
    void *output_handle,
    size_t output_offset
) {
    if (runtime == NULL || input_handle == NULL || output_handle == NULL) return -1;
    if (runtime->activation_pipeline == nil) return -2;
    if (rows == 0 || dim == 0 || rows > UINT32_MAX || dim > UINT32_MAX) return -3;
    if (rows > SIZE_MAX / dim) return -4;
    @autoreleasepool {
        id<MTLBuffer> input_buffer = (__bridge id<MTLBuffer>)input_handle;
        id<MTLBuffer> output_buffer = (__bridge id<MTLBuffer>)output_handle;
        const size_t total = rows * dim;
        if (total > UINT32_MAX) return -5;
        const size_t bytes = total * sizeof(float);
        if (input_offset + bytes > input_buffer.length) return -6;
        if (output_offset + bytes > output_buffer.length) return -7;
        if (termite_metal_decode_runtime_prepare_planned_compute_unary_accesses(
                runtime,
                input_buffer,
                input_offset,
                bytes,
                output_buffer,
                output_offset,
                bytes,
                -10) != 0)
        {
            return -10;
        }
        termite_metal_apply_activation_params params = {
            .activation_kind = activation_kind,
            .rows = (uint32_t)rows,
            .dim = (uint32_t)dim,
        };
        bool frame_owned = true;
        id<MTLCommandBuffer> command_buffer = termite_metal_decode_runtime_command_buffer(runtime, __func__, &frame_owned);
        if (command_buffer == nil) return -9;
        id<MTLComputeCommandEncoder> encoder = runtime->active_planned_compute_encoder;
        const BOOL planned_encoder = (encoder != nil);
        if (!planned_encoder) {
            encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
        }
        if (encoder == nil) return -10;
        [encoder setComputePipelineState:runtime->activation_pipeline];
        [encoder setBuffer:input_buffer offset:input_offset atIndex:0];
        [encoder setBuffer:output_buffer offset:output_offset atIndex:1];
        [encoder setBytes:&params length:sizeof(params) atIndex:2];
        NSUInteger thread_width = runtime->activation_pipeline.maxTotalThreadsPerThreadgroup;
        if (thread_width == 0) thread_width = 64;
        if (thread_width > total && total > 0) thread_width = total;
        [encoder dispatchThreads:MTLSizeMake(total, 1, 1) threadsPerThreadgroup:MTLSizeMake(thread_width, 1, 1)];
        if (!planned_encoder) [encoder endEncoding];
        return termite_metal_decode_runtime_finish_command_buffer(command_buffer, frame_owned, -11);
    }
}

int termite_metal_decode_runtime_apply_softmax_device(
