int termite_metal_decode_runtime_reduce_last_dim_device(
    termite_metal_decode_runtime *runtime,
    void *input_handle,
    size_t input_offset,
    size_t rows,
    size_t dim,
    uint32_t kind,
    void *output_handle,
    size_t output_offset
) {
    if (runtime == NULL || input_handle == NULL || output_handle == NULL) return -1;
    if (runtime->reduce_last_dim_pipeline == nil) return -2;
    if (rows == 0 || dim == 0 || rows > UINT32_MAX || dim > UINT32_MAX || kind > 2u) return -3;
    if (rows > SIZE_MAX / dim) return -4;
    @autoreleasepool {
        id<MTLBuffer> input_buffer = (__bridge id<MTLBuffer>)input_handle;
        id<MTLBuffer> output_buffer = (__bridge id<MTLBuffer>)output_handle;
        const size_t total = rows * dim;
        if (total > UINT32_MAX) return -5;
        const size_t input_bytes = total * sizeof(float);
        const size_t output_bytes = rows * sizeof(float);
        if (input_offset + input_bytes > input_buffer.length) return -6;
        if (output_offset + output_bytes > output_buffer.length) return -7;
        termite_metal_reduce_last_dim_params params = {
            .rows = (uint32_t)rows,
            .dim = (uint32_t)dim,
            .kind = kind,
            .reserved = 0,
        };
        bool frame_owned = true;
        id<MTLCommandBuffer> command_buffer = termite_metal_decode_runtime_command_buffer(runtime, __func__, &frame_owned);
        if (command_buffer == nil) return -9;
        id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
        if (encoder == nil) return -10;
        [encoder setComputePipelineState:runtime->reduce_last_dim_pipeline];
        [encoder setBuffer:input_buffer offset:input_offset atIndex:0];
