                                                                                  dataType:MPSDataTypeFloat32];
            MPSMatrixDescriptor *right_desc = [MPSMatrixDescriptor matrixDescriptorWithRows:(transpose_right ? n : k)
                                                                                    columns:(transpose_right ? k : n)
                                                                                   rowBytes:(transpose_right ? k : n) * sizeof(float)
                                                                                   dataType:MPSDataTypeFloat32];
