        [command_buffer commit];
        [command_buffer waitUntilCompleted];
        if (command_buffer.status != MTLCommandBufferStatusCompleted) return -22;
        // newBufferWithBytes (the non-page-aligned fallback) snapshots the caller's
        // buffer instead of aliasing it, so results must be copied back after the wait.
        if (output_buffer.contents != (void *)output) memcpy(output, output_buffer.contents, hidden_bytes);
        return 0;
    }
}

int termite_metal_decode_runtime_update_attention_span(
    termite_metal_decode_runtime *runtime,
    const uint8_t *encoded_key,
    const float *v,
    size_t kv_tokens,
    size_t key_row_bytes,
    size_t v_row_stride,
    size_t position_offset
) {
    if (runtime == NULL || encoded_key == NULL || v == NULL) return -1;
    if (kv_tokens == 0 || key_row_bytes == 0 || v_row_stride == 0) return -2;
    @autoreleasepool {
        const size_t encoded_bytes = kv_tokens * key_row_bytes;
        const size_t v_bytes = kv_tokens * v_row_stride * sizeof(float);
        if (termite_metal_decode_runtime_ensure_attention_span_slot_buffers(runtime, 0, encoded_bytes, v_bytes) != 0) return -3;
        if (termite_metal_upload_private_buffer(runtime->device, runtime->queue, runtime->attention_span_encoded_key_buffer, encoded_key, encoded_bytes) != 0) return -5;
        if (termite_metal_upload_private_buffer(runtime->device, runtime->queue, runtime->attention_span_v_buffer, v, v_bytes) != 0) return -6;
        runtime->attention_span_tokens = kv_tokens;
        runtime->attention_span_key_row_bytes = key_row_bytes;
        runtime->attention_span_v_row_stride = v_row_stride;
        runtime->attention_span_position_offset = position_offset;
        runtime->attention_span_encoded_key_buffers[0] = runtime->attention_span_encoded_key_buffer;
        runtime->attention_span_v_buffers[0] = runtime->attention_span_v_buffer;
        runtime->attention_span_encoded_key_capacities[0] = runtime->attention_span_encoded_key_capacity;
        runtime->attention_span_v_capacities[0] = runtime->attention_span_v_capacity;
        runtime->attention_span_slot_tokens[0] = kv_tokens;
        runtime->attention_span_slot_key_row_bytes[0] = key_row_bytes;
        runtime->attention_span_slot_v_row_stride[0] = v_row_stride;
        runtime->attention_span_slot_position_offset[0] = position_offset;
        return 0;
    }
}

