int termite_metal_decode_runtime_update_attention_span_from_f32_key_device_slot(
    termite_metal_decode_runtime *runtime,
    size_t slot,
    uint32_t format,
    void *k_handle,
    size_t k_offset,
    void *v_handle,
    size_t v_offset,
    size_t kv_tokens,
    size_t num_kv_heads,
    size_t head_dim,
    size_t key_row_bytes,
