            runtime,
            encoder,
            slot,
            k_buffer,
            k_offset,
            v_buffer,
            v_offset,
            kv_tokens,
            suffix_tokens,
            num_kv_heads,
            head_dim,
            key_row_bytes,
            v_row_stride,
            position_offset,
            contiguous_block_table,
            1,
            kv_tokens,
            -12);
