static int termite_metal_decode_runtime_encode_attention_span_slot(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    size_t slot,
    uint32_t format,
    id<MTLBuffer> q_buffer,
    size_t q_offset,
    size_t kv_tokens,
    size_t num_heads,
    size_t num_kv_heads,
    size_t head_dim,
    size_t key_row_bytes,
    size_t base_key_row_bytes,
    size_t query_position,
    size_t kv_position_offset,
    size_t sliding_window,
    id<MTLBuffer> output_buffer,
    size_t output_offset
) {
    if (runtime == NULL || command_buffer == nil || q_buffer == nil || output_buffer == nil) return -1;
    if (kv_tokens == 0 || num_heads == 0 || num_kv_heads == 0 || head_dim == 0) return -2;
    if (num_heads > UINT32_MAX || num_kv_heads > UINT32_MAX || head_dim > UINT32_MAX || kv_tokens > UINT32_MAX) return -3;
    if (key_row_bytes > UINT32_MAX || base_key_row_bytes > UINT32_MAX || query_position > UINT32_MAX || kv_position_offset > UINT32_MAX || sliding_window > UINT32_MAX) return -4;
    if (slot >= TERMITE_METAL_ATTENTION_SPAN_SLOT_CAPACITY) return -5;
    if (runtime->attention_span_encoded_key_buffers[slot] == nil || runtime->attention_span_v_buffers[slot] == nil) return -6;
    if (runtime->attention_span_slot_tokens[slot] != kv_tokens || runtime->attention_span_slot_key_row_bytes[slot] != key_row_bytes || runtime->attention_span_slot_position_offset[slot] != kv_position_offset) return -7;
    id<MTLComputePipelineState> pipeline = nil;
    switch (format) {
        case 0u: pipeline = runtime->polar4_attention_span_pipeline; break;
        case 1u: pipeline = runtime->turbo3_attention_span_pipeline; break;
        default: return -8;
    }
    if (pipeline == nil) return -9;
    termite_metal_attention_span_params params = {
        .kv_tokens = (uint32_t)kv_tokens,
        .num_heads = (uint32_t)num_heads,
        .num_kv_heads = (uint32_t)num_kv_heads,
        .head_dim = (uint32_t)head_dim,
        .key_row_bytes = (uint32_t)key_row_bytes,
        .base_key_row_bytes = (uint32_t)base_key_row_bytes,
        .query_position = (uint32_t)query_position,
        .kv_position_offset = (uint32_t)kv_position_offset,
        .sliding_window = (uint32_t)sliding_window,
        .v_row_stride = (uint32_t)runtime->attention_span_slot_v_row_stride[slot],
    };
    id<MTLBuffer> params_buffer = [runtime->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
    if (params_buffer == nil) return -10;
    id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
    if (encoder == nil) return -11;
    [encoder setComputePipelineState:pipeline];
    [encoder setBuffer:q_buffer offset:q_offset atIndex:0];
    [encoder setBuffer:runtime->attention_span_encoded_key_buffers[slot] offset:0 atIndex:1];
    [encoder setBuffer:runtime->attention_span_v_buffers[slot] offset:0 atIndex:2];
    [encoder setBuffer:output_buffer offset:output_offset atIndex:3];
    [encoder setBuffer:params_buffer offset:0 atIndex:4];
    [encoder dispatchThreads:MTLSizeMake(num_heads, 1, 1) threadsPerThreadgroup:MTLSizeMake(termite_metal_thread_width(pipeline, num_heads), 1, 1)];
    [encoder endEncoding];
    return 0;
}

static int termite_metal_apply_optional_norm(
    termite_metal_decode_runtime *runtime,
    size_t layer_norm_slot,
    size_t rms_norm_slot,
    const float *input,
    size_t hidden_size,
    float eps,
    float *output
) {
    if (layer_norm_slot != SIZE_MAX) {
        return termite_metal_decode_runtime_apply_layer_norm(
            runtime,
            layer_norm_slot,
            input,
            1,
            hidden_size,
            eps,
            output
        );
    }
    if (rms_norm_slot != SIZE_MAX) {
        return termite_metal_decode_runtime_apply_rms_norm(
            runtime,
            rms_norm_slot,
            input,
            hidden_size,
            eps,
            output
        );
    }
    if (input != output) {
        memcpy(output, input, hidden_size * sizeof(float));
    }
    return 0;
}

static NSUInteger termite_metal_thread_width(id<MTLComputePipelineState> pipeline, size_t dim) {
    NSUInteger thread_width = pipeline.maxTotalThreadsPerThreadgroup;
    if (thread_width == 0) thread_width = 64;
    if (dim > 0 && thread_width > dim) thread_width = dim;
    return thread_width;
}

static NSUInteger termite_metal_sdpa_thread_width(id<MTLComputePipelineState> pipeline, size_t seq_len, size_t head_dim) {
    if (pipeline == nil) return 0;
    NSUInteger max_width = pipeline.maxTotalThreadsPerThreadgroup;
    if (max_width == 0u) return 0;
    NSUInteger width = pipeline.threadExecutionWidth;
    if (width == 0u) width = 32u;
    const size_t work = seq_len > head_dim ? seq_len : head_dim;
    while (width < 256u && width < max_width && width < work) {
        const NSUInteger next = width << 1u;
        if (next > max_width) break;
        width = next;
    }
    return width;
}

static NSUInteger termite_metal_threadgroup_memory_16(NSUInteger bytes) {
    return (bytes + 15u) & ~(NSUInteger)15u;
}

static int termite_metal_decode_runtime_encode_attention_block_prefix(
    termite_metal_decode_runtime *runtime,
    id<MTLCommandBuffer> command_buffer,
    id<MTLBuffer> attention_input_buffer,
    size_t attention_input_offset,
    size_t attention_pre_linear_rms_norm_slot,
    size_t attention_linear_slot,
    size_t attention_post_linear_rms_norm_slot,
    id<MTLBuffer> residual_buffer,
    size_t residual_offset,
    size_t attention_input_size,
    size_t hidden_size,
    float eps,
    size_t ffn_layer_norm_slot,
    size_t ffn_rms_norm_slot,
    id<MTLBuffer> attn_added_buffer,
    size_t attn_added_offset,
    id<MTLBuffer> ffn_input_buffer,
    size_t ffn_input_offset
) {
    if (runtime == NULL || command_buffer == nil || attention_input_buffer == nil || residual_buffer == nil || attn_added_buffer == nil || ffn_input_buffer == nil) return -1;
    if (runtime->linear_pipeline == nil || runtime->linear_reduce_pipeline == nil || runtime->add_pipeline == nil) return -2;
    if (attention_linear_slot >= TERMITE_METAL_LINEAR_SLOT_CAPACITY || runtime->linear_slot_prepared[attention_linear_slot] == 0) return -3;
    if (runtime->linear_in_dims[attention_linear_slot] != attention_input_size || runtime->linear_out_dims[attention_linear_slot] != hidden_size) return -4;
    if (attention_input_size == 0 || hidden_size == 0 || attention_input_size > UINT32_MAX || hidden_size > UINT32_MAX) return -5;
    @autoreleasepool {
        const size_t hidden_bytes = hidden_size * sizeof(float);
        const size_t attention_input_bytes = attention_input_size * sizeof(float);
        const size_t scratch_bytes = attention_input_bytes > hidden_bytes ? attention_input_bytes : hidden_bytes;
        id<MTLBuffer> tmp_a = [runtime->device newBufferWithLength:scratch_bytes options:MTLResourceStorageModePrivate];
        id<MTLBuffer> tmp_b = [runtime->device newBufferWithLength:scratch_bytes options:MTLResourceStorageModePrivate];
        if (tmp_a == nil || tmp_b == nil) return -6;

        id<MTLBuffer> current_buffer = attention_input_buffer;
        NSUInteger current_offset = attention_input_offset;
        if (attention_pre_linear_rms_norm_slot != SIZE_MAX) {
            termite_metal_apply_layer_norm_params params = { .hidden_size = (uint32_t)attention_input_size, .eps = eps };
            id<MTLBuffer> params_buffer = [runtime->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
            if (params_buffer == nil) return -7;
            id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder_for(command_buffer, TERMITE_METAL_COMPUTE_SOURCE_ATTENTION);
            if (encoder == nil) return -8;
            [encoder setComputePipelineState:runtime->rms_norm_pipeline];
            [encoder setBuffer:current_buffer offset:current_offset atIndex:0];
            [encoder setBuffer:runtime->rms_norm_weight_buffers[attention_pre_linear_rms_norm_slot] offset:0 atIndex:1];
            [encoder setBuffer:tmp_a offset:0 atIndex:2];
            [encoder setBuffer:params_buffer offset:0 atIndex:3];
            [encoder dispatchThreads:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
            [encoder endEncoding];
            current_buffer = tmp_a;
            current_offset = 0;
        }

        {
            termite_metal_apply_linear_params params = { .in_dim = (uint32_t)attention_input_size, .out_dim = (uint32_t)hidden_size };
            id<MTLBuffer> params_buffer = [runtime->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
            if (params_buffer == nil) return -9;
            id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
            if (encoder == nil) return -10;
            const BOOL use_reduce = hidden_size >= 128;
            [encoder setComputePipelineState:(use_reduce ? runtime->linear_reduce_pipeline : runtime->linear_pipeline)];
            [encoder setBuffer:current_buffer offset:current_offset atIndex:0];
            [encoder setBuffer:runtime->linear_weight_buffers[attention_linear_slot] offset:0 atIndex:1];
            [encoder setBuffer:runtime->linear_bias_buffers[attention_linear_slot] offset:0 atIndex:2];
            [encoder setBuffer:tmp_b offset:0 atIndex:3];
            [encoder setBuffer:params_buffer offset:0 atIndex:4];
            if (use_reduce) {
                [encoder dispatchThreads:MTLSizeMake(hidden_size * 32u, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
            } else {
                [encoder dispatchThreads:MTLSizeMake(hidden_size, 1, 1) threadsPerThreadgroup:MTLSizeMake(termite_metal_thread_width(runtime->linear_pipeline, hidden_size), 1, 1)];
            }
            [encoder endEncoding];
            current_buffer = tmp_b;
            current_offset = 0;
        }

        if (attention_post_linear_rms_norm_slot != SIZE_MAX) {
            termite_metal_apply_layer_norm_params params = { .hidden_size = (uint32_t)hidden_size, .eps = eps };
            id<MTLBuffer> params_buffer = [runtime->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
            if (params_buffer == nil) return -11;
            id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
            if (encoder == nil) return -12;
            [encoder setComputePipelineState:runtime->rms_norm_pipeline];
            [encoder setBuffer:current_buffer offset:current_offset atIndex:0];
            [encoder setBuffer:runtime->rms_norm_weight_buffers[attention_post_linear_rms_norm_slot] offset:0 atIndex:1];
            [encoder setBuffer:tmp_a offset:0 atIndex:2];
            [encoder setBuffer:params_buffer offset:0 atIndex:3];
            [encoder dispatchThreads:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
            [encoder endEncoding];
            current_buffer = tmp_a;
            current_offset = 0;
        }

        {
            termite_metal_apply_add_params params = { .rows = 1, .dim = (uint32_t)hidden_size };
            id<MTLBuffer> params_buffer = [runtime->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
            if (params_buffer == nil) return -13;
            id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
            if (encoder == nil) return -14;
            [encoder setComputePipelineState:runtime->add_pipeline];
            [encoder setBuffer:current_buffer offset:current_offset atIndex:0];
            [encoder setBuffer:residual_buffer offset:residual_offset atIndex:1];
            [encoder setBuffer:attn_added_buffer offset:attn_added_offset atIndex:2];
            [encoder setBuffer:params_buffer offset:0 atIndex:3];
            [encoder dispatchThreads:MTLSizeMake(hidden_size, 1, 1) threadsPerThreadgroup:MTLSizeMake(termite_metal_thread_width(runtime->add_pipeline, hidden_size), 1, 1)];
            [encoder endEncoding];
        }

        if (ffn_layer_norm_slot != SIZE_MAX) {
            termite_metal_apply_layer_norm_params params = { .hidden_size = (uint32_t)hidden_size, .eps = eps };
            id<MTLBuffer> params_buffer = [runtime->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
            if (params_buffer == nil) return -15;
            id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
            if (encoder == nil) return -16;
            [encoder setComputePipelineState:runtime->layer_norm_pipeline];
            [encoder setBuffer:attn_added_buffer offset:attn_added_offset atIndex:0];
