int termite_metal_provider_generated_quant_snapshot(
    termite_metal_provider *provider,
    termite_metal_decode_runtime_memory_stats *snapshot
) {
    if (snapshot == NULL) return -1;
    memset(snapshot, 0, sizeof(*snapshot));
    if (provider == NULL) return -2;

    memcpy(snapshot->antfly_generated_dispatch_counts, provider->antfly_generated_dispatch_counts, sizeof(snapshot->antfly_generated_dispatch_counts));
    return 0;
}

int termite_metal_decode_runtime_reserve(termite_metal_decode_runtime *runtime, size_t scratch_bytes, size_t token_bytes) {
    if (runtime == NULL) return -1;
    if (termite_metal_decode_runtime_ready(runtime) == 0) return -2;
    @autoreleasepool {
        if (scratch_bytes > runtime->scratch_capacity) {
            id<MTLBuffer> scratch = [runtime->device newBufferWithLength:scratch_bytes options:MTLResourceStorageModePrivate];
            if (scratch == nil) return -3;
            runtime->scratch_buffer = scratch;
            runtime->scratch_capacity = scratch_bytes;
        }
        if (token_bytes > runtime->token_capacity) {
            id<MTLBuffer> token = [runtime->device newBufferWithLength:token_bytes options:MTLResourceStorageModeShared];
            if (token == nil) return -4;
            runtime->token_buffer = token;
            runtime->token_capacity = token_bytes;
        }
        return 0;
    }
}

static int termite_metal_buffer_reuse_enabled(termite_metal_decode_runtime *runtime) {
    if (runtime == NULL) return 0;
    if (runtime->buffer_reuse_enabled < 0) {
        const char *env = getenv("TERMITE_METAL_BUFFER_REUSE");
        runtime->buffer_reuse_enabled = (env != NULL && (env[0] == '0' || env[0] == 'f' || env[0] == 'F')) ? 0 : 1;
    }
    return runtime->buffer_reuse_enabled;
}

static void *termite_metal_buffer_alloc_new(
    termite_metal_decode_runtime *runtime,
    size_t length,
    int storage_mode
) {
    @autoreleasepool {
        MTLResourceOptions options = (storage_mode == 1)
            ? MTLResourceStorageModePrivate
            : MTLResourceStorageModeShared;
        id<MTLBuffer> buffer = [runtime->device newBufferWithLength:length options:options];
        if (buffer == nil) return NULL;
        return (__bridge_retained void *)buffer;
    }
}

void *termite_metal_buffer_alloc(termite_metal_decode_runtime *runtime, size_t length, int storage_mode) {
    if (runtime == NULL || runtime->device == nil || length == 0) return NULL;
    // In-frame reuse: serve a same-or-larger released private buffer from the
    // pool (best-fit) instead of allocating. The returned handle keeps the
    // pooled buffer's +1 ownership (transferred to the caller).
    if (storage_mode == 1 && runtime->active_frame_cb != nil &&
        termite_metal_buffer_reuse_enabled(runtime)) {
        runtime->reuse_alloc_count += 1;
        if (runtime->frame_reuse_pool_len > 0) {
            size_t best_idx = (size_t)-1;
            size_t best_len = (size_t)-1;
            for (size_t i = 0; i < runtime->frame_reuse_pool_len; ++i) {
                id<MTLBuffer> b = (__bridge id<MTLBuffer>)runtime->frame_reuse_pool[i];
                size_t blen = (size_t)b.length;
                if (blen >= length && blen < best_len) {
                    best_len = blen;
                    best_idx = i;
                }
            }
            if (best_idx != (size_t)-1) {
                void *handle = runtime->frame_reuse_pool[best_idx];
                runtime->frame_reuse_pool[best_idx] =
                    runtime->frame_reuse_pool[--runtime->frame_reuse_pool_len];
                runtime->reuse_hit_count += 1;
                return handle;
            }
        }
    }
    return termite_metal_buffer_alloc_new(runtime, length, storage_mode);
}

void *termite_metal_buffer_alloc_fresh(termite_metal_decode_runtime *runtime, size_t length, int storage_mode) {
    if (runtime == NULL || runtime->device == nil || length == 0) return NULL;
    return termite_metal_buffer_alloc_new(runtime, length, storage_mode);
}

void termite_metal_buffer_release(void *handle) {
    if (handle == NULL) return;
    id<MTLBuffer> buffer = (__bridge_transfer id<MTLBuffer>)handle;
    (void)buffer;
}

void termite_metal_decode_runtime_release_buffer(termite_metal_decode_runtime *runtime, void *handle) {
    if (handle == NULL) return;
    // During the active frame, pool the (now dead, refcount-0) buffer for
    // reuse instead of just frame-retaining it. The pool keeps the handle's
    // +1, so the buffer stays alive for the in-flight frame AND is available
    // to satisfy a later same-frame allocation.
    if (runtime != NULL && runtime->active_frame_cb != nil &&
        termite_metal_buffer_reuse_enabled(runtime)) {
        if (runtime->frame_reuse_pool_len >= runtime->frame_reuse_pool_cap) {
            size_t new_cap = runtime->frame_reuse_pool_cap == 0 ? 256 : runtime->frame_reuse_pool_cap * 2;
            void **grown = realloc(runtime->frame_reuse_pool, new_cap * sizeof(void *));
            if (grown != NULL) {
                runtime->frame_reuse_pool = grown;
                runtime->frame_reuse_pool_cap = new_cap;
            }
        }
        if (runtime->frame_reuse_pool_len < runtime->frame_reuse_pool_cap) {
            runtime->frame_reuse_pool[runtime->frame_reuse_pool_len++] = handle;
            if (runtime->frame_reuse_pool_len > runtime->reuse_pool_peak_len) {
                runtime->reuse_pool_peak_len = runtime->frame_reuse_pool_len;
            }
            return;
        }
        // realloc failed: fall through to the normal frame-retain path.
    }
    @autoreleasepool {
        id<MTLBuffer> buffer = (__bridge_transfer id<MTLBuffer>)handle;
        if (runtime != NULL && (runtime->active_frame_cb != nil || runtime->submitted_frame_cb != nil)) {
            (void)termite_metal_decode_runtime_retain_frame_resource(runtime, buffer);
        }
    }
}

void *termite_metal_buffer_contents(void *handle) {
    if (handle == NULL) return NULL;
    id<MTLBuffer> buffer = (__bridge id<MTLBuffer>)handle;
    if (buffer.storageMode != MTLStorageModeShared) return NULL;
    return buffer.contents;
}

int termite_metal_buffer_upload(
    termite_metal_decode_runtime *runtime,
    void *handle,
    size_t offset,
    const void *src,
    size_t length
) {
    if (handle == NULL || src == NULL || length == 0) return -1;
    @autoreleasepool {
        id<MTLBuffer> dst = (__bridge id<MTLBuffer>)handle;
        if (offset + length > dst.length) return -2;
        if (dst.storageMode == MTLStorageModeShared) {
            memcpy((uint8_t *)dst.contents + offset, src, length);
            return 0;
        }
        if (runtime == NULL || runtime->device == nil || runtime->queue == nil) return -3;
        id<MTLBuffer> staging = [runtime->device newBufferWithBytes:src length:length options:MTLResourceStorageModeShared];
        if (staging == nil) return -4;
        bool frame_owned = true;
        id<MTLCommandBuffer> command_buffer = termite_metal_decode_runtime_command_buffer(runtime, __func__, &frame_owned);
        if (command_buffer == nil) return -5;
        if (!frame_owned && termite_metal_decode_runtime_retain_frame_resource(runtime, staging) != 0) return -4;
        termite_metal_record_active_frame_blit_source(command_buffer, TERMITE_METAL_BLIT_SOURCE_BUFFER_UPLOAD);
        id<MTLBlitCommandEncoder> blit = termite_metal_tracked_blit_command_encoder(command_buffer);
        if (blit == nil) return -6;
        if ([blit respondsToSelector:@selector(setLabel:)]) {
            blit.label = @"buffer-upload";
        }
        [blit copyFromBuffer:staging sourceOffset:0 toBuffer:dst destinationOffset:offset size:length];
        [blit endEncoding];
        return termite_metal_decode_runtime_finish_command_buffer(command_buffer, frame_owned, -7);
    }
}

int termite_metal_buffer_download(
    termite_metal_decode_runtime *runtime,
    void *handle,
    size_t offset,
    void *dst,
    size_t length
) {
    if (handle == NULL || dst == NULL || length == 0) return -1;
    @autoreleasepool {
        id<MTLBuffer> src = (__bridge id<MTLBuffer>)handle;
        if (offset + length > src.length) return -2;
        if (src.storageMode == MTLStorageModeShared) {
            if (termite_metal_trace_frame_lifecycle_enabled()) {
                fprintf(stderr, "metal_frame_lifecycle: buffer_download storage=shared length=%zu offset=%zu\n", length, offset);
            }
            if (runtime != NULL && termite_metal_decode_runtime_flush_active_frame(runtime) != 0) return -8;
            memcpy(dst, (const uint8_t *)src.contents + offset, length);
            return 0;
        }
        if (runtime == NULL || runtime->device == nil || runtime->queue == nil) return -3;
        if (termite_metal_trace_frame_lifecycle_enabled()) {
            fprintf(stderr, "metal_frame_lifecycle: buffer_download storage=private length=%zu offset=%zu\n", length, offset);
        }
        if (termite_metal_decode_runtime_flush_active_frame(runtime) != 0) return -8;
        id<MTLBuffer> staging = [runtime->device newBufferWithLength:length options:MTLResourceStorageModeShared];
        if (staging == nil) return -4;
        id<MTLCommandBuffer> command_buffer = termite_metal_new_command_buffer(runtime->queue, __func__);
        if (command_buffer == nil) return -5;
        id<MTLBlitCommandEncoder> blit = termite_metal_tracked_blit_command_encoder(command_buffer);
        if (blit == nil) return -6;
        if ([blit respondsToSelector:@selector(setLabel:)]) {
            blit.label = @"buffer-download";
        }
        [blit copyFromBuffer:src sourceOffset:offset toBuffer:staging destinationOffset:0 size:length];
        [blit endEncoding];
        if (termite_metal_commit_and_wait(command_buffer, __func__, -7) != 0) return -7;
        memcpy(dst, staging.contents, length);
        return 0;
    }
}

int termite_metal_buffer_copy(
    termite_metal_decode_runtime *runtime,
    void *src_handle,
    size_t src_offset,
    void *dst_handle,
    size_t dst_offset,
    size_t length
) {
    if (src_handle == NULL || dst_handle == NULL || length == 0) return -1;
    @autoreleasepool {
        id<MTLBuffer> src = (__bridge id<MTLBuffer>)src_handle;
        id<MTLBuffer> dst = (__bridge id<MTLBuffer>)dst_handle;
        if (src_offset + length > src.length || dst_offset + length > dst.length) return -2;
        if (src.storageMode == MTLStorageModeShared && dst.storageMode == MTLStorageModeShared) {
            memcpy((uint8_t *)dst.contents + dst_offset, (const uint8_t *)src.contents + src_offset, length);
            return 0;
        }
        if (runtime == NULL || runtime->device == nil || runtime->queue == nil) return -3;
        bool frame_owned = true;
        id<MTLCommandBuffer> command_buffer = termite_metal_decode_runtime_command_buffer(runtime, __func__, &frame_owned);
        if (command_buffer == nil) return -4;
        termite_metal_record_active_frame_blit_source(command_buffer, TERMITE_METAL_BLIT_SOURCE_BUFFER_COPY);
        if (!frame_owned && termite_metal_trace_frame_blits_enabled()) {
            fprintf(stderr, "metal_frame_blit: kind=copy length=%zu src_offset=%zu dst_offset=%zu\n", length, src_offset, dst_offset);
        }
        id<MTLBlitCommandEncoder> blit = termite_metal_tracked_blit_command_encoder(command_buffer);
        if (blit == nil) return -5;
        if ([blit respondsToSelector:@selector(setLabel:)]) {
            blit.label = @"buffer-copy";
        }
        [blit copyFromBuffer:src sourceOffset:src_offset toBuffer:dst destinationOffset:dst_offset size:length];
        [blit endEncoding];
        return termite_metal_decode_runtime_finish_command_buffer(command_buffer, frame_owned, -6);
    }
}

int termite_metal_buffer_copy_pair(
    termite_metal_decode_runtime *runtime,
    void *src_a_handle,
    size_t src_a_offset,
    void *dst_a_handle,
    size_t dst_a_offset,
    size_t length_a,
    void *src_b_handle,
    size_t src_b_offset,
    void *dst_b_handle,
    size_t dst_b_offset,
    size_t length_b
) {
    if (src_a_handle == NULL || dst_a_handle == NULL || src_b_handle == NULL || dst_b_handle == NULL) return -1;
    if (length_a == 0 || length_b == 0) return -2;
    @autoreleasepool {
        id<MTLBuffer> src_a = (__bridge id<MTLBuffer>)src_a_handle;
        id<MTLBuffer> dst_a = (__bridge id<MTLBuffer>)dst_a_handle;
        id<MTLBuffer> src_b = (__bridge id<MTLBuffer>)src_b_handle;
        id<MTLBuffer> dst_b = (__bridge id<MTLBuffer>)dst_b_handle;
        if (src_a_offset + length_a > src_a.length || dst_a_offset + length_a > dst_a.length) return -3;
        if (src_b_offset + length_b > src_b.length || dst_b_offset + length_b > dst_b.length) return -4;
        if (src_a.storageMode == MTLStorageModeShared &&
            dst_a.storageMode == MTLStorageModeShared &&
            src_b.storageMode == MTLStorageModeShared &&
            dst_b.storageMode == MTLStorageModeShared) {
            memcpy((uint8_t *)dst_a.contents + dst_a_offset, (const uint8_t *)src_a.contents + src_a_offset, length_a);
            memcpy((uint8_t *)dst_b.contents + dst_b_offset, (const uint8_t *)src_b.contents + src_b_offset, length_b);
            return 0;
        }
        if (runtime == NULL || runtime->device == nil || runtime->queue == nil) return -5;
        bool frame_owned = true;
        id<MTLCommandBuffer> command_buffer = termite_metal_decode_runtime_command_buffer(runtime, __func__, &frame_owned);
        if (command_buffer == nil) return -6;
        termite_metal_record_active_frame_blit_source(command_buffer, TERMITE_METAL_BLIT_SOURCE_BUFFER_COPY);
        if (!frame_owned && termite_metal_trace_frame_blits_enabled()) {
            fprintf(stderr, "metal_frame_blit: kind=copy_pair length_a=%zu length_b=%zu src_a_offset=%zu dst_a_offset=%zu src_b_offset=%zu dst_b_offset=%zu\n", length_a, length_b, src_a_offset, dst_a_offset, src_b_offset, dst_b_offset);
        }
        id<MTLBlitCommandEncoder> blit = termite_metal_tracked_blit_command_encoder(command_buffer);
        if (blit == nil) return -7;
        if ([blit respondsToSelector:@selector(setLabel:)]) {
            blit.label = @"buffer-copy-pair";
        }
        [blit copyFromBuffer:src_a sourceOffset:src_a_offset toBuffer:dst_a destinationOffset:dst_a_offset size:length_a];
        [blit copyFromBuffer:src_b sourceOffset:src_b_offset toBuffer:dst_b destinationOffset:dst_b_offset size:length_b];
        [blit endEncoding];
        return termite_metal_decode_runtime_finish_command_buffer(command_buffer, frame_owned, -8);
    }
}

int termite_metal_buffer_slice_last_dim_2d(
    termite_metal_decode_runtime *runtime,
    void *src_handle,
    size_t src_offset,
    size_t rows,
    size_t cols,
    size_t start,
    size_t out_cols,
    void *dst_handle,
    size_t dst_offset
) {
    if (runtime == NULL || runtime->queue == nil || src_handle == NULL || dst_handle == NULL) return -1;
    if (rows == 0 || cols == 0 || out_cols == 0 || start > cols || out_cols > cols - start) return -2;
    if (rows > UINT32_MAX || cols > UINT32_MAX || start > UINT32_MAX || out_cols > UINT32_MAX) return -2;
    @autoreleasepool {
        id<MTLBuffer> src = (__bridge id<MTLBuffer>)src_handle;
        id<MTLBuffer> dst = (__bridge id<MTLBuffer>)dst_handle;
        const size_t elem_size = sizeof(float);
        const size_t row_bytes = out_cols * elem_size;
        const size_t src_required = src_offset + ((rows - 1) * cols + start + out_cols) * elem_size;
        const size_t dst_required = dst_offset + rows * out_cols * elem_size;
        if (src_required > src.length || dst_required > dst.length) return -3;
        if (runtime->slice_last_dim_f32_2d_pipeline != nil) {
            termite_metal_slice_last_dim_f32_2d_params params = {
                .rows = (uint32_t)rows,
                .cols = (uint32_t)cols,
                .start = (uint32_t)start,
                .out_cols = (uint32_t)out_cols,
            };
            const size_t total = rows * out_cols;
            id<MTLComputeCommandEncoder> planned_encoder = runtime->active_planned_compute_encoder;
            if (planned_encoder != nil) {
                if (src_required < src_offset || dst_required < dst_offset) return -3;
                if (termite_metal_decode_runtime_prepare_planned_compute_unary_accesses(
                        runtime,
                        src,
                        src_offset,
                        src_required - src_offset,
                        dst,
                        dst_offset,
                        dst_required - dst_offset,
                        -3) != 0)
                {
                    return -3;
                }
                [planned_encoder setComputePipelineState:runtime->slice_last_dim_f32_2d_pipeline];
                [planned_encoder setBuffer:src offset:src_offset atIndex:0];
                [planned_encoder setBuffer:dst offset:dst_offset atIndex:1];
                [planned_encoder setBytes:&params length:sizeof(params) atIndex:2];
                [planned_encoder dispatchThreads:MTLSizeMake(total, 1, 1)
                           threadsPerThreadgroup:MTLSizeMake(termite_metal_thread_width(runtime->slice_last_dim_f32_2d_pipeline, total), 1, 1)];
                return 0;
            }
            bool frame_owned = true;
            id<MTLCommandBuffer> command_buffer = termite_metal_decode_runtime_command_buffer(runtime, __func__, &frame_owned);
            if (command_buffer == nil) return -4;
            id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder_for(command_buffer, TERMITE_METAL_COMPUTE_SOURCE_OTHER);
            if (encoder == nil) return -5;
            [encoder setComputePipelineState:runtime->slice_last_dim_f32_2d_pipeline];
            [encoder setBuffer:src offset:src_offset atIndex:0];
            [encoder setBuffer:dst offset:dst_offset atIndex:1];
            [encoder setBytes:&params length:sizeof(params) atIndex:2];
            [encoder dispatchThreads:MTLSizeMake(total, 1, 1)
               threadsPerThreadgroup:MTLSizeMake(termite_metal_thread_width(runtime->slice_last_dim_f32_2d_pipeline, total), 1, 1)];
            [encoder endEncoding];
            return termite_metal_decode_runtime_finish_command_buffer(command_buffer, frame_owned, -6);
        }
        bool frame_owned = true;
        id<MTLCommandBuffer> command_buffer = termite_metal_decode_runtime_command_buffer(runtime, __func__, &frame_owned);
        if (command_buffer == nil) return -4;
        termite_metal_record_active_frame_blit_source(command_buffer, TERMITE_METAL_BLIT_SOURCE_BUFFER_SLICE);
        if (!frame_owned && termite_metal_trace_frame_blits_enabled()) {
            fprintf(stderr, "metal_frame_blit: kind=slice_last_dim rows=%zu cols=%zu start=%zu out_cols=%zu row_bytes=%zu\n", rows, cols, start, out_cols, row_bytes);
        }
        id<MTLBlitCommandEncoder> blit = termite_metal_tracked_blit_command_encoder(command_buffer);
        if (blit == nil) return -5;
        if ([blit respondsToSelector:@selector(setLabel:)]) {
            blit.label = @"buffer-slice-last-dim-2d";
        }
        for (size_t row = 0; row < rows; ++row) {
            const size_t src_row_offset = src_offset + (row * cols + start) * elem_size;
            const size_t dst_row_offset = dst_offset + row * out_cols * elem_size;
            [blit copyFromBuffer:src sourceOffset:src_row_offset toBuffer:dst destinationOffset:dst_row_offset size:row_bytes];
        }
        [blit endEncoding];
        return termite_metal_decode_runtime_finish_command_buffer(command_buffer, frame_owned, -6);
    }
}

int termite_metal_decode_runtime_reserve_hidden_state(
    termite_metal_decode_runtime *runtime,
    size_t max_prefill_rows,
    size_t hidden_size
) {
    if (runtime == NULL || runtime->device == nil) return -1;
    if (max_prefill_rows == 0 || hidden_size == 0) return -2;
    const size_t required_bytes = max_prefill_rows * hidden_size * sizeof(float);
    @autoreleasepool {
        if (required_bytes > runtime->hidden_state_capacity) {
            id<MTLBuffer> front = [runtime->device newBufferWithLength:required_bytes options:MTLResourceStorageModePrivate];
            if (front == nil) return -3;
            id<MTLBuffer> back = [runtime->device newBufferWithLength:required_bytes options:MTLResourceStorageModePrivate];
            if (back == nil) return -4;
            runtime->hidden_state_front = front;
            runtime->hidden_state_back = back;
            runtime->hidden_state_capacity = required_bytes;
        }
        runtime->hidden_state_max_rows = max_prefill_rows;
        runtime->hidden_state_hidden_size = hidden_size;
        return 0;
    }
}

void *termite_metal_decode_runtime_hidden_state_buffer(
    termite_metal_decode_runtime *runtime,
    int which
) {
    if (runtime == NULL) return NULL;
    id<MTLBuffer> buffer = (which == 0) ? runtime->hidden_state_front : runtime->hidden_state_back;
    if (buffer == nil) return NULL;
    return (__bridge_retained void *)buffer;
}

size_t termite_metal_decode_runtime_hidden_state_capacity(
    termite_metal_decode_runtime *runtime
) {
    if (runtime == NULL) return 0;
    return runtime->hidden_state_capacity;
}

size_t termite_metal_decode_runtime_hidden_state_max_rows(
    termite_metal_decode_runtime *runtime
) {
    if (runtime == NULL) return 0;
    return runtime->hidden_state_max_rows;
}

void *termite_metal_decode_runtime_acquire_scratch(
    termite_metal_decode_runtime *runtime,
    size_t bytes
) {
    if (runtime == NULL || runtime->device == nil || bytes == 0) return NULL;
    @autoreleasepool {
        // Prefer an idle slot that already has enough capacity — no allocation.
        for (size_t slot = 0; slot < TERMITE_METAL_SCRATCH_POOL_CAPACITY; ++slot) {
            if (runtime->scratch_pool_in_use[slot] == 0 &&
                runtime->scratch_pool_pending_frame_release[slot] == 0 &&
                runtime->scratch_pool_buffers[slot] != nil &&
                runtime->scratch_pool_capacities[slot] >= bytes) {
                runtime->scratch_pool_in_use[slot] = 1;
                return (__bridge_retained void *)runtime->scratch_pool_buffers[slot];
            }
        }
        // Fallback: find the first idle slot and (re)allocate it to fit.
        for (size_t slot = 0; slot < TERMITE_METAL_SCRATCH_POOL_CAPACITY; ++slot) {
            if (runtime->scratch_pool_in_use[slot] == 0 && runtime->scratch_pool_pending_frame_release[slot] == 0) {
                id<MTLBuffer> buffer = [runtime->device newBufferWithLength:bytes options:MTLResourceStorageModePrivate];
                if (buffer == nil) return NULL;
                runtime->scratch_pool_buffers[slot] = buffer;
                runtime->scratch_pool_capacities[slot] = bytes;
                runtime->scratch_pool_in_use[slot] = 1;
                return (__bridge_retained void *)buffer;
            }
        }
        // Pool exhausted — caller can fall back to `termite_metal_buffer_alloc`.
        return NULL;
    }
}

void termite_metal_decode_runtime_release_scratch(
    termite_metal_decode_runtime *runtime,
    void *handle
) {
    if (handle == NULL) return;
    // Consume the caller's +1 retain from acquire; the slot's own strong
    // reference in `scratch_pool_buffers[slot]` keeps the buffer alive across
    // frames so the next acquire can reuse the allocation.
    id<MTLBuffer> buffer = (__bridge_transfer id<MTLBuffer>)handle;
    if (runtime == NULL) {
        (void)buffer;
        return;
    }
    for (size_t slot = 0; slot < TERMITE_METAL_SCRATCH_POOL_CAPACITY; ++slot) {
        if (runtime->scratch_pool_buffers[slot] == buffer) {
            if (runtime->active_frame_cb != nil || runtime->submitted_frame_cb != nil) {
                runtime->scratch_pool_pending_frame_release[slot] = 1;
                runtime->scratch_pool_in_use[slot] = 1;
            } else {
                runtime->scratch_pool_pending_frame_release[slot] = 0;
                runtime->scratch_pool_in_use[slot] = 0;
            }
            break;
        }
    }
    (void)buffer;
}

int termite_metal_decode_runtime_prepare_decoder_only_greedy(
    termite_metal_decode_runtime *runtime,
    size_t hidden_size,
    size_t intermediate_size,
    size_t num_layers,
    size_t num_heads,
    size_t num_kv_heads,
    size_t head_dim,
    size_t vocab_size,
    size_t kv_tokens
) {
    if (runtime == NULL) return -1;
    if (hidden_size == 0 || intermediate_size == 0 || num_layers == 0 || num_heads == 0 || num_kv_heads == 0 || head_dim == 0 || vocab_size == 0) return -2;

    const size_t hidden_bytes = hidden_size * sizeof(float);
    const size_t q_bytes = num_heads * head_dim * sizeof(float);
    const size_t kv_bytes = num_kv_heads * head_dim * sizeof(float);
    const size_t attn_bytes = num_heads * head_dim * sizeof(float);
    const size_t mlp_bytes = intermediate_size * sizeof(float) * 2u;
    const size_t layer_scratch = hidden_bytes * 2u + q_bytes + kv_bytes * 2u + attn_bytes + mlp_bytes;
    const size_t kv_span_meta = kv_tokens * sizeof(uint32_t);
    const size_t scratch_bytes = layer_scratch + hidden_bytes + kv_span_meta + 4096u;

    return termite_metal_decode_runtime_reserve(runtime, scratch_bytes, sizeof(uint32_t));
}

static int termite_metal_dispatch(termite_metal_provider *provider, id<MTLComputePipelineState> pipeline, const float *input, size_t rows, size_t in_dim, size_t row_blocks, const uint8_t *weight_raw, size_t weight_bytes, size_t out_dim, float *output) {
    if (provider == NULL || pipeline == nil || input == NULL || weight_raw == NULL || output == NULL) return -1;
    @autoreleasepool {
        const size_t input_bytes = rows * in_dim * sizeof(float);
        const size_t output_bytes = rows * out_dim * sizeof(float);
        id<MTLBuffer> input_buffer = [provider->device newBufferWithBytesNoCopy:(void *)input length:input_bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (input_buffer == nil) input_buffer = [provider->device newBufferWithBytes:input length:input_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> weight_buffer = [provider->device newBufferWithBytesNoCopy:(void *)weight_raw length:weight_bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (weight_buffer == nil) weight_buffer = [provider->device newBufferWithBytes:weight_raw length:weight_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> output_buffer = [provider->device newBufferWithBytesNoCopy:output length:output_bytes options:MTLResourceStorageModeShared deallocator:nil];
        // The output is write-only. When the caller allocation cannot be
        // wrapped directly, avoid snapshotting its uninitialized bytes into
        // Metal only to overwrite them before the required copy-back below.
        if (output_buffer == nil) output_buffer = [provider->device newBufferWithLength:output_bytes options:MTLResourceStorageModeShared];
        if (input_buffer == nil || weight_buffer == nil || output_buffer == nil) return -3;
        termite_metal_linear_params params = { .rows = (uint32_t)rows, .in_dim = (uint32_t)in_dim, .out_dim = (uint32_t)out_dim, .row_blocks = (uint32_t)row_blocks };
        id<MTLBuffer> params_buffer = [provider->device newBufferWithBytes:&params length:sizeof(params) options:MTLResourceStorageModeShared];
        if (params_buffer == nil) return -4;
        id<MTLCommandBuffer> command_buffer = termite_metal_new_command_buffer(provider->queue, __func__);
        if (command_buffer == nil) return -5;
        id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
        if (encoder == nil) return -6;
        [encoder setComputePipelineState:pipeline];
        [encoder setBuffer:input_buffer offset:0 atIndex:0];
        [encoder setBuffer:weight_buffer offset:0 atIndex:1];
        [encoder setBuffer:output_buffer offset:0 atIndex:2];
        [encoder setBuffer:params_buffer offset:0 atIndex:3];
        const NSUInteger total = rows * out_dim;
        MTLSize grid_size = MTLSizeMake(total, 1, 1);
        NSUInteger thread_width = pipeline.maxTotalThreadsPerThreadgroup;
        if (thread_width == 0) thread_width = 64;
        if (thread_width > total && total > 0) thread_width = total;
        MTLSize group_size = MTLSizeMake(thread_width, 1, 1);
        [encoder dispatchThreads:grid_size threadsPerThreadgroup:group_size];
        [encoder endEncoding];
        [command_buffer commit];
        [command_buffer waitUntilCompleted];
        if (command_buffer.status != MTLCommandBufferStatusCompleted) return -7;
        // newBufferWithBytes (the non-page-aligned fallback) snapshots the
        // caller's buffer instead of aliasing it, so results must be copied back.
        if (output_buffer.contents != (void *)output) memcpy(output, output_buffer.contents, output_bytes);
        return 0;
    }
}

static void termite_metal_provider_add_generated_quant_runtime_stats(termite_metal_provider *provider, const termite_metal_decode_runtime *runtime) {
    if (provider == NULL || runtime == NULL) return;
    for (size_t format_index = 0; format_index < TERMITE_METAL_GENERATED_QUANT_FORMAT_COUNT; format_index += 1) {
        for (size_t epilogue_index = 0; epilogue_index < TERMITE_METAL_GENERATED_QUANT_EPILOGUE_COUNT; epilogue_index += 1) {
            provider->antfly_generated_dispatch_counts[format_index][epilogue_index] += runtime->antfly_generated_dispatch_counts[format_index][epilogue_index];
        }
    }
}

static void termite_metal_provider_record_generated_quant_dispatch(termite_metal_provider *provider, uint32_t format, termite_metal_generated_quant_epilogue epilogue) {
    if (provider == NULL) return;
    if (epilogue == TERMITE_METAL_GENERATED_QUANT_EPILOGUE_NONE) return;
    const int format_index = termite_metal_generated_quant_format_index(format);
    const int epilogue_index = (int)epilogue;
    if (format_index < 0 || epilogue_index < 0 || epilogue_index >= TERMITE_METAL_GENERATED_QUANT_EPILOGUE_COUNT) return;
    provider->antfly_generated_dispatch_counts[format_index][epilogue_index] += 1;
}

static void termite_metal_provider_copy_exact_jit_pipelines(
    const termite_metal_provider *provider,
    termite_metal_decode_runtime *runtime
) {
    if (provider == NULL || runtime == NULL) return;
    for (size_t route = 0; route < TERMITE_METAL_JIT_EXACT_ROUTE_COUNT; ++route) {
        const size_t count = provider->jit_exact_pipeline_counts[route];
        if (count > TERMITE_METAL_JIT_EXACT_PIPELINES_PER_ROUTE) continue;
        for (size_t index = 0; index < count; ++index) {
            const termite_metal_jit_exact_pipeline_entry *source = &provider->jit_exact_pipelines[route][index];
            termite_metal_jit_exact_pipeline_entry *target = &runtime->jit_exact_pipelines[route][index];
            termite_metal_jit_exact_pipeline_entry_copy(source, target);
        }
        runtime->jit_exact_pipeline_counts[route] = (uint8_t)count;
    }
}

static uint8_t termite_metal_provider_bundled_quant_dispatch(
    const termite_metal_decode_runtime *runtime,
    uint32_t format,
    size_t in_dim,
    size_t out_dim
) {
    (void)in_dim;
    (void)out_dim;
    if (runtime == NULL) return TERMITE_METAL_QUANT_MATMUL_DISPATCH_UNKNOWN;
    if (format == TERMITE_METAL_QUANT_FORMAT_Q4_K) return TERMITE_METAL_QUANT_MATMUL_DISPATCH_SCALAR;
    if (format != TERMITE_METAL_QUANT_FORMAT_Q4_0) return TERMITE_METAL_QUANT_MATMUL_DISPATCH_UNKNOWN;
    // This helper reports route availability only.  Concrete row-one variant
    // policy is centralized in termite_metal_select_q4_0_mmv.
    return (runtime->q4_0_small_batch_r2_pipeline != nil ||
            runtime->q4_0_reduce_pipeline != nil ||
            runtime->q4_0_reduce_small_pipeline != nil)
        ? TERMITE_METAL_QUANT_MATMUL_DISPATCH_SMALL_BATCH
        : TERMITE_METAL_QUANT_MATMUL_DISPATCH_SCALAR;
}

static int termite_metal_dispatch_quant_matmul_none(termite_metal_provider *provider, termite_metal_decode_runtime *source_runtime, uint32_t format, id<MTLComputePipelineState> fallback_pipeline, const float *input, size_t rows, size_t in_dim, size_t values_per_block, size_t bytes_per_block, const uint8_t *weight_raw, size_t weight_bytes, size_t out_dim, float *output) {
    if (provider == NULL || input == NULL || weight_raw == NULL || output == NULL) return -1;
    @autoreleasepool {
        const size_t input_bytes = rows * in_dim * sizeof(float);
        const size_t output_bytes = rows * out_dim * sizeof(float);
        id<MTLBuffer> input_buffer = [provider->device newBufferWithBytesNoCopy:(void *)input length:input_bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (input_buffer == nil) input_buffer = [provider->device newBufferWithBytes:input length:input_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> weight_buffer = [provider->device newBufferWithBytesNoCopy:(void *)weight_raw length:weight_bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (weight_buffer == nil) weight_buffer = [provider->device newBufferWithBytes:weight_raw length:weight_bytes options:MTLResourceStorageModeShared];
        id<MTLBuffer> output_buffer = [provider->device newBufferWithBytesNoCopy:output length:output_bytes options:MTLResourceStorageModeShared deallocator:nil];
        if (output_buffer == nil) output_buffer = [provider->device newBufferWithBytes:output length:output_bytes options:MTLResourceStorageModeShared];
        if (input_buffer == nil || weight_buffer == nil || output_buffer == nil) return -3;
        id<MTLCommandBuffer> command_buffer = termite_metal_new_command_buffer(provider->queue, __func__);
        if (command_buffer == nil) return -5;
        id<MTLComputeCommandEncoder> encoder = termite_metal_tracked_compute_command_encoder(command_buffer);
        if (encoder == nil) return -6;
        termite_metal_decode_runtime runtime = {0};
        runtime.florence_q4_k_mm_enabled = source_runtime != NULL
            ? source_runtime->florence_q4_k_mm_enabled
            : 0;
        runtime.workload_profile_regime = source_runtime != NULL
            ? source_runtime->workload_profile_regime
            : TERMITE_METAL_WORKLOAD_REGIME_UNKNOWN;
        runtime.workload_profile_active = source_runtime != NULL
            ? source_runtime->workload_profile_active
            : 0;
        runtime.workload_profile_complete = 1;
        runtime.generated_quant_disabled = source_runtime != NULL
            ? source_runtime->generated_quant_disabled
            : NO;
        runtime.generated_quant_disabled_initialized = source_runtime != NULL
            ? source_runtime->generated_quant_disabled_initialized
            : NO;
        runtime.jit_generated_route_mask = provider->jit_generated_route_mask;
        memcpy(runtime.jit_qualified_shapes, provider->jit_qualified_shapes, sizeof(runtime.jit_qualified_shapes));
        memcpy(runtime.jit_qualified_shape_counts, provider->jit_qualified_shape_counts, sizeof(runtime.jit_qualified_shape_counts));
        termite_metal_provider_copy_exact_jit_pipelines(provider, &runtime);
        runtime.q2_k_pipeline = provider->q2_k_pipeline;
